function g(topic,nzLink,iDo,weDo,youDo,aos){return{topic,nzLink,iDo,weDo,youDo,aos:aos||[]}}
window.__WWU_TERM_DATA=window.__WWU_TERM_DATA||{};
window.__WWU_TERM_DATA[2]={1:{Monday:g("Tier 2 vocabulary: words for movement & action","Writing — Vocabulary (Knowledge & Practice): precise verbs eliminate vague movement words; students select verbs that convey manner and quality of movement, reducing reliance on weak constructions.",{title:"I Do — Swap the Vague Movement Verb",instruction:"Watch me swap plain movement verbs for precise ones that carry more information.",example:'"The man went down the street." → "The man <u>strode</u> down the street."',demonstration:'Went → strode, shuffled, sprinted, lurched. Each verb tells us HOW as well as that movement happened. "Strode" tells us purposeful, confident movement. "Shuffled" tells us tired or reluctant movement. One word replaces a verb + adverb.',tip:'Precise verbs eliminate the need for adverbs: "ran quickly" → "sprinted."'},{title:"We Do — Upgrade the Verb",instruction:"Upgrade the underlined verbs with more precise movement words.",sentences:["The bird <u>went</u> through the air.","She <u>moved</u> across the dance floor.","He <u>went</u> into the room."],prompt:'What does the precise verb tell us that "went" does not?'},{title:"You Do — Your Turn",instruction:"Replace each plain verb with the most precise one you can think of.",tasks:["The snake <u>went</u> through the grass.","The toddler <u>moved</u> towards the door.","She <u>went</u> across the rooftops.","✦ Bonus: Write 4 sentences each using a different precise movement verb. No two the same."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Precise verbs for movement",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Vocabulary is chosen deliberately for effect, so students consider the precision and connotations of words." Selecting a precise movement verb (strode, shuffled, lurched) rather than a generic one (went, moved) demonstrates Tier 2 vocabulary development — a core expectation at Years 5–6. Each verb carries manner, intent, and character without requiring additional adverbs.'},{code:"Writing — Vocabulary (Practice)",label:"Selecting verbs fit for purpose",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." This lesson builds the habit of interrogating verb choices — asking not just 'what is happening?' but 'exactly how is it happening?' — and finding the single word that answers both questions simultaneously.`}]),Tuesday:g("Nouns: collective & abstract nouns","Writing — Sentence Structure (Knowledge): nouns include common, proper, collective, and abstract types; understanding the full range of noun classes develops students' grammatical knowledge and expands their writing vocabulary.",{title:"I Do — Two Special Noun Types",instruction:"Collective nouns name a group. Abstract nouns name ideas, feelings, or concepts you cannot touch.",example:"Collective: a <u>flock</u> of birds | Abstract: <u>courage</u>, <u>freedom</u>, <u>justice</u>",demonstration:"Flock, swarm, pride, pod — these are collective. Justice, hope, anger — these are abstract. You can't hold justice in your hand, but it's a noun because it names a concept.",tip:"If you can't touch it or see it, but it's a thing — it's probably abstract."},{title:"We Do — Sort the Nouns",instruction:"Sort these nouns into collective, abstract, or concrete.",sentences:["a herd of cattle","curiosity","a bouquet of flowers","loyalty","a school of fish"],prompt:"How do you know? Could you take a photo of it? Touch it?"},{title:"You Do — Your Turn",instruction:"Label each noun: collective (C), abstract (A), or concrete (Co).",tasks:["a murder of crows —","envy —","a packet of biscuits —","a pride of lions —","determination —","✦ Bonus: Write a sentence for each type using a noun from today's lesson."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Word classes: collective & abstract nouns",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Words belong to different classes… nouns include common, proper, collective (naming a group), and abstract (naming a concept, idea, or emotion) types." Understanding the full range of noun classes deepens grammatical awareness and expands the vocabulary available to students when composing at Years 5–6.'},{code:"Writing — Vocabulary (Practice)",label:"Using abstract nouns for depth",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Using abstract nouns deliberately — courage, justice, determination — is a hallmark of sophisticated writing at Phase 2, allowing students to write about ideas and values, not just concrete events.'}]),Wednesday:g("Simple sentences: revisit with action-verb focus","Writing — Sentence Structure (Practice): students revisit simple sentence structure with a focus on replacing weak verb constructions (do/make/give + noun) with single powerful action verbs.",{title:"I Do — One Strong Verb Beats Three Weak Words",instruction:'Revisiting simple sentences — but this time the focus is on choosing a powerful action verb over a weak "do + noun" construction.',example:'Weak: "The volcano did an explosion." → Strong: "The volcano <u>erupted</u>."',demonstration:'"Do + noun" is often the weak version. Replace with a direct action verb: made a decision → decided. Gave a performance → performed. Did an investigation → investigated. Each replacement tightens the sentence and strengthens the verb.',tip:'"Did", "made", "gave", "had" + noun = usually replaceable with one strong verb.'},{title:"We Do — Find the Strong Verb",instruction:'Replace the weak "do + noun" construction with one strong verb.',sentences:["She made a complaint about the noise.","They did a celebration when they won.","He gave a performance that amazed the crowd."],prompt:"What single verb can replace each phrase?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence using one strong action verb.",tasks:["She made a decision to leave early.","The team gave a demonstration of the new skill.","They did an investigation into the disappearance.","✦ Bonus: Write 5 simple sentences using 5 different powerful action verbs."]},[{code:"Writing — Sentence Structure (Practice)",label:"Strong action verbs in simple sentences",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences" and to select verbs that convey meaning precisely. Replacing weak "do/make/give + noun" constructions with single powerful action verbs is a key revision skill — it tightens sentence structure and removes redundant words simultaneously.'},{code:"Writing — Vocabulary (Practice)",label:"Precise verb selection",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." This lesson reinforces that one exact verb (erupted, decided, investigated) is more powerful and precise than a vague verb + noun combination — a foundational principle of effective word choice at Phase 2.'}]),Thursday:g("Proofreading: capitals for proper nouns in context","Writing — Punctuation (Knowledge) & Writing Process (Practice): students apply capitalisation rules for proper nouns in complex, multi-sentence text, developing accuracy and consistency in editing.",{title:"I Do — Proper Nouns in Longer Text",instruction:"In this term's editing focus, we look specifically at proper noun capitals in longer, more complex text.",example:'"last tuesday, ms brown took class 5b to the otago museum in dunedin."',demonstration:'Fixed: "Last Tuesday, Ms Brown took Class 5B to the Otago Museum in Dunedin." Every specific name, title, day, place, and class identifier needs a capital.',tip:"Scan specifically for: days, months, place names, people's names/titles, specific event names."},{title:"We Do — Capital Letter Hunt",instruction:"Find and fix all the proper noun capitalisation errors.",sentences:["on anzac day, uncle mike and aunt sarah drove to hamilton for the dawn parade at memorial park."],prompt:"List every word that needs a capital. How many did you find?"},{title:"You Do — Your Turn",instruction:"Rewrite this passage with all proper noun capitals correctly placed.",tasks:["my cousin riya is visiting from tauranga next friday. she goes to otumoetai college and is in year 10. on saturday we're going to visit the national aquarium of new zealand in napier. riya wants to see the tuatara display and the kiwi house afterwards we might have lunch at the hawke's bay farmers market.","✦ Bonus: Write a paragraph about a real or imaginary trip. Include at least 6 proper nouns — all correctly capitalised."]},[{code:"Writing — Punctuation (Knowledge)",label:"Capitalisation: proper nouns in context",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "Capital letters are used at the start of sentences and for all proper nouns — names of specific people, places, days, months, titles, organisations, and events." At Phase 2, students are expected to apply this convention consistently across longer, more complex text where proper nouns appear frequently and in varied contexts.'},{code:"Writing — Writing Process (Practice)",label:"Editing for capitalisation accuracy",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking for correct capitalisation." This lesson trains the targeted scanning strategy — reading specifically for proper nouns — that helps students catch capitalisation errors they overlook in a general read-through.'}])},2:{Monday:g("Commas after fronted adverbials","Writing — Punctuation (Knowledge & Practice): a fronted adverbial is followed by a comma; students apply this convention accurately and understand why the comma signals a pause before the main clause.",{title:"I Do — The Opener Comma",instruction:"When a sentence starts with an adverbial phrase or clause (a fronted adverbial), we put a comma after it before the main clause begins.",example:'"<u>After the long match,</u> the players collapsed on the grass." | "<u>During the school holidays,</u> we visited Rotorua."',demonstration:'"After the long match" is the fronted adverbial — it sets the scene. The comma after "match" separates it from the main clause. Without the comma, the reader rushes past the opener without pausing.',tip:"Read aloud. If you naturally pause after the opening phrase before the subject arrives — that pause is your comma."},{title:"We Do — Add the Comma",instruction:"These sentences have fronted adverbials but are missing the comma. Find the opener and add the comma.",sentences:["Before the sun had risen the fishing boats left the harbour.","On the last day of term the students performed their assembly item.","Despite the heavy rain the match went ahead as planned."],prompt:"Where does the fronted adverbial end and the main clause begin? That's where the comma goes."},{title:"You Do — Your Turn",instruction:"Add the missing comma to each sentence and write the type of fronted adverbial (time/place/contrast).",tasks:["Throughout the long journey south the waka stayed on course.","Although the trail was steep the tamariki kept climbing.","By the time the tide turned the divers were already back on shore.","✦ Bonus: Write 5 sentences that each begin with a different type of fronted adverbial. Use at least one time, one place, and one contrast opener."]},[{code:"Writing — Punctuation (Knowledge)",label:"Comma after fronted adverbials",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "When an adverbial word, phrase, or clause is placed before the subject at the start of a sentence (a fronted adverbial), a comma is used to separate it from the main clause." This is a specific and frequently tested punctuation convention at Years 5–6, appearing across narrative, recount, and persuasive writing.'},{code:"Writing — Punctuation (Practice)",label:"Applying fronted adverbial comma",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." The comma after a fronted adverbial is both a convention (accuracy) and a craft tool (effect) — it signals a deliberate pause that gives the opener its weight. This lesson builds the read-aloud checking strategy: the natural pause reveals where the comma belongs.'}]),Tuesday:g("Future tense: will & going to",'Writing — Sentence Structure (Knowledge): the future tense is expressed using "will" or "going to"; the choice between them carries different shades of meaning — spontaneous decisions vs planned intentions.',{title:"I Do — Two Ways to Talk About the Future",instruction:'English expresses future time in two main ways: "will" + verb, and "going to" + verb. They are not always interchangeable. Watch me use each one and explain the difference.',example:'"I <u>will</u> help you with that." (spontaneous decision) | "We <u>are going to</u> plant native trees next month." (planned intention)',demonstration:`"Will" is used for spontaneous decisions, offers, predictions, and promises made at the moment of speaking. "Going to" is used for plans already decided and for predictions based on current evidence. "Look at those clouds — it's going to rain." (evidence right there).`,tip:"Planned ahead → going to. Decided right now → will. Evidence in front of you → going to."},{title:"We Do — Will or Going To?",instruction:'Choose "will" or "going to" and explain why.',sentences:["The marae committee ___ (will/is going to) hold a hui next Saturday — it's been in the calendar for months.",`"I can't carry that box." "Don't worry, I ___ (will/am going to) help you."`,"Look at those storm clouds — the weather ___ (will/is going to) turn soon."],prompt:"Is this a plan, a spontaneous offer, or a prediction based on evidence?"},{title:"You Do — Your Turn",instruction:"Complete each sentence with the correct future form. Write a brief reason for your choice.",tasks:["The school ___ (will/is going to) hold a matariki celebration — we've been practising for weeks.",'"The printer is broken." "I ___ (will/am going to) fix it." (spontaneous offer)',"That kūmara plant ___ (will/is going to) need water soon — the soil is bone dry.",`✦ Bonus: Write a paragraph of 5 sentences about a future event you're genuinely planning. Use "going to" for plans and "will" for predictions or promises within it.`]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Future tense: will & going to",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "The future tense in English is expressed using 'will' + verb (for spontaneous decisions, offers, and promises) or 'going to' + verb (for pre-planned intentions and predictions based on present evidence). Understanding the distinction allows writers to express future time with precision rather than using the two forms interchangeably."`},{code:"Writing — Sentence Structure (Practice)",label:"Using future tense accurately",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences" using a range of tenses accurately. Choosing between "will" and "going to" is a nuanced grammar decision that requires students to consider the context and intended meaning — a marker of grammatical sophistication at Years 5–6.'}]),Wednesday:g("Compound sentences: new contexts & conjunctions","Writing — Sentence Structure (Practice): students use FANBOYS conjunctions in new writing contexts — recount, report, and argument — understanding that the same conjunction carries different weight depending on purpose and audience.",{title:"I Do — FANBOYS in Fresh Contexts",instruction:"We know FANBOYS conjunctions (for, and, nor, but, or, yet, so). This week we use them in new writing contexts to see how the same conjunction does different jobs.",example:'Recount: "We arrived at Tāmaki Makaurau, <u>and</u> the whole whānau was waiting." | Argument: "The policy is popular, <u>yet</u> the evidence does not support it."',demonstration:'"And" adds. "But/yet" contrasts. "So" shows result. "Or" gives alternatives. "For" gives reason (formal). "Nor" adds a negative. The conjunction you choose shapes the relationship between the two ideas.',tip:"Before picking a conjunction, decide: am I adding, contrasting, showing a result, or giving a reason? That decides which FANBOYS fits."},{title:"We Do — Choose the Right FANBOYS",instruction:"Join each pair of sentences with the best FANBOYS conjunction. Add a comma before the conjunction.",sentences:["The hīkoi had been going for three days. The marchers showed no sign of stopping.","You can present your findings as a poster. You can create a short video.","The experiment failed the first time. The team learnt something valuable from it."],prompt:"What is the relationship between the two ideas? That decides the conjunction."},{title:"You Do — Your Turn",instruction:"Write a compound sentence for each context using the conjunction given.",tasks:['Write about a kaitiakitanga project using "so."','Write about a time something went wrong using "yet."','Write a sentence giving someone two choices using "or."',"✦ Bonus: Write a paragraph about an environmental issue. Use at least three different FANBOYS conjunctions. Underline each one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"FANBOYS in varied contexts",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Coordinating conjunctions (for, and, nor, but, or, yet, so) join two independent clauses of equal grammatical weight. Each conjunction signals a different relationship: addition (and), contrast (but/yet), result (so), alternative (or), reason (for), negative addition (nor)." Students learn that the same conjunction carries different register and weight depending on text type and context.'},{code:"Writing — Sentence Structure (Practice)",label:"Compound sentences across text types",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity" across different text types. This lesson extends compound sentence use beyond narrative into recount, report, and argument — building students' ability to select the right conjunction for the relationship and context, not just the first one that fits grammatically.`}]),Thursday:g("Editing: fixing comma splices","Writing — Punctuation (Knowledge) & Writing Process (Practice): a comma splice joins two independent clauses with only a comma; students identify comma splices and correct them using a full stop, semicolon, or conjunction.",{title:"I Do — The Comma That Tries to Do Too Much",instruction:"A comma splice is when two complete sentences are joined with just a comma. A comma is not strong enough to hold two independent clauses together on its own. Watch me find and fix one.",example:'✗ "The waka was ready, the crew climbed aboard." → ✓ "The waka was ready. The crew climbed aboard." OR ✓ "The waka was ready, and the crew climbed aboard." OR ✓ "The waka was ready; the crew climbed aboard."',demonstration:"Three fixes: (1) full stop — two separate sentences. (2) comma + conjunction — compound sentence. (3) semicolon — joins two closely related sentences. All three are correct. Choose based on the relationship between the ideas.",tip:"Test: read each side of the comma. If both could stand alone as sentences — the comma is a splice. Fix it."},{title:"We Do — Fix the Splice",instruction:"Find the comma splice in each sentence and fix it three ways.",sentences:["The tide was coming in, we had to leave quickly.","She had been training for months, the race was finally here."],prompt:"Which fix sounds best for each sentence? Does the relationship between the ideas affect your choice?"},{title:"You Do — Your Turn",instruction:"Fix each comma splice using the method shown in brackets.",tasks:["The kākāpō is critically endangered, conservation efforts have helped increase numbers. [semicolon]","The hail hammered the roof, everyone moved away from the windows. [conjunction]","She had practised the speech a hundred times, she still felt her hands shake. [full stop]","✦ Bonus: Write 3 pairs of sentences — then deliberately create a comma splice, and fix it in two different ways each time."]},[{code:"Writing — Punctuation (Knowledge)",label:"Comma splices",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "A comma splice occurs when two independent clauses are joined with only a comma, which is insufficient punctuation. It can be corrected by: (1) replacing the comma with a full stop; (2) adding a coordinating conjunction after the comma; or (3) replacing the comma with a semicolon." Understanding comma splices deepens students' knowledge of sentence boundaries and punctuation function.`},{code:"Writing — Writing Process (Practice)",label:"Identifying and correcting comma splices",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Recognising and fixing comma splices is a targeted editing skill that requires students to identify sentence boundaries and select the punctuation or conjunction that best expresses the relationship between the two clauses.'}])},3:{Monday:g("Antonyms & shades of meaning","Writing — Vocabulary (Knowledge): antonyms are words with opposite meanings; understanding the spectrum between antonyms develops nuanced vocabulary and helps students select words with the right shade of meaning.",{title:"I Do — The Meaning Spectrum",instruction:"Antonyms are opposites — but between most opposites there's a whole spectrum of words. Understanding that spectrum lets you choose exactly the right word for your meaning.",example:`hot ←——————————————→ cold
scalding / burning / warm / tepid / cool / chilly / freezing / arctic`,demonstration:'"Hot" and "cold" are antonyms, but the spectrum between them has eight gradations. "The water was cold" is vague. "The water was arctic" is precise. Choosing from the spectrum — rather than defaulting to the antonym — gives writing its precision and texture.',tip:"Before writing a describing word, ask: where on the spectrum between the two extremes does this fall? Then find the word that sits exactly there."},{title:"We Do — Build the Spectrum",instruction:"Build meaning spectrums for each pair of antonyms. Aim for at least five words between the two extremes.",sentences:["happy ←—————————→ sad","loud ←—————————→ quiet","fast ←—————————→ slow"],prompt:"Which word on the spectrum best describes: a library, a sports crowd, a funeral? Why?"},{title:"You Do — Your Turn",instruction:"Choose the word from the spectrum that best fits each context. Explain your choice.",tasks:["The old man's voice was ___ (choose from: booming / loud / clear / soft / faint / inaudible) as he told the story.","After the marathon, the runner felt ___ (choose from: exhausted / tired / weary / drained / spent / destroyed).","The stream moved ___ (choose from: rushing / flowing / trickling / seeping / still) through the valley.","✦ Bonus: Choose one antonym pair. Build a spectrum of 8 words. Then use three of them in three separate sentences about the same setting."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Antonyms & meaning spectrums",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "The meaning of words can be extended or changed by context; vocabulary is chosen deliberately for effect, so students consider the connotations and precision of words." Understanding antonyms and the spectrum of meaning between them is a key component of Tier 2 vocabulary development — it moves students beyond binary word choice (hot/cold) to nuanced selection along a continuum.'},{code:"Writing — Vocabulary (Practice)",label:"Selecting words for precision",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases, including subject-specific vocabulary, that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson develops the habit of asking 'exactly where on the spectrum does this fall?' before committing to a word — the key discipline of precise vocabulary selection.`}]),Tuesday:g("Subject-verb agreement: tricky cases (everyone, each)","Writing — Sentence Structure (Knowledge): indefinite pronouns such as everyone, each, neither, and someone are grammatically singular and require singular verb forms, even when they refer to multiple people.",{title:"I Do — The Tricky Singular Words",instruction:"Most subject-verb agreement is straightforward. But some words look plural and feel plural yet are grammatically singular.",example:'"<u>Everyone</u> in the two classes <u>was</u> invited." (not "were") | "<u>Each</u> of the players <u>has</u> a number." (not "have")',demonstration:'"Everyone," "everybody," "someone," "nobody," "each," "either," "neither" — all singular, even when they refer to many people. The trick: mentally replace with "every single person" — then the singular verb feels natural.',tip:'Everyone/each/either/neither/nobody = singular. Replace with "every single one" in your head — the right verb follows naturally.'},{title:"We Do — Choose the Right Verb",instruction:"Choose the correct verb form for each sentence.",sentences:["Everyone in the kapa haka group ___ (know/knows) the words.","Each of the entries ___ (was/were) judged on three criteria.","Neither of the referees ___ (was/were) happy with the decision."],prompt:'Replace the subject with "every single one" — which verb sounds right now?'},{title:"You Do — Your Turn",instruction:"Correct the subject-verb agreement error in each sentence.",tasks:["Everyone in the syndicate have submitted their work.","Each of the kūmara plants were carefully watered.","Neither of the answers are correct.","Somebody have left their bag on the mat.","✦ Bonus: Write 5 sentences, each using one of these subjects: everyone, each, neither, somebody, anyone. Make sure agreement is correct in every one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"SVA: indefinite pronouns",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Indefinite pronouns (everyone, everybody, someone, nobody, each, either, neither) are grammatically singular and require singular verb forms, even when they refer to multiple people or things. Errors in agreement with these pronouns are among the most common grammar mistakes at Years 5–6." Students learn to override the "feels plural" instinct by testing with "every single one."'},{code:"Writing — Writing Process (Practice)",label:"Editing for tricky SVA",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Identifying and correcting tricky subject-verb agreement errors — particularly with indefinite pronouns — requires students to understand the grammatical subject of the clause, not just the nearest noun, and is a key editing skill at Phase 2.'}]),Wednesday:g('Expanding sentences using "when" and "because"','Writing — Sentence Structure (Practice): students expand simple sentences by adding subordinate clauses using "when" and "because" to show time relationships and causation.',{title:"I Do — Add the Why and the When",instruction:'Two of the most useful subordinating conjunctions for expanding sentences are "when" (time) and "because" (cause/reason). Watch me use them to transform bare sentences.',example:'Base: "The crowd cheered." → + when: "The crowd cheered <u>when the final whistle blew</u>." → + because: "The crowd cheered <u>because the home team had just equalised</u>."',demonstration:'"When" tells us the time — the moment the action happened. "Because" tells us the cause — why it happened. Each adds a whole new layer of meaning to the same simple sentence. I can also put the "when/because" clause first: "When the final whistle blew, the crowd cheered."',tip:'"When" answers: at what moment? "Because" answers: for what reason? Add the one your sentence is missing.'},{title:"We Do — Expand Together",instruction:'Expand each sentence by adding a "when" clause AND a "because" clause. Try both.',sentences:["The pohutukawa bloomed.","The students fell silent.","The explorer turned back."],prompt:"Which expansion is more interesting for each sentence — the when or the because? Why?"},{title:"You Do — Your Turn",instruction:"Expand each sentence with the conjunction shown. Try putting the clause at the start AND at the end.",tasks:["The river flooded. [because]","The kiwi came out. [when]","She changed her mind. [because]","The lights went out. [when]",'✦ Bonus: Write a paragraph of 5 sentences. Use "when" in at least two and "because" in at least two. Vary whether the clause comes first or last.']},[{code:"Writing — Sentence Structure (Practice)",label:'Expanding with "when" & "because"',detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand simple sentences by adding words, phrases, and clauses to add detail and description," including using subordinating conjunctions to express time (when) and cause (because). This lesson revisits and deepens Term 1 complex sentence work in a fresh context, reinforcing that clause order is flexible and that the fronted version requires a comma.'},{code:"Writing — Sentence Structure (Knowledge)",label:"Subordinating conjunctions: time & cause",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "'When' is a subordinating conjunction that introduces a clause expressing time; 'because' introduces a clause expressing cause or reason. Both create complex sentences where one clause depends on the other for full meaning." Understanding the semantic difference between these two conjunctions helps students choose the right one for the relationship they want to express.`}]),Thursday:g("Editing: upgrading bland verbs in a passage","Writing — Vocabulary (Practice) & Writing Process (Practice): students identify weak, overused verbs in a passage and replace them with precise verbs that carry meaning, character, and energy.",{title:"I Do — Bland Verbs Drain Energy",instruction:"Some verbs are so vague they tell us almost nothing: went, got, said, did, made, was. Watch me identify them in a passage and replace them with verbs that do real work.",example:'"The children <u>went</u> to the beach. They <u>got</u> into the water. Dad <u>said</u> they should come out."',demonstration:'"went" → "raced" | "got" → "plunged" | "said" → "bellowed". New version: "The children <u>raced</u> to the beach. They <u>plunged</u> into the water. Dad <u>bellowed</u> at them to come out." The scene comes alive.',tip:'Highlight every "went," "got," "said," "did," "made," "was" in a passage. Each one is an upgrade opportunity.'},{title:"We Do — Upgrade the Passage",instruction:"Replace every underlined bland verb with a more precise one. The new verb must match the context.",sentences:["The kererū <u>went</u> from branch to branch, <u>getting</u> the ripest berries. It <u>made</u> a loud noise with its wings as it <u>went</u> away."],prompt:`What is actually happening physically? What does a precise verb tell the reader that "went" and "got" don't?`},{title:"You Do — Your Turn",instruction:"Rewrite this passage, upgrading every bland verb you can find.",tasks:["On field trip day, the class got on the bus early. They went to the wetland reserve near Ōtaki. The guide said something about the different birds. Some students went into the hide and got photos of a bittern. Everyone said it was great.","✦ Bonus: Count how many bland verbs you replaced. Write the before and after side by side. Which passage is more engaging and why?"]},[{code:"Writing — Vocabulary (Practice)",label:"Upgrading bland verbs",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson targets the most common verb weakness in Years 5–6 writing — overuse of generic verbs (went, got, said) — and builds the habit of asking 'what is ACTUALLY happening?' before selecting a more precise alternative.`},{code:"Writing — Writing Process (Practice)",label:"Verb audit in revision",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The verb audit — highlighting every weak verb and asking if it can be upgraded — is a targeted revision strategy that directly improves the energy and precision of students' writing at Phase 2.`}])},4:{Monday:g("Apostrophes for contraction","Writing — Punctuation (Knowledge): a contraction apostrophe replaces omitted letters when two words are joined; students apply contraction apostrophes accurately and distinguish them from possessive apostrophes.",{title:"I Do — The Apostrophe That Replaces Letters",instruction:"A contraction apostrophe shows where one or more letters have been removed when two words are joined together.",example:`"do not" → "don't" (the apostrophe replaces the 'o') | "they are" → "they're" | "I would" → "I'd"`,demonstration:`"cannot" → "can't" — the apostrophe replaces "no". "would not" → "wouldn't" — replaces "o". "she is" → "she's" — replaces "i". The apostrophe sits exactly where the missing letters were.`,tip:"The apostrophe goes WHERE THE LETTERS WERE REMOVED — not just anywhere between the words."},{title:"We Do — Contract and Expand",instruction:"Write the contraction for each pair of words, and expand each contraction back to the full form.",sentences:["we will → ___  |  it's → ___","have not → ___  |  they'd → ___","I am → ___  |  couldn't → ___"],prompt:`Exactly which letters did the apostrophe replace? Could you be confused between "it's" (it is) and "its" (belonging to it)?`},{title:"You Do — Your Turn",instruction:"Fix the apostrophe errors in these sentences — some are missing, some are in the wrong place.",tasks:["Sh'es not sure if theyre coming to the hangi tonight.","I wo'nt be ready until the bus ha's already left.","Weve been waiting here for ages — it isnt fair.","They're dog isnt allowed inside but its a cold night.","✦ Bonus: Write a conversation (6 lines of dialogue) between two friends making plans. Use at least 6 different contractions correctly."]},[{code:"Writing — Punctuation (Knowledge)",label:"Contraction apostrophes",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "A contraction apostrophe replaces the letter or letters omitted when two words are combined (e.g. do not → don't, they are → they're, I would → I'd). The apostrophe is placed exactly where the letters were removed." Students also practise distinguishing contraction apostrophes from possessive apostrophes — a critical and frequently confused distinction at Years 5–6.`},{code:"Writing — Punctuation (Practice)",label:"Applying contraction apostrophes accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including apostrophes for contraction. The key test — expanding the contraction to check whether the apostrophe placement makes sense — gives students a reliable self-checking strategy they can apply independently when editing their own writing.'}]),Tuesday:g("Relative pronouns: who, which, that","Writing — Sentence Structure (Knowledge): relative pronouns (who, which, that) introduce relative clauses that give additional information about a noun; the choice of pronoun and use of commas depends on whether the clause defines or adds extra information.",{title:"I Do — Clauses That Give Extra Information",instruction:`A relative clause is a type of subordinate clause that gives more information about a noun. It's introduced by a relative pronoun: "who" (for people), "which" (for things), "that" (for people or things in defining clauses).`,example:'"The woman <u>who won the award</u> is our neighbour." | "The bridge<u>, which was built in 1902,</u> is being restored." | "The book <u>that she recommended</u> was brilliant."',demonstration:'"who" → refers back to a person. "which" → refers back to a thing, adds non-essential info (use commas): "The river, which floods every winter, is rising again." "that" → defines which one (no commas): "The path that leads to the pā is steep."',tip:'"Who" = people. "Which" = things + commas (extra info). "That" = defines which one, no commas.'},{title:"We Do — Choose the Right Relative Pronoun",instruction:"Complete each sentence with who, which, or that.",sentences:["The rangatira ___ led the iwi was known for her wisdom.","The old pōhutukawa, ___ had stood for 300 years, was finally protected.","This is the exact track ___ leads to the summit."],prompt:"Does the clause define which one, or add extra information? Does it refer to a person or a thing?"},{title:"You Do — Your Turn",instruction:"Add a relative clause to each sentence using the pronoun given.",tasks:["The scientist ___ (who) discovered the new species published her findings last month.","Rotorua, ___ (which) is famous for its geothermal activity, attracts tourists year-round.","She finally found the notebook ___ (that) she had been searching for all morning.","✦ Bonus: Write a paragraph about a local place or person. Include at least three relative clauses — one with who, one with which (with commas), and one with that."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Relative pronouns & relative clauses",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Relative pronouns (who, which, that) introduce relative clauses that modify a noun. 'Who' refers to people; 'which' refers to things and introduces non-defining (parenthetical) clauses set off with commas; 'that' introduces defining clauses with no commas." Mastering this distinction is a key grammar milestone at Phase 2, with direct implications for comma use.`},{code:"Writing — Sentence Structure (Practice)",label:"Using relative clauses for detail",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding clauses to add detail and description." Relative clauses are a sophisticated tool for embedding additional information about a noun within a sentence — avoiding the need for a separate sentence and creating more fluent, complex writing at Years 5–6.'}]),Wednesday:g("Topic sentences for persuasive paragraphs","Writing — Text Structure (Knowledge & Practice): persuasive topic sentences state a clear position or claim; students write topic sentences that introduce the paragraph argument and signal the writer's stance.",{title:"I Do — Topic Sentences That Argue",instruction:"In Term 1 we wrote topic sentences for informational paragraphs. This week, topic sentences carry an opinion or argument — they tell the reader not just what the paragraph is about, but what position you're taking.",example:'Informational: "Recycling reduces waste sent to landfill." | Persuasive: "<u>Recycling is not enough — we must stop producing unnecessary plastic altogether.</u>"',demonstration:`The persuasive topic sentence does three jobs: (1) introduces the paragraph's main idea, (2) makes the writer's position clear, (3) makes the reader want to know the evidence. "Everyone deserves access to clean water" is both a topic sentence AND an argument.`,tip:"A strong persuasive topic sentence takes a clear position. If someone could disagree with it — it's persuasive. If it's just a fact — it's informational."},{title:"We Do — Upgrade to Persuasive",instruction:"Turn each informational topic sentence into a persuasive one by adding a position or claim.",sentences:["Smartphones are used by many young people.","Schools have canteens that sell food to students.","Exercise has effects on health."],prompt:"What position could a writer take on each topic? Add the opinion to make it genuinely persuasive."},{title:"You Do — Your Turn",instruction:"Write a persuasive topic sentence for each argument prompt.",tasks:["Topic: whether students should have homework.","Topic: whether animals should be kept in zoos.","Topic: whether Aotearoa should have a four-day school week.","✦ Bonus: Choose one topic and write the full paragraph — topic sentence + at least two pieces of evidence or reasoning."]},[{code:"Writing — Text Structure (Knowledge)",label:"Persuasive topic sentences",detail:`NZC Phase 2 Writing — Text Structure (Knowledge): "In persuasive writing, each paragraph is organised around a claim or position introduced in the topic sentence. A persuasive topic sentence makes the writer's stance clear and invites the reader to consider the supporting evidence that follows." Students learn that a topic sentence in argument writing must be contestable — if no one could disagree with it, it is not yet persuasive.`},{code:"Writing — Text Structure (Practice)",label:"Structuring persuasive paragraphs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail" across a range of text types including persuasion. This lesson builds the skill of leading with a clear position before providing evidence — a structural discipline that is foundational to effective persuasive writing at Phase 2.'}]),Thursday:g("Editing: removing unnecessary apostrophes","Writing — Punctuation (Knowledge) & Writing Process (Practice): apostrophes are not used to form plurals; students identify and remove apostrophes used incorrectly in plural nouns.",{title:"I Do — The Apostrophe That Shouldn't Be There",instruction:"One of the most common apostrophe errors is using one to make a word plural. Apostrophes are NEVER used for plurals — only for possession and contraction. Watch me find and fix the errors.",example:`✗ "We have three cat's and two dog's." → ✓ "We have three cats and two dogs."`,demonstration:`"Cat's" — is the cat possessing something? No. Is it a contraction? No. So no apostrophe! "Dog's" — same test, same result. The simple rule: to make a word plural, just add -s or -es. Never add an apostrophe.`,tip:"Before adding an apostrophe, ask: is this possession or contraction? If neither — no apostrophe."},{title:"We Do — Find and Remove",instruction:"Remove every incorrect apostrophe from this passage.",sentences:["At the market we bought apple's, pear's, and two kind's of cheese. The stall's were busy all morning and the seller's were friendly. By noon, all the basket's were empty."],prompt:"Which apostrophes are wrong? How do you know? What test did you apply?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence, correcting all apostrophe errors. Some sentences may have no error.",tasks:["The team's jerseys were hanging on hook's in the changing room.","Both runner's crossed the line within second's of each other.","The children's laughter echoed across the playground.","Three dog's barked at the cat's on the fence.","✦ Bonus: Write 5 sentences that correctly use apostrophes for possession, contraction, and plural — making sure plurals never have apostrophes."]},[{code:"Writing — Punctuation (Knowledge)",label:"Apostrophes: not for plurals",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "Apostrophes are used to show possession and to mark omitted letters in contractions. They are never used to form plurals. The 'greengrocer's apostrophe' (apple's, pear's) is one of the most common punctuation errors in English." Students develop the two-question test: Is this possession? Is this a contraction? If neither — no apostrophe.`},{code:"Writing — Writing Process (Practice)",label:"Editing for apostrophe errors",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking punctuation." This lesson builds a targeted apostrophe audit: applying the possession/contraction test to every apostrophe in a passage and removing those that fail both tests — a practical and reliable editing strategy.'}])},5:{Monday:g("Brackets & dashes for parenthetical information","Writing — Punctuation (Knowledge): brackets and dashes are used to add parenthetical (non-essential) information within a sentence; students choose between them based on the degree of emphasis and formality required.",{title:"I Do — The Aside in a Sentence",instruction:"Sometimes we want to add extra information inside a sentence without breaking its flow. Brackets and dashes both do this job — but with different emphasis. Watch me use both.",example:'Brackets: "The tūī (a native honeyeater) feeds on kōwhai nectar." | Dashes: "The tūī — our boldest garden visitor — feeds on kōwhai nectar."',demonstration:"Brackets add a quiet aside — the reader can almost skip it. Dashes shout for attention — they make the parenthetical feel dramatic or important. Use brackets for factual clarifications. Use dashes when you want the reader to pause and notice.",tip:"Remove the parenthetical — does the sentence still make sense? Good — it's truly parenthetical. Now choose: quiet (brackets) or dramatic (dashes)?"},{title:"We Do — Choose the Right Mark",instruction:"For each sentence, decide whether brackets or dashes are more appropriate. Add them correctly.",sentences:["The pōhutukawa also called the New Zealand Christmas tree blooms in December.","The final score 14 to 12 in our favour was the best result of the season.","Captain Cook who arrived in 1769 was the first European to chart New Zealand's coastline."],prompt:"Is this extra information quiet and factual, or dramatic and emphatic? That decides the mark."},{title:"You Do — Your Turn",instruction:"Add brackets or dashes to each sentence. Write a reason for your choice.",tasks:["The Whanganui River legally recognised as a person in 2017 is sacred to the Māori people.","My brother the one who never reads finished the whole novel in a weekend.","Mount Taranaki also known as Egmont is one of New Zealand's most symmetrical volcanoes.","✦ Bonus: Write 4 sentences of your own — two using brackets and two using dashes. Make sure the parenthetical is genuinely non-essential in each."]},[{code:"Writing — Punctuation (Knowledge)",label:"Brackets & dashes for parentheticals",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "Brackets and dashes are used to add parenthetical (non-essential) information within a sentence. Brackets indicate quiet, factual asides; dashes create emphasis and draw attention to the additional information. Both marks come in pairs, and the sentence must make grammatical sense if the parenthetical is removed." This is an explicitly expected Phase 2 punctuation skill.'},{code:"Writing — Punctuation (Practice)",label:"Using parenthetical punctuation for effect",detail:`NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." Choosing between brackets and dashes is a purposeful punctuation decision — not a random one. This lesson teaches students that punctuation shapes the reader's experience of additional information: brackets whisper, dashes shout. That awareness is the foundation of punctuation as a craft tool.`}]),Tuesday:g("Comparative & superlative adjectives","Writing — Sentence Structure (Knowledge): comparative adjectives compare two things; superlative adjectives compare three or more; students apply the rules for regular and irregular forms accurately.",{title:"I Do — More, Most, -er, -est",instruction:"Comparative adjectives compare two things. Superlative adjectives compare three or more. Short adjectives add -er/-est; longer adjectives use more/most; some are irregular.",example:"fast → faster → fastest | beautiful → more beautiful → most beautiful | good → better → best",demonstration:'Rule: 1–2 syllable adjectives → -er/-est: tall/taller/tallest. 3+ syllable adjectives → more/most: exciting/more exciting/most exciting. Exceptions: good/better/best, bad/worse/worst, far/further/furthest. Test: if "-er" sounds natural — use it.',tip:'Try adding -er: if it sounds natural, use it. If it sounds awkward ("intelligenter?"), use "more."'},{title:"We Do — Form the Comparatives",instruction:"Form the comparative and superlative of each adjective and use each in a sentence.",sentences:["cold → ___ → ___","dangerous → ___ → ___","good → ___ → ___"],prompt:"Which rule applies? Are there any exceptions here? Can you use each in an example sentence?"},{title:"You Do — Your Turn",instruction:"Complete the comparison chart and write sentences using the correct form.",tasks:['happy → ___ → ___  |  Use "happiest" in a sentence.','mysterious → ___ → ___  |  Use "more mysterious" in a sentence.','bad → ___ → ___  |  Use "worst" in a sentence.',"✦ Bonus: Write a paragraph comparing two animals, using at least four comparative or superlative adjectives."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Comparative & superlative adjectives",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Adjectives can be modified to express degrees of comparison. Comparative forms (using -er or 'more') compare two things; superlative forms (using -est or 'most') compare three or more. Some adjectives have irregular comparative and superlative forms (good/better/best, bad/worse/worst)." Students learn and apply both the rules and the exceptions.`},{code:"Writing — Vocabulary (Practice)",label:"Precise comparative language",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Using precise comparative and superlative forms — rather than vague modifiers ("more good," "more bad") — is a key marker of vocabulary accuracy at Years 5–6. This lesson also reinforces that form choice follows a rule, not guesswork.'}]),Wednesday:g("Combining short sentences for variety","Writing — Sentence Structure (Practice): students combine multiple short sentences into smoother compound and complex sentences, eliminating choppiness and creating better flow.",{title:"I Do — Stitch the Choppy Sentences",instruction:"Too many short sentences in a row creates choppy, monotonous writing. Watch me combine short sentences into longer, smoother ones using conjunctions, relative clauses, and participial phrases.",example:'Choppy: "The kererū landed. It ate the berries. It flew away. It was very fast." → Smooth: "The kererū landed, ate the berries, and flew away with surprising speed."',demonstration:'I combined four sentences into one by removing repeated subjects and joining the actions with commas and "and." I also replaced "very fast" with "surprising speed" — more precise and vivid. The rhythm is now smooth rather than clipped.',tip:"If three or more sentences in a row are short and start with the same subject — they can probably be combined."},{title:"We Do — Combine Together",instruction:"Combine each group of short sentences into one or two smooth sentences.",sentences:["The storm arrived quickly. The wind was strong. Trees bent. Branches snapped.","She practised every day. She was nervous. The performance was coming soon."],prompt:"Which sentences share a subject and can be combined? Which conjunction or relative clause best links the ideas?"},{title:"You Do — Your Turn",instruction:"Combine each group into one well-constructed sentence.",tasks:["The kaiako walked in. She smiled. She placed a pile of books on the desk. She waited.","The volcano was silent. It had been silent for years. Scientists were watching it. They were worried.","The dog sat by the door. It was whining. It wanted to go outside. It had been waiting for an hour.","✦ Bonus: Find a paragraph in your own writing that has more than three consecutive short sentences. Combine at least two pairs."]},[{code:"Writing — Sentence Structure (Practice)",label:"Combining sentences for flow",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity," including combining short sentences to improve rhythm and flow. Eliminating choppy repetition by merging sentences with conjunctions, relative clauses, and shared verb phrases is a key revision skill at Years 5–6 — it shows control over sentence construction, not just sentence production.'},{code:"Writing — Writing Process (Practice)",label:"Revising for sentence variety",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson practises a specific revision strategy: identifying runs of short sentences, diagnosing why they feel choppy, and selecting the best combining method — conjunction, relative clause, or shared verb chain.'}]),Thursday:g("Peer editing: punctuation variety","Writing — Writing Process (Practice): students apply a punctuation variety checklist to their own and a partner's writing, giving and receiving specific feedback on comma, colon, semicolon, and dash use.",{title:"I Do — Reading for Punctuation Variety",instruction:"Today I'm going to show you how to read a piece of writing specifically to assess its punctuation variety — not just accuracy.",example:"Checklist: ☐ At least one comma after a fronted adverbial ☐ At least one colon ☐ At least one semicolon ☐ At least one pair of brackets or dashes ☐ No comma splices",demonstration:`I read the passage once for meaning. Then I read again specifically for punctuation. I mark each type I find. I notice what's missing. Then I give specific feedback: "You've used commas well in lists, but there are no semicolons — try joining two of these related sentences with one."`,tip:'Specific feedback is helpful. "Your punctuation is good" is not. "You need a comma after your fronted adverbial on line 2" is.'},{title:"We Do — Punctuation Variety Audit",instruction:"Let's audit this passage together for punctuation variety.",sentences:["The science fair was held on Thursday. Every class had an entry. Our class made a working volcano. It erupted three times. The judges were impressed. We won first place. It was a good day."],prompt:"Where could a semicolon replace a full stop? Where could a dash add drama? Is there a list that needs a colon?"},{title:"You Do — Your Turn",instruction:"Swap a piece of your writing with a partner. Edit each other's work for punctuation variety using the checklist.",tasks:["✦ Checklist: At least one semicolon used correctly.","✦ Checklist: At least one colon introducing a list or explanation.","✦ Checklist: At least one dash or pair of brackets for parenthetical information.","✦ Bonus: Rewrite your partner's weakest paragraph — the one with the least punctuation variety — as a model of what it could look like."]},[{code:"Writing — Writing Process (Practice)",label:"Peer editing for punctuation variety",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "share writing with others and respond to feedback to improve their work." Peer editing for punctuation variety is a specific application of this expectation — students give targeted, rule-based feedback (not just "it's good") and practise reading writing through an editor's eye rather than a writer's eye.`},{code:"Writing — Punctuation (Practice)",label:"Applying a punctuation checklist",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This lesson consolidates all Term 2 punctuation learning — commas after fronted adverbials, colons, semicolons, brackets, and dashes — in a peer editing context where students must both recognise correct use and explain the rule behind each mark.'}])},6:{Monday:g("Greek & Latin roots in everyday words","Writing — Vocabulary (Knowledge): many English words are built from Greek and Latin roots; understanding common roots enables students to decode unfamiliar words and expand their vocabulary systematically.",{title:"I Do — Crack the Code",instruction:"Many English words are built from Greek and Latin roots. Once you know a root, you can work out the meaning of dozens of words you've never seen before.",example:'"tele" (far) → telescope, television, telepathy | "aqua" (water) → aquatic, aquarium, aqueduct | "bio" (life) → biology, biography, biodiversity',demonstration:'If you see "submarine," you might not know it — but "sub" means under and "marine" means sea. So submarine = under the sea. Same with "microphone" — "micro" (small) + "phone" (sound) = small sound amplifier. Roots unlock words like a key.',tip:"When you hit an unknown word, look for a root you recognise. Even a partial match gives you a clue."},{title:"We Do — Decode Together",instruction:"Use the roots provided to work out what each word means. Then check by looking at the context sentence.",sentences:['"geo" (earth): geology, geography, geothermal — what does "geothermal" likely mean?','"script/scribe" (write): manuscript, inscription, transcribe — what does "transcribe" likely mean?','"spec/spect" (look/see): inspect, spectator, spectacular — what does "spectator" likely mean?'],prompt:"Can you find other words that share these roots? How does knowing the root help you read unfamiliar texts?"},{title:"You Do — Your Turn",instruction:"Use your knowledge of roots to answer each question.",tasks:['The root "port" means carry. What do these words mean: export, import, transport, portfolio?','The root "vis/vid" means see. Use it to work out: visible, invisible, vision, evidence.','The root "terra" means land/earth. What do: terrain, territory, terrarium, extraterrestrial mean?',"✦ Bonus: Find 5 words in a book, magazine, or website that share a Greek or Latin root. List the root, its meaning, and the words that use it."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Greek & Latin roots",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Many English words are built from Latin and Greek roots, prefixes, and suffixes. Understanding the meaning of word parts enables students to work out the meaning of unfamiliar words and to build their vocabulary systematically." This lesson develops morphological awareness — knowing that "geo" means earth unlocks geology, geography, geothermal, and geocentric simultaneously.'},{code:"Writing — Vocabulary (Practice)",label:"Using root knowledge in writing",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "use knowledge of word origins, roots, and word families to extend vocabulary." Understanding that "port" means carry (import, export, transport) gives students a transferable tool — they can both decode unfamiliar words when reading and select more precise vocabulary when writing.'}]),Tuesday:g("Adverbial phrases for time & manner","Writing — Sentence Structure (Practice): adverbial phrases extend single adverbs by adding precision and texture; students replace weak single adverbs with richer adverbial phrases that tell the reader more.",{title:"I Do — Beyond Single Adverbs",instruction:"A single adverb tells us how or when. An adverbial PHRASE does the same job but with more precision and colour.",example:'"She spoke quietly." → "She spoke <u>in a hushed, urgent whisper</u>." | "He left quickly." → "He left <u>before anyone could ask questions</u>."',demonstration:'"Quietly" tells us the manner. "In a hushed, urgent whisper" tells us manner AND gives texture — we can picture it. "Before anyone could ask questions" tells us time AND hints at motivation. Adverbial phrases carry more weight than single adverbs.',tip:"Spot a lone adverb. Ask: can I replace it with a phrase that tells the reader more? If yes — upgrade it."},{title:"We Do — Upgrade Together",instruction:"Replace each underlined adverb with an adverbial phrase that adds more information.",sentences:["The tūī sang <u>loudly</u> in the pōhutukawa.","The tamariki waited <u>nervously</u> for the results.","The boat left <u>early</u>."],prompt:"What kind of adverbial phrase fits — one of manner, time, or place? Can you add detail and stay true to the context?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence by replacing the adverb in brackets with a precise adverbial phrase.",tasks:["The kaitiaki worked [hard] to restore the wetland.","The team celebrated [happily] after the final whistle.","She finished her speech [suddenly].","✦ Bonus: Write a paragraph of 5 sentences about an event or journey. Use at least three different adverbial phrases — one of time, one of manner, one of place."]},[{code:"Writing — Sentence Structure (Practice)",label:"Adverbial phrases for precision",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding adverbial and prepositional phrases to express location, time, and manner." This lesson advances from single adverbs to adverbial phrases — teaching students that a phrase ("in a hushed, urgent whisper") carries more information and creates a richer picture than a single word ("quietly") ever can.'},{code:"Writing — Vocabulary (Practice)",label:"Replacing weak adverbs with phrases",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Replacing a generic adverb with a specific adverbial phrase is a key vocabulary refinement skill at Phase 2 — it demonstrates that the student is thinking about the reader's experience and choosing language that creates a precise and vivid picture.`}]),Wednesday:g("Who/where/when phrases in persuasive writing","Writing — Composing (Practice): specific who, where, and when details make persuasive arguments more credible and harder to dismiss; students embed precise detail in persuasive sentences and paragraphs.",{title:"I Do — Detail That Persuades",instruction:"In Term 1 we used who/where/when phrases to add descriptive detail. This week we use the same technique in persuasive writing — where specific detail makes arguments more convincing.",example:'Vague: "Schools should have gardens." → Specific: "Schools across Aotearoa, from urban Auckland to rural Northland, should have gardens where students can grow and harvest their own kai."',demonstration:'The added phrases — "across Aotearoa, from urban Auckland to rural Northland" (where) and "where students can grow and harvest their own kai" (who/what) — make the claim feel specific and grounded. Vague arguments are easy to dismiss. Specific ones are harder to ignore.',tip:"In persuasion, specific detail builds credibility. WHO would benefit? WHERE would this happen? WHEN should it change? Answer those questions inside your sentences."},{title:"We Do — Make It Specific",instruction:"Add who, where, or when detail to each persuasive sentence to make it more convincing.",sentences:["Students should have access to nature.","Communities need to protect waterways.","Young people deserve to have their voices heard."],prompt:"Which type of detail makes each argument stronger — who, where, or when? Can you add more than one?"},{title:"You Do — Your Turn",instruction:"Expand each bare persuasive claim using who/where/when phrases.",tasks:['Claim: "Aotearoa needs more native tree planting." Add a where and a when phrase.','Claim: "Students learn better outdoors." Add a who and a where phrase.','Claim: "Schools should start later." Add a who and a when phrase.',"✦ Bonus: Write a persuasive paragraph (5–6 sentences) on a topic you care about. Every sentence must include at least one who, where, or when detail."]},[{code:"Writing — Composing (Practice)",label:"Specific detail in persuasion",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to "provide specific, concrete detail that supports the purpose." In persuasive writing, specificity is a core argument strategy — claims supported by precise who, where, and when details are more credible and more resistant to dismissal than vague generalisations.'},{code:"Writing — Text Structure (Practice)",label:"Building convincing persuasive paragraphs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail" in persuasive writing. This lesson directly builds the ability to support a persuasive topic sentence with specific, embedded detail — the who, where, and when that transforms a claim into a convincing argument.'}]),Thursday:g("Editing: replacing overused words ('nice', 'good')","Writing — Vocabulary (Practice) & Writing Process (Practice): students identify and replace the most overused and vague words in their writing with precise, purposeful alternatives.",{title:"I Do — The Vague Word Hit List",instruction:"Some words appear in almost every piece of student writing: nice, good, bad, big, little, went, got, said, things, stuff. They're not wrong — they're just empty. Watch me hunt them down and replace them.",example:'"It was a nice day and we had a good time doing lots of fun things." → "The sun blazed over the harbour and we spent the afternoon kayaking, laughing until our arms gave out."',demonstration:'"Nice day" → specific weather detail. "Good time" → specific activity. "Lots of fun things" → actual examples. The second version creates a picture. The first creates nothing.',tip:"The vague word hit list: nice, good, bad, big, little, went, got, said, things, stuff, very, really. Highlight every one. Each is an upgrade opportunity."},{title:"We Do — Upgrade Together",instruction:"Find every vague word in this passage and replace it with something precise.",sentences:["We went to the nice beach and it was really good. We did lots of fun things and got really tired. The food was nice and everyone said it was a good day."],prompt:"How many vague words can you find? What specific, precise word or phrase could replace each one?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence, replacing every vague word with a precise alternative.",tasks:["The movie was really good and the things that happened were very exciting.","She is a nice person who always says good things to people.","It was a bad situation and lots of bad things went wrong.","✦ Bonus: Take a paragraph from your own writing. Highlight every word from the vague word hit list. Rewrite the paragraph with every vague word upgraded."]},[{code:"Writing — Vocabulary (Practice)",label:"Replacing vague words",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson targets the most pervasive vocabulary weakness at Years 5–6 — over-reliance on generic, high-frequency words — and builds the habit of interrogating each word choice against a concrete alternative.'},{code:"Writing — Writing Process (Practice)",label:"Vocabulary audit in revision",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The vague word audit — highlighting every word from the hit list and challenging each one — is a practical revision strategy that directly improves the precision and vividness of students' writing at Phase 2.`}])},7:{Monday:g("Colons to introduce lists","Writing — Punctuation (Knowledge): a colon introduces a list only when a complete sentence precedes it; students apply this rule accurately and correct common misuses of the colon.",{title:"I Do — The Colon That Sets Up a List",instruction:"We met colons in Term 1. This week we focus specifically on using them to introduce lists — and on the rule about what must come BEFORE the colon.",example:'✓ "The kete contained three items: a tī kōuka leaf, a piece of bone, and a carved pounamu." | ✗ "The kete contained: a tī kōuka leaf, a piece of bone, and a carved pounamu."',demonstration:'The colon introduces the list — but only when a complete sentence comes before it. "The kete contained three items" is a complete sentence ✓. "The kete contained" is NOT a complete sentence ✗ — so no colon. The rule: a complete sentence must precede the colon.',tip:"Before the colon = a complete sentence. After the colon = the list. Test: can the part before the colon stand alone? If not — remove the colon."},{title:"We Do — Fix or Confirm",instruction:"Decide whether the colon is used correctly in each sentence. Fix those that aren't.",sentences:["The scientist needed: a microscope, slides, and a sample jar.","The rescue team brought the following equipment: ropes, a first-aid kit, and torches.","To make rewena bread you will need: flour, potato water, sugar, and salt."],prompt:"Is the part before the colon a complete sentence? If not, what needs to change?"},{title:"You Do — Your Turn",instruction:"Add a colon in the correct place, or rewrite so the colon is used correctly.",tasks:["The pā required three things to defend effectively high ground, a clear view, and strong palisades.","There are many native birds in the Waikato region including: tūī, kererū, and pīwakawaka.","She packed everything she would need for the tramp: food, a sleeping bag, a compass, and wet-weather gear.","✦ Bonus: Write five sentences, each using a colon to introduce a list. Make sure every sentence before the colon is grammatically complete."]},[{code:"Writing — Punctuation (Knowledge)",label:"Colons before lists",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "A colon is used after a complete clause to introduce a list, explanation, or quotation. A common error is placing a colon after an incomplete clause (e.g. 'The bag contained:') — the part before the colon must be a grammatically complete sentence." Students learn to test for completeness before adding a colon, developing both accuracy and understanding of clause structure.`},{code:"Writing — Punctuation (Practice)",label:"Applying colons accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including colons. This lesson develops the completeness test as a reliable self-checking strategy — students identify whether the part before the colon could stand alone as a sentence before applying the mark, preventing the most common colon error at Years 5–6.'}]),Tuesday:g("Progressive tenses: past & present continuous","Writing — Sentence Structure (Knowledge): past and present progressive tenses express ongoing actions; students form and use these tenses accurately, understanding how past progressive sets a background scene interrupted by simple past events.",{title:"I Do — Actions in Progress",instruction:"The progressive (or continuous) tense shows an action that was happening over a period of time — not just a single completed event.",example:'Present progressive: "The kākāpō <u>is climbing</u> the tree right now." | Past progressive: "The kākāpō <u>was climbing</u> when we first spotted it."',demonstration:'Present progressive = is/are + verb-ing: "She is writing." Past progressive = was/were + verb-ing: "She was writing when the bell rang." Key use: past progressive sets a scene that another action interrupts. "He was reading when the power cut out."',tip:'Past progressive sets the background scene. Simple past is the event that interrupts it. Together: "She was sleeping when the earthquake struck."'},{title:"We Do — Form and Use",instruction:"Complete each sentence with the correct progressive form.",sentences:["The students ___ (prepare) their speeches when the fire alarm went off.","Look out the window — the kererū ___ (eat) all the berries!","While the waka ___ (cross) the harbour, the wind suddenly changed direction."],prompt:"Is this happening right now (present) or was it in progress at a past moment (past)? That decides was/were vs is/are."},{title:"You Do — Your Turn",instruction:"Write sentences using the progressive tense as directed.",tasks:["Write a sentence using past progressive to set a scene, then use simple past for an interrupting event.","Describe what three different people are doing right now using present progressive.",'Rewrite in past progressive: "The rangatira spoke to the crowd. The sun set behind the hills."',"✦ Bonus: Write a short recount (5 sentences) of a real or imagined event. Use past progressive at least twice to set the scene before key moments."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Progressive tenses",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "The present progressive tense (is/are + verb-ing) describes an action happening at the moment of speaking. The past progressive tense (was/were + verb-ing) describes an action that was in progress at a past moment, often interrupted by another event in simple past. Both forms require the auxiliary verb 'be' and the present participle (-ing form)."`},{code:"Writing — Sentence Structure (Practice)",label:"Using progressive tense for narrative effect",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of tenses." In narrative writing, past progressive is particularly powerful for scene-setting — it creates a sustained background action ("The village was sleeping") that simple past then disrupts ("when the alarm sounded"). This lesson develops students' control of tense as a narrative craft tool.`}]),Wednesday:g("Complex sentences using 'although', 'unless', 'while'","Writing — Sentence Structure (Knowledge & Practice): 'although', 'unless', and 'while' are subordinating conjunctions that express contrast, condition, and simultaneity; students use them accurately to create nuanced complex sentences.",{title:"I Do — Conjunctions That Add Nuance",instruction:'"Although," "unless," and "while" are subordinating conjunctions that add nuance — they create contrast, condition, and simultaneous action.',example:'"<u>Although</u> it was raining, the match continued." | "The match will continue <u>unless</u> there is lightning." | "<u>While</u> the rain fell, the players kept their positions."',demonstration:`"Although" = contrast (it happened despite something). "Unless" = condition (this won't happen IF something else does). "While" = at the same time. Each creates a different relationship — choosing the right conjunction is part of a writer's craft.`,tip:'"Although" = despite this. "Unless" = except if. "While" = at the same time as. Choose based on the relationship between your two ideas.'},{title:"We Do — Choose the Right Conjunction",instruction:"Complete each sentence with although, unless, or while.",sentences:["___ the journey was exhausting, Mere never once complained.","The kaiako won't begin ___ everyone is seated and listening.","___ the kettle boiled, she set out the cups and the tea."],prompt:"What relationship exists between the two clauses — contrast, condition, or simultaneity?"},{title:"You Do — Your Turn",instruction:"Write two sentences for each conjunction — one with the subordinate clause first, one with it second.",tasks:["although (contrast)","unless (condition)","while (simultaneous)","✦ Bonus: Write a paragraph of 6 sentences about a challenge or difficult situation. Use although, unless, and while at least once each."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Subordinating conjunctions: although, unless, while",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "'Although' expresses contrast (despite the subordinate clause, the main clause is still true); 'unless' expresses condition (the main clause won't happen except under the stated condition); 'while' expresses simultaneity (both actions happen at the same time). Each conjunction creates a different logical relationship between the clauses — understanding these distinctions is a key Phase 2 grammar expectation."`},{code:"Writing — Sentence Structure (Practice)",label:"Complex sentences for nuance",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures — including complex sentences — for effect and clarity." This lesson extends complex sentence use to three conjunctions that require genuine understanding of logical relationships: contrast, condition, and simultaneity — moving students beyond the familiar "because" and "when" into more nuanced subordination.'}]),Thursday:g("Editing: checking tense consistency","Writing — Writing Process (Practice) & Sentence Structure (Knowledge): students apply a systematic verb audit to identify and correct tense inconsistencies in modelled and their own writing.",{title:"I Do — The Verb Audit",instruction:"A tense audit means underlining every verb in a passage, labelling it as past or present, and then correcting any that break the pattern.",example:'"The explorer sets out at dawn. She walked for three hours before she reaches the ridge." — sets (Pr), walked (P), reaches (Pr).',demonstration:'Two present, one past — inconsistent. I decide: past tense works better for a recount. Fix: "The explorer set out at dawn. She walked for three hours before she reached the ridge." — all past, all consistent.',tip:'Be especially careful with "was/is" and "said/says" — these are the most common accidental tense switches.'},{title:"We Do — Audit Together",instruction:"Underline every verb, label each P (past) or Pr (present), then rewrite in consistent past tense.",sentences:["The market is busy on Saturday mornings. Stalls lined both sides of the street. Vendors called out their prices. The smell of fresh bread drifts through the air. Families stopped to chat and children run between the stalls."],prompt:"Which verbs switch tense? What is the dominant tense here? Rewrite consistently."},{title:"You Do — Your Turn",instruction:"Underline all verbs, label each one P or Pr, then rewrite in consistent past tense.",tasks:["The diver slips below the surface. The water was cold and very clear. She searches for the wreck that locals told her about. After ten minutes, she spots a shadow on the seabed. She swam closer and felt her heart race.","✦ Bonus: Take a piece of your own writing and do a full tense audit on it. Note how many switches you find."]},[{code:"Writing — Writing Process (Practice)",label:"Tense audit as revision strategy",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." The tense audit — underline every verb, label the tense, decide on consistency, fix mismatches — is a specific, repeatable revision strategy that goes beyond casual re-reading. It is a direct application of the Phase 2 expectation that students revise systematically.'},{code:"Writing — Sentence Structure (Knowledge)",label:"Identifying tense in context",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Verbs carry tense and must remain consistent throughout a piece of writing. Tense shifts disrupt the reader's experience and signal a lack of control over the writing." This editing lesson deepens grammatical knowledge by requiring students to identify and label verb tense in context before applying corrections — connecting knowledge to practice.`}])},8:{Monday:g("Spelling: tricky high-frequency words","Writing — Conventions (Knowledge): certain high-frequency words have irregular or non-phonetic spellings that must be learned; students apply strategies to memorise and recall these words accurately.",{title:"I Do — Words That Break the Rules",instruction:"Some high-frequency words don't follow phonetic patterns — they must be memorised. Watch me demonstrate three strategies for locking these tricky spellings in.",example:"receive, separate, necessary, occurrence, privilege, conscience, rhythm, liaison",demonstration:`Strategy 1 — Look, Cover, Write, Check: study the word, cover it, write it from memory, check. Strategy 2 — Find the word within the word: "sep-a-rate" (not sep-er-ate) — there's "a rat" in separate! Strategy 3 — Mnemonic: "Rhythm Helps Your Two Hips Move" — first letters spell RHYTHM.`,tip:"When you spell a word wrong twice, look for a mnemonic or pattern that makes the correct spelling stick."},{title:"We Do — Spelling Strategies",instruction:"Use at least one strategy to help you learn each of these tricky spellings.",sentences:["necessary (one c, two s) — find a mnemonic.","occasion (two c, one s) — find the pattern.",'definitely (not "definately") — break it into parts.'],prompt:"Which strategy worked best for each word? Can you teach your strategy to a partner?"},{title:"You Do — Your Turn",instruction:"Use Look, Cover, Write, Check for each word. Then write a sentence using each one correctly.",tasks:["accommodate (two c, two m)","embarrass (two r, two s)","government (silent n before m)",'privilege (not "priviledge")',"✦ Bonus: Create a personal spelling list of 5 words you consistently misspell. Apply one strategy to each and test yourself tomorrow."]},[{code:"Writing — Conventions (Knowledge)",label:"Tricky high-frequency spellings",detail:'NZC Phase 2 Writing — Conventions (Knowledge): "Some high-frequency words have irregular or non-phonetic spellings that must be memorised through repeated practice and strategic learning. Students develop spelling knowledge through a range of strategies including visual memory (Look, Cover, Write, Check), morphological analysis (breaking into meaningful parts), and mnemonics." Accurate spelling of high-frequency words is a core expectation at Years 5–6.'},{code:"Writing — Writing Process (Practice)",label:"Checking and correcting spelling",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking spelling." This lesson builds students' metacognitive awareness of their own spelling weaknesses and gives them a toolkit of strategies — rather than relying on spellcheck — for identifying and fixing errors in their writing.`}]),Tuesday:g("Prepositions of direction & movement","Writing — Sentence Structure (Knowledge): directional prepositions express movement through, across, towards, and along specific paths; students use them precisely to create clear, vivid spatial descriptions.",{title:"I Do — Which Way? Prepositions of Direction",instruction:"Some prepositions express static location (in, on, under). Others express direction and movement — they tell us where something is going. Watch me use directional prepositions to make movement vivid.",example:'"The waka moved <u>across</u> the harbour, <u>through</u> the channel, and <u>towards</u> the shore."',demonstration:'"Across" — movement over a surface from one side to another. "Through" — movement from one side of something to the other by passing inside it. "Towards" — movement in the direction of something. "Along" — movement following the length of something. Each is precise about the geometry of the movement.',tip:"Visualise the movement and ask: is it over a surface (across), inside something (through), in a direction (towards), or following a line (along)?"},{title:"We Do — Choose the Right Preposition",instruction:"Choose the most accurate directional preposition for each gap.",sentences:["The children ran ___ (across/through/along) the beach to the water's edge.","The tuna moved ___ (across/through/towards) the dark water of the river.","She walked ___ (along/towards/through) the ridge, keeping the sea in sight."],prompt:"Picture the movement precisely. Which preposition describes the path most accurately?"},{title:"You Do — Your Turn",instruction:"Add the correct directional preposition and then rewrite the sentence with more specific detail.",tasks:["The kererū flew ___ the canopy and ___ the clearing.","The river flows ___ the gorge and ___ the sea.","She moved ___ the crowd and ___ the stage.","✦ Bonus: Write a paragraph of 5 sentences describing a journey — by foot, waka, or bike. Use at least four different directional prepositions precisely."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Directional prepositions",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Prepositions of direction (across, through, towards, along, past, into, out of) express movement in relation to a surface, an interior, or a destination. Choosing the correct directional preposition requires visualising the geometry of the movement — is it over a surface, inside something, towards a target, or along a path?" Students learn to distinguish between similar prepositions by thinking spatially.'},{code:"Writing — Sentence Structure (Practice)",label:"Precise spatial writing",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding prepositional phrases to express location" and direction. Using directional prepositions precisely — rather than vague alternatives ("went near," "moved by") — is a key skill in descriptive and narrative writing at Phase 2, enabling students to place the reader inside the movement they are describing.'}]),Wednesday:g("Making vague sentences specific","Writing — Composing (Practice) & Vocabulary (Practice): students transform vague, general sentences into specific, detailed ones by adding precise nouns, verbs, and modifiers that answer the reader's implicit questions.",{title:"I Do — Vague vs. Specific",instruction:"Vague sentences tell the reader almost nothing. Specific sentences give them something to picture. Watch me transform a vague sentence into a specific one by answering the reader's questions.",example:'Vague: "A bird made a sound in the tree." → Specific: "A tūī burst into a cascading trill from the topmost branch of the pōhutukawa."',demonstration:"Reader's questions: WHAT bird? → tūī. WHAT sound? → cascading trill. WHERE in the tree? → topmost branch. WHAT tree? → pōhutukawa. Answering each question turns a generic sentence into one that only this moment could have produced.",tip:"For every noun, ask: what exactly? For every verb, ask: how exactly? For every place, ask: where exactly?"},{title:"We Do — Make It Specific",instruction:"Rewrite each vague sentence by answering every implied reader question.",sentences:["A person walked past.","The weather changed.","Something fell."],prompt:"What are the reader's questions for each sentence? What specific detail answers each one?"},{title:"You Do — Your Turn",instruction:"Transform each vague sentence into a specific one. Aim for a sentence only THIS moment could produce.",tasks:["A vehicle went by.","The animal made a noise.","She did something with the object.","The food smelled good.","✦ Bonus: Write 4 intentionally vague sentences, then rewrite each one with maximum specificity. Compare the two versions."]},[{code:"Writing — Composing (Practice)",label:"Creating specific, vivid writing",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including providing specific, concrete detail that allows the reader to visualise the scene. This lesson teaches the "reader's question" technique — systematically asking 'what exactly? how exactly? where exactly?' to identify and fill gaps that leave writing vague and generic.`},{code:"Writing — Vocabulary (Practice)",label:"Precise nouns and verbs",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience," choosing Tier 2 vocabulary that is precise and cross-curricular. Replacing generic nouns ("bird") with specific ones ("tūī") and generic verbs ("made a sound") with precise ones ("burst into a cascading trill") is the most direct application of this principle — specificity IS vocabulary.'}]),Thursday:g("Editing: strengthening narrative openings","Writing — Writing Process (Practice) & Composing (Practice): students evaluate narrative openings against criteria for engagement and revise weak openings to draw the reader immediately into the story.",{title:"I Do — First Sentences That Work",instruction:"A weak opening loses the reader before the story begins. Watch me evaluate three narrative openings against criteria, then revise the weakest one.",example:'Weak: "My name is Jake and this is a story about something that happened to me last summer." | Strong: "The day I found the box, I almost walked straight past it."',demonstration:`The weak opening: tells rather than shows, introduces the narrator self-consciously, contains no tension or mystery. The strong opening: drops us into a specific moment, creates immediate curiosity ("what was in the box?"), and doesn't explain itself. Criteria for a strong opening: specific moment, no explaining, creates a question in the reader's mind.`,tip:"Test: does the opening make the reader ask a question? If not — rewrite until it does."},{title:"We Do — Diagnose and Revise",instruction:"Evaluate each opening against our three criteria. Then revise the weakest one together.",sentences:['"Once upon a time there was a girl who wanted to be an explorer."','"The engine coughed twice, then fell silent. In the distance, the lights of the mainland blinked out."','"I am going to write about the best day I ever had which was when we went to the beach."'],prompt:"Which opening drops you into a specific moment? Which creates a question? Which explains too much?"},{title:"You Do — Your Turn",instruction:"Rewrite each weak opening so it meets all three criteria.",tasks:['"This is the story of how I found out my neighbour was not who she said she was."','"One day something strange happened and I will tell you about it in this story."',`"It was a morning like any other until it wasn't."`,"✦ Bonus: Write three alternative openings for a story of your choice. Choose the best one and explain why."]},[{code:"Writing — Writing Process (Practice)",label:"Evaluating and revising narrative openings",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson applies that revision process to the highest-stakes part of any narrative — the opening sentence. Students evaluate against explicit criteria (specific moment, no explaining, reader question) and revise until the opening works.'},{code:"Writing — Composing (Practice)",label:"Engaging the reader from the first sentence",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader." Narrative opening strategy is a key composing skill at Phase 2 — students learn that the most engaging openings drop the reader directly into a specific moment, create immediate curiosity, and resist the urge to explain or introduce the narrator self-consciously.'}])},9:{Monday:g("Alliteration & assonance","Writing — Vocabulary (Knowledge) & Composing (Practice): alliteration (repeated consonant sounds) and assonance (repeated vowel sounds) are sound devices that create rhythm, mood, and texture in writing.",{title:"I Do — Making Writing Sound as Good as It Reads",instruction:"Alliteration repeats the same consonant sound at the start of neighbouring words. Assonance repeats the same vowel sound in the middle of words. Both create rhythm and texture that the reader can hear.",example:'Alliteration: "The <u>s</u>ilent <u>s</u>nake <u>s</u>lipped through the <u>s</u>edge." | Assonance: "The r<u>ai</u>n-sl<u>ai</u>n pl<u>ai</u>n."',demonstration:`Alliteration: the "s" sound creates a hissing, slithering effect — perfect for a snake. Assonance: the "ai" sound gives a slow, mournful quality — good for a grey, flat landscape. Both devices work best when they reinforce the meaning or mood, not when they're forced.`,tip:"Sound devices should serve the meaning. If the reader notices the device more than the content — it's too obvious."},{title:"We Do — Hear the Sound",instruction:"Brainstorm sound words for each setting, then build a sentence using alliteration or assonance.",sentences:["Setting: a beach at high tide","Setting: a forest just after rain","Setting: a crowded school cafeteria"],prompt:"What sounds would you hear? What sounds could you create with alliteration or assonance?"},{title:"You Do — Your Turn",instruction:"Write sentences using the device specified.",tasks:['Write an alliterative sentence about a NZ animal using the "k" sound (kiwi, kererū, kākāpō, kārearea).','Write a sentence about the sea using assonance with the "ō" or "oo" sound.',"Write a description of a storm using both alliteration and assonance in the same sentence.","✦ Bonus: Write a 4-line descriptive poem about a NZ landscape. Use alliteration in at least two lines and assonance in at least one."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Sound devices: alliteration & assonance",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Language devices such as alliteration (repeated consonant sounds) and assonance (repeated vowel sounds) create specific effects for the reader — rhythm, mood, and texture. They are most effective when they reinforce the meaning of the writing rather than being applied for their own sake." Students learn to use sound devices deliberately and discriminatingly, not mechanically.'},{code:"Writing — Composing (Practice)",label:"Using sound devices for effect",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use language devices to create specific effects and engage the reader." Alliteration and assonance are sound-based composing tools — they work on the reader's ear as well as their mind. This lesson develops the discipline of asking 'what mood am I creating?' before selecting which sound to repeat and how often.`}]),Tuesday:g("Coordinating vs. subordinating conjunctions: review","Writing — Sentence Structure (Knowledge): students consolidate their understanding of coordinating (FANBOYS) and subordinating conjunctions, applying the distinction to build and identify compound and complex sentences accurately.",{title:"I Do — Two Types, Two Jobs",instruction:"We've studied both types of conjunction across Terms 1 and 2. Today we consolidate: coordinating conjunctions join equal clauses; subordinating conjunctions create a main clause and a dependent clause.",example:'Coordinating: "The hīkoi was long, <u>but</u> the marchers kept going." | Subordinating: "The marchers kept going <u>although</u> the hīkoi was exhausting."',demonstration:"FANBOYS (for, and, nor, but, or, yet, so) = coordinating — both sides could stand alone. AAAWWUBBIS (after, although, as, when, while, until, because, before, if, since) = subordinating — the dependent clause leans on the main clause.",tip:"Test: remove the conjunction and split the sentence in two. If both halves make sense alone — coordinating. If one half sounds incomplete — subordinating."},{title:"We Do — Classify and Use",instruction:"Identify whether the underlined conjunction is coordinating or subordinating, then explain how you know.",sentences:["The kaiako waited <u>until</u> the class was completely silent.","The experiment failed, <u>yet</u> the students learnt something important.","<u>Because</u> the tide was out, we could walk across to the island."],prompt:"Could both sides stand alone? What type of relationship does each conjunction create?"},{title:"You Do — Your Turn",instruction:"Write sentences using the conjunction type shown.",tasks:["Write a compound sentence using a coordinating conjunction that shows contrast.","Write a complex sentence using a subordinating conjunction that shows cause.","Write a complex sentence where the subordinate clause comes FIRST (with a comma after it).","✦ Bonus: Write a paragraph of 5 sentences about a place you know well. Use at least two coordinating and two subordinating conjunctions. Label each one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Coordinating vs. subordinating conjunctions",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Coordinating conjunctions (FANBOYS: for, and, nor, but, or, yet, so) join two independent clauses of equal grammatical weight — both sides can stand alone. Subordinating conjunctions (because, although, when, unless, while, until, since, as, before, after, if) introduce a dependent clause that cannot stand alone. Understanding this distinction is essential for building compound and complex sentences accurately."'},{code:"Writing — Sentence Structure (Practice)",label:"Compound & complex sentence consolidation",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures — simple, compound, and complex — for effect and clarity." This review lesson consolidates the distinction between compound sentences (coordinating conjunctions, comma before) and complex sentences (subordinating conjunctions, comma only when fronted) — integrating Term 1 and Term 2 sentence structure learning at Phase 2.'}]),Wednesday:g("Paragraph cohesion: pronouns as linking devices",'Writing — Text Structure (Practice): students use personal pronouns, demonstrative pronouns ("this," "these"), and pronoun reference to create cohesion within paragraphs, linking sentences into a connected whole.',{title:"I Do — Pronouns That Hold a Paragraph Together",instruction:'We used connective words in Term 1. This week, we focus specifically on pronouns as cohesive devices — how "he," "she," "they," "it," "this," and "these" reach back to a previous sentence and pull ideas together.',example:`"The tuatara is one of New Zealand's most ancient reptiles. <u>It</u> has barely changed in 200 million years. <u>This</u> makes <u>it</u> a living link to the age of the dinosaurs."`,demonstration:'"It" in sentence 2 refers back to "tuatara" — no need to repeat the noun. "This" in sentence 3 refers back to the whole idea of sentence 2. Each pronoun acts like a thread, stitching sentences into a paragraph rather than a list.',tip:"After writing a paragraph, draw an arrow from each pronoun to what it refers to. Every pronoun should have a clear, unambiguous referent."},{title:"We Do — Stitch It Together",instruction:"Replace the repeated nouns with appropriate pronouns to improve paragraph cohesion.",sentences:["The pūkeko is a bold and territorial bird. The pūkeko will often chase away much larger animals. The pūkeko's bright red beak makes the pūkeko easy to spot in wetland areas. Despite the pūkeko's aggression, the pūkeko is a beloved part of the New Zealand landscape."],prompt:"Which nouns can be replaced with pronouns? Are there any where replacing would cause confusion?"},{title:"You Do — Your Turn",instruction:"Rewrite this paragraph so pronouns link the sentences without causing ambiguity.",tasks:["The kākāpō is a large, flightless parrot. The kākāpō is critically endangered. Conservation teams monitor every single kākāpō. Each kākāpō has a name and a tracking pack. The tracking pack helps conservation teams follow each kākāpō's movements across the island.","✦ Bonus: Write a paragraph of 5 sentences about a NZ animal or place. Use a different pronoun in at least three sentences to link back to the subject. Make sure every pronoun is unambiguous."]},[{code:"Writing — Text Structure (Practice)",label:"Pronoun cohesion within paragraphs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "use cohesive devices — including pronouns, synonyms, and connectives — to link ideas within and across sentences and paragraphs." This lesson focuses specifically on pronoun cohesion: using personal pronouns (it, they), possessive pronouns (its, their), and demonstrative pronouns (this, these) to refer back to nouns and ideas — creating flow rather than repetition.'},{code:"Writing — Sentence Structure (Knowledge)",label:"Pronoun reference & ambiguity",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Pronouns must refer unambiguously to their antecedent. When two or more nouns are present, pronouns can create confusion if the referent is unclear." This lesson develops the habit of checking pronoun reference — drawing arrows from each pronoun to its antecedent — and revising when the reference is ambiguous.'}]),Thursday:g("Editing: identifying weak sentence openings","Writing — Writing Process (Practice) & Sentence Structure (Practice): students diagnose monotonous sentence opening patterns and revise them using fronted adverbials, adjective openers, and rearranged clause order.",{title:"I Do — The Weak Opening Pattern",instruction:'When every sentence starts the same way — especially with "The" or "I" — writing becomes monotonous. Watch me diagnose a passage with weak openings and revise it.',example:'"The sky was dark. The clouds gathered quickly. The wind picked up. The rain began to fall. The thunder rolled in from the south."',demonstration:'Five sentences. Every one starts with "The." Revision: "Dark clouds gathered quickly. As the wind picked up, the first drops of rain began to fall. From the south, thunder rolled in — low and threatening." Varied openers: adjective, adverbial, fronted phrase. Immediately more dynamic.',tip:"List the first word of every sentence in your paragraph. If more than two start the same way — vary them."},{title:"We Do — Diagnose Together",instruction:"List the first word of each sentence. Identify the pattern. Then rewrite three sentences with different openers.",sentences:["I arrived at school early. I put my bag in my locker. I went to find my friends. I sat down and waited for the bell. I felt nervous about the day ahead."],prompt:"What pattern do you see? What three different ways could you begin these sentences instead?"},{title:"You Do — Your Turn",instruction:"Rewrite this paragraph, varying the sentence openings so no two consecutive sentences start the same way.",tasks:["The match started well. The team scored early. The crowd cheered loudly. The other team fought back. The score was level at half time. The players looked tired. The coach spoke to them firmly. The second half began.","✦ Bonus: Write a paragraph of 6 sentences about any topic. Make a rule: no two sentences may start with the same word. List the opening word of each sentence underneath."]},[{code:"Writing — Writing Process (Practice)",label:"Revising for sentence opener variety",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson teaches a specific diagnostic strategy — listing the first word of every sentence — that makes repetitive opener patterns immediately visible, enabling targeted revision.'},{code:"Writing — Sentence Structure (Practice)",label:"Varying sentence openers",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "vary sentence openings to avoid repetition and create effect," using fronted adverbials, adjective openers, and rearranged clause order. This lesson consolidates all sentence variety strategies from Terms 1 and 2, applying them in a revision context where students must diagnose the problem before selecting the solution.'}])},10:{Monday:g("Review: Term 2 punctuation","Writing — Punctuation (Knowledge & Practice): students consolidate all punctuation covered in Term 2 — commas after fronted adverbials, colons, semicolons, brackets, dashes, apostrophes for contraction, and comma splices.",{title:"I Do — Term 2 Punctuation Gallery",instruction:"Let's revisit every punctuation mark from Term 2 and its rule.",example:"Comma after fronted adverbial | Colon before list | Semicolon joining related sentences | Brackets for quiet aside | Dashes for emphatic aside | Contraction apostrophe | No apostrophe for plurals | Comma splice fix",demonstration:'"Before the match began, the referee called the captains together. Each team needed the following things: a captain, a strategy, and confidence. The home team was ready; the visitors looked nervous. One player — the one who had trained hardest — stepped forward."',tip:"For each mark, ask: what job is it doing here? If it's not doing a job, remove it."},{title:"We Do — Punctuation Challenge",instruction:"Add the correct punctuation to each sentence and name the rule.",sentences:["Despite the strong wind the waka race continued as planned.","The pā required three things a strong location high walls and clear sightlines.","The tī kōuka also known as the cabbage tree is found throughout Aotearoa."],prompt:"Which marks are needed and why? Could any sentence use more than one type?"},{title:"You Do — Your Turn",instruction:"Add all missing punctuation to this passage. Name every rule you applied.",tasks:["although the weather was overcast the school cross-country went ahead as planned. the course covered three different terrains the playing field a bush track and the school road. hazel our fastest runner had trained every morning before school. she wasnt nervous she was ready. after two kilometres hazel was still in front the other runners couldnt keep up with her pace.","✦ Bonus: Write a paragraph of 6 sentences that uses every Term 2 punctuation mark at least once. Label each one."]},[{code:"Writing — Punctuation (Knowledge)",label:"Term 2 punctuation review",detail:"NZC Phase 2 Writing — Punctuation (Knowledge): Students consolidate all punctuation covered in Term 2: commas after fronted adverbials, colons to introduce lists or explanations, semicolons to join related independent clauses, brackets and dashes for parenthetical information, apostrophes for contraction (not for plurals), and the identification and correction of comma splices. Review ensures students can name the function of each mark and apply the relevant rule."},{code:"Writing — Punctuation (Practice)",label:"Applying full range of punctuation",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This consolidation lesson asks students to apply all Term 2 punctuation conventions in an extended passage — naming the rule behind each choice — building the metacognitive awareness needed to make punctuation decisions independently across all writing contexts at Phase 2.'}]),Tuesday:g("Review: Term 2 grammar","Writing — Sentence Structure (Knowledge): students consolidate all grammar covered in Term 2 — collective and abstract nouns, future tense, SVA tricky cases, relative pronouns, progressive tenses, and conjunction types.",{title:"I Do — Term 2 Grammar Gallery",instruction:"Let's revisit every grammar concept from Term 2 — one mini-example each.",example:"Collective & abstract nouns | Future tense: will/going to | SVA: everyone/each | Relative pronouns: who/which/that | Progressive tenses: was-ing/is-ing | Conjunction types: CO vs SUB",demonstration:'"A pride of lions (collective) shows remarkable loyalty (abstract). Each lion (SVA: singular) has its own role. The pride is going to move (future: planned) at dusk. The leader, who guides (relative: person) the hunt, was circling (past progressive) the herd when the weakest animal stumbled (simple past interrupts)."',tip:"Grammar is about understanding why a sentence works, not just labelling. Always connect the rule to the meaning it creates."},{title:"We Do — Grammar Challenge",instruction:"For each sentence, identify the grammar feature underlined and explain what rule it follows.",sentences:["A <u>flock</u> of starlings was swooping across the estuary.","<u>Neither</u> of the answers is correct.","The taonga, <u>which</u> had been in the whānau for generations, was carefully restored."],prompt:"What type of noun/pronoun/verb is underlined? What rule governs it?"},{title:"You Do — Your Turn",instruction:"Complete the grammar review tasks.",tasks:["Write a sentence using a collective noun and an abstract noun.",'Write two future tense sentences — one with "will" (spontaneous) and one with "going to" (planned).','Write a sentence using a relative clause with "which" (remember the commas).',"Write a sentence using past progressive interrupted by simple past.","✦ Bonus: Write a paragraph of 6 sentences demonstrating at least 5 different Term 2 grammar concepts. Label them in the margin."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Term 2 grammar review",detail:"NZC Phase 2 Writing — Sentence Structure (Knowledge): Students consolidate their understanding of all grammar covered in Term 2: collective and abstract nouns, future tense using will/going to, subject-verb agreement with indefinite pronouns (everyone, each, neither), relative pronouns (who, which, that), past and present progressive tenses, and the distinction between coordinating and subordinating conjunctions. Review connects knowledge to meaning and use."},{code:"Writing — Sentence Structure (Practice)",label:"Integrated grammar application",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of word classes and structures." This review lesson asks students to demonstrate all Term 2 grammar knowledge in context — combining multiple features in single sentences — moving from isolated recognition to integrated, purposeful use at Phase 2.'}]),Wednesday:g("Review: Term 2 sentence structures","Writing — Sentence Structure (Practice): students consolidate all sentence structures from Term 2 — compound sentences in new contexts, complex sentences using although/unless/while, sentence combining, and fronted adverbial sentences.",{title:"I Do — The Term 2 Sentence Toolkit",instruction:"This term we added powerful new tools to our sentence toolkit. Let me show each one in action.",example:"FANBOYS in context | Complex: although/unless/while | Combined sentences | Fronted adverbials | Who/where/when expanded",demonstration:'"Although the hīkoi had been going for three days, the marchers showed no sign of stopping (although). They would not rest unless they reached the marae (unless). While the leaders held talks, the rest of the group set up camp (while). Before dawn the next morning, they set out again (fronted adverbial)."',tip:"Variety is the goal. Read your writing aloud — if it has a rhythm that changes and shifts, you're using your toolkit well."},{title:"We Do — Sentence Type Identification",instruction:"Identify the sentence type and explain the structural feature that defines it.",sentences:["Despite the forecast, the outdoor event went ahead without a hitch.","She wanted to give up, yet something kept her moving forward.","The waka, which had been carved by hand over two years, was finally blessed."],prompt:"What type is each sentence? What structural feature tells you?"},{title:"You Do — Your Turn",instruction:"Write one sentence of each type, all on the topic of the sea.",tasks:['Compound sentence using "yet."','Complex sentence starting with "Although."','Complex sentence using "unless" — subordinate clause second.','Complex sentence using "while."',"Fronted adverbial sentence.","✦ Bonus: Combine all five sentences into a cohesive paragraph about the sea. Edit for flow and variety."]},[{code:"Writing — Sentence Structure (Practice)",label:"Term 2 sentence structure review",detail:"NZC Phase 2 Writing — Sentence Structure (Practice): Students consolidate all sentence structures from Term 2: FANBOYS compound sentences in varied contexts, complex sentences using although/unless/while, combining choppy sentences for flow, and fronted adverbial sentences with correct comma placement. Students demonstrate the ability to identify structural features by name and produce each type on demand."},{code:"Writing — Composing (Practice)",label:"Sentence variety across a paragraph",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including controlling rhythm and variety through sentence structure. This consolidation task — writing five different sentence types on the same topic and combining them into a paragraph — directly tests whether students can select the right structure for each moment rather than defaulting to a favourite pattern.'}]),Thursday:g("Full-passage edit: Term 2 checklist","Writing — Writing Process (Practice): students apply all Term 2 editing skills in a systematic multi-pass edit, using the full Term 2 checklist to revise a passage for punctuation, grammar, vocabulary, and structure.",{title:"I Do — The Full Term 2 Edit",instruction:"Today I do a complete multi-pass edit using our full Term 2 checklist. One pass per focus — never try to fix everything at once.",example:"Pass 1: Comma after fronted adverbials | Pass 2: Colons, semicolons, brackets, dashes | Pass 3: Apostrophes (possession AND contraction — no plurals) | Pass 4: Comma splices | Pass 5: Vague verb/word upgrades | Pass 6: Sentence opener variety",demonstration:"I read the passage once for meaning. Then Pass 1: check every sentence that starts with an adverbial phrase — is the comma there? Pass 2: look for lists — do they use colons correctly? Pass 3: every apostrophe — possession, contraction, or error? And so on.",tip:"Multi-pass editing catches more than single-pass. Each pass has a specific focus — you're not trying to see everything at once."},{title:"We Do — Class Edit",instruction:"Work through each pass together on this passage.",sentences:["despite the rain our school fair went ahead last saturday. the organisers needed three things good volunteers lots of stalls and the right attitude. the fair included many activities a cake stall a bouncy castle a talent show and a silent auction. it wasnt perfect but everyones effort paid off. by the end of the afternoon the school had raised over two thousand dollars for the librarys new books."],prompt:"Pass by pass — what are we fixing? Count the total improvements."},{title:"You Do — Your Turn",instruction:"Edit this passage using all six passes of the Term 2 checklist. Rewrite the improved version.",tasks:["on thursday afternoon the year 5 and 6 students went to the wetland reserve near school. the reserve contained many things native plants birds insects and a small stream. although the track was muddy the students werent put off. the guide who had worked there for twenty years showed them a bittern its one of new zealands rarest birds. everyone said it was the best trip theyd ever been on.","✦ Bonus: Apply the full 6-pass edit to a paragraph from your own writing journal."]},[{code:"Writing — Writing Process (Practice)",label:"Multi-pass editing: Term 2 checklist",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson makes the revision process systematic and visible — a structured, six-pass approach that integrates every editing skill from Term 2. Students apply punctuation, grammar, and vocabulary knowledge simultaneously in a single extended editing task.'},{code:"Writing — Writing Process (Practice)",label:"Term 2 skills: integrated application",detail:'NZC Phase 2 Writing — Writing Process (Practice): This consolidation lesson asks students to demonstrate mastery of all Term 2 writing skills in one editing task: fronted adverbial commas, colons and semicolons, brackets and dashes, apostrophes, comma splice correction, vocabulary precision, and sentence opener variety. It directly mirrors the Phase 2 expectation that students "apply writing knowledge and skills across a range of text types and purposes" with increasing independence.'}])},3:{1:{Monday:g("Tier 2 vocabulary: words for feelings & emotion","Writing — Vocabulary (Knowledge & Practice): emotive vocabulary conveys character and stakes; students build emotion word ladders and select words matched precisely to the intensity of what they are describing.",{title:"I Do — The Emotion Word Ladder",instruction:'Precise emotion vocabulary moves readers. Watch me build an "emotion word ladder" — from mild to intense.',example:"sad → unhappy → miserable → devastated → heartbroken",demonstration:'Each word is more intense than the last. A character who is "unhappy" about losing a game feels different from one who is "devastated." Choosing the right level signals to the reader exactly how much this moment matters.',tip:`Match the emotion word to the story's stakes. Small disappointment → "disappointed." Life-changing loss → "devastated."`},{title:"We Do — Build the Ladder",instruction:"Build emotion ladders for these feelings together — from mild to intense.",sentences:["angry → ___ → ___ → ___ → ___","happy → ___ → ___ → ___ → ___"],prompt:"Which word would you use in a funny story? Which in a dramatic one? Why does the choice matter?"},{title:"You Do — Your Turn",instruction:"Replace each plain emotion word with one from the correct intensity level.",tasks:["She was <u>sad</u> when her goldfish died. (use devastated or heartbroken)","He was <u>happy</u> when his name was called. (mild — use pleased or delighted)","The crowd was <u>angry</u> at the decision. (intense — use furious or outraged)",'✦ Bonus: Write an "emotion ladder" for "scared" with 6 levels from mild to extreme. Use three of them in three separate sentences.']},[{code:"Writing — Vocabulary (Knowledge)",label:"Emotive vocabulary & intensity",detail:`NZC Phase 2 Writing — Vocabulary (Knowledge): "Vocabulary is chosen deliberately for effect, so students consider the connotations and precision of words." Emotive vocabulary has a spectrum of intensity — from "unhappy" to "heartbroken" — and choosing the right point on that spectrum is a key craft decision in narrative and persuasive writing at Years 5–6. Emotion ladders build students' awareness of this spectrum explicitly.`},{code:"Writing — Vocabulary (Practice)",label:"Selecting emotion words for effect",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson develops the habit of asking 'exactly how intense is this feeling?' before selecting an emotion word — replacing vague defaults (sad, happy, angry) with precisely calibrated Tier 2 vocabulary.`}]),Tuesday:g("Nouns revisited: count vs. non-count nouns","Writing — Sentence Structure (Knowledge): count nouns have plurals and use a/an or numbers; non-count (mass) nouns cannot be pluralised and require different determiners; students identify and use both accurately.",{title:"I Do — Can You Count It?",instruction:"Count nouns can be counted and have plurals. Non-count (mass) nouns cannot be counted and have no plural form.",example:"Count: one book, two books ✓ | Non-count: one sand, two sands ✗",demonstration:`"Sand" — you can't say "two sands." You say "some sand" or "a grain of sand." Other non-count nouns: water, music, advice, furniture, information. With count nouns you use "a/an" or numbers. With non-count nouns you use "some," "much," "a lot of."`,tip:`"Much" = non-count ("much water"). "Many" = count ("many cups"). If you're unsure, try adding a number — if it sounds wrong, it's non-count.`},{title:"We Do — Sort and Choose",instruction:"Sort these nouns as count (C) or non-count (NC) and choose the correct determiner.",sentences:["___ furniture | ___ chairs | ___ advice | ___ suggestions | ___ lightning"],prompt:"Count or non-count? Which determiner fits — a/an, some, many, or much?"},{title:"You Do — Your Turn",instruction:"Correct the non-count noun errors in these sentences.",tasks:["She gave me a lot of advices about the exam.","We need two furnitures for the new room.","Can I have some informations about the trip?","There were many thunders during the storm.","✦ Bonus: Write 6 sentences — 3 using count nouns correctly with numbers or a/an, 3 using non-count nouns correctly with some/much/a lot of."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Count vs. non-count nouns",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Nouns can be classified as count nouns (which can be pluralised and used with a/an or numbers: a book, two books) or non-count (mass) nouns (which cannot be pluralised and require determiners such as some, much, or a lot of: some advice, much water). Using the correct determiner with non-count nouns is a grammatical accuracy expectation at Years 5–6."'},{code:"Writing — Writing Process (Practice)",label:"Editing non-count noun errors",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Non-count noun errors (advices, furnitures, informations) are among the most persistent grammatical inaccuracies in Years 5–6 writing, particularly for students with languages other than English at home. Developing the counting test gives all students a reliable self-checking strategy.'}]),Wednesday:g("Simple sentences in narrative: building suspense","Writing — Sentence Structure (Practice) & Composing (Practice): short simple sentences create dramatic rhythm and suspense in narrative; students use sentence length deliberately as a craft tool.",{title:"I Do — Simple Sentences as Drama",instruction:"In narrative, simple sentences aren't just exercises — they're dramatic tools. Watch how a string of short simple sentences creates suspense.",example:'"She stopped. She listened. The floorboard creaked. Someone was there."',demonstration:'Each sentence is complete. Each ends with a full stop — a tiny pause. That rhythm creates tension. Compare: "She stopped and listened because a floorboard creaked and someone was there." — all the information, but none of the tension. Short sentences force the reader to pause and feel each beat.',tip:"In action or suspense moments, break your writing into short simple sentences. Let the reader feel every beat individually."},{title:"We Do — Build the Tension",instruction:"Rewrite this rushed description as a series of short simple sentences to build suspense.",sentences:["The old house was dark and silent and the child walked slowly up the creaking staircase and then she heard a sound coming from behind the closed door at the end of the hall."],prompt:"Where are the moments of tension? How many sentences should there be? What length creates the most suspense?"},{title:"You Do — Your Turn",instruction:"Write a 5-sentence suspense sequence using only simple sentences. Then label the dramatic effect each one creates.",tasks:["Scene: a character is alone in a forest at night and hears something.","Rule: 5 simple sentences, each 5–8 words. No conjunctions.","Label each sentence: anticipation / shock / pause / realisation / climax","✦ Bonus: Now rewrite the same scene as one long complex sentence. Compare the two versions — which works better for suspense and why?"]},[{code:"Writing — Sentence Structure (Practice)",label:"Short sentences for suspense",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity," including using short, simple sentences deliberately for dramatic impact. This lesson establishes sentence length as a craft tool — students learn that a sequence of short sentences creates a specific rhythm (pause, pause, pause) that builds suspense more effectively than a single long sentence carrying the same information.'},{code:"Writing — Composing (Practice)",label:"Controlling pace in narrative",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including controlling pace and rhythm. In narrative, sentence length is one of the most powerful pacing tools available — short sentences slow the clock; long sentences sweep time forward. This lesson gives students conscious control over that decision.'}]),Thursday:g("Dialogue punctuation: speech marks and conventions","Writing — Punctuation (Knowledge & Practice): dialogue has specific punctuation conventions including speech marks, commas before speech tags, and new lines for new speakers; students identify and apply these accurately.",{title:"I Do — The Five Rules of Dialogue",instruction:"Dialogue has its own punctuation rules. Watch me apply all five with clear examples.",example:`"I think we're lost," she whispered.
"Lost?" said Tom. "Are you sure?"
"Yes," she replied. "Completely."`,demonstration:"Rule 1: Speech marks around the spoken words. Rule 2: Comma (not full stop) before the closing speech mark when a speech tag follows. Rule 3: The speech tag (she whispered) is NOT capitalised after the comma unless it's a proper noun. Rule 4: New speaker = new line. Rule 5: All punctuation sits inside the speech marks.",tip:"Ask: is there a speech tag after the speech? If yes — the full stop becomes a comma inside the speech marks."},{title:"We Do — Fix the Dialogue",instruction:"Fix the dialogue punctuation in these exchanges, applying all five rules.",sentences:['"We should go" said Marcus "before it gets dark."','Anna replied "but I havent finished yet"','"Look out screamed the driver'],prompt:"Apply the 5 rules one at a time. What is wrong with each line?"},{title:"You Do — Your Turn",instruction:"Rewrite this dialogue with correct punctuation throughout.",tasks:['"where are we going asked lily','"to the market said dad I need to get some things','"can I have a sausage she asked','"if youre good he replied',"✦ Bonus: Write a 6-line dialogue between two characters discovering something unexpected. Apply all 5 dialogue punctuation rules perfectly."]},[{code:"Writing — Punctuation (Knowledge)",label:"Dialogue punctuation conventions",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "Dialogue has specific punctuation conventions: speech marks enclose the spoken words; a comma (not a full stop) precedes the closing speech mark when a speech tag follows; the speech tag is not capitalised after a comma unless it is a proper noun; a new speaker requires a new line; all punctuation sits inside the speech marks." These conventions are explicitly expected at Years 5–6 across narrative text types.'},{code:"Writing — Punctuation (Practice)",label:"Applying dialogue punctuation accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including speech marks and dialogue conventions. This lesson builds a systematic rule-checking approach — students apply the five rules in sequence rather than trying to fix everything at once — developing the accuracy and confidence needed to punctuate dialogue independently in their narrative writing.'}])},2:{Monday:g("Commas in complex sentences (before 'but', 'although')","Writing — Punctuation (Knowledge & Practice): a comma before 'but' separates two independent clauses; a comma after a fronted 'although' clause separates it from the main clause; students apply both rules accurately.",{title:"I Do — The Comma at the Turn",instruction:'When we join two clauses with "but" or use "although" at the start of a sentence, commas signal the shift in meaning. Watch me show exactly when and where they go.',example:'"She trained hard every day<u>,</u> but she still felt unprepared." | "<u>Although</u> she trained hard every day<u>,</u> she still felt unprepared."',demonstration:'"But" joining two complete clauses = comma before "but." "Although" at the start = comma after the subordinate clause, before the main clause. If "although" comes in the middle: "She still felt unprepared although she had trained hard" — no comma needed.',tip:'Comma before "but" when both sides are complete clauses. Comma after a clause starting with "although" when it comes first.'},{title:"We Do — Add or Remove the Comma",instruction:"Decide whether each sentence needs a comma, already has one correctly, or has one in the wrong place.",sentences:["The pōhutukawa was blooming but the bees had not yet arrived.","Although the water was cold she jumped in without hesitating.","He wanted to speak but, he couldn't find the right words."],prompt:'Is the comma in the right place? Is there a complete clause on both sides of "but"? Does "although" come at the front or middle?'},{title:"You Do — Your Turn",instruction:"Add commas where needed in each sentence.",tasks:["The tāniko weaving was intricate but she finished it in two evenings.","Although the hīkoi had been going for three days the group showed no sign of stopping.","He was tired but determined to reach the hut before dark.","Although kiwi are nocturnal they are occasionally spotted during the day.",'✦ Bonus: Write 4 sentences — two using "but" and two using "although." Make sure every comma is correctly placed.']},[{code:"Writing — Punctuation (Knowledge)",label:"Commas with 'but' and 'although'",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "A comma is placed before 'but' when it joins two independent clauses. When 'although' introduces a fronted subordinate clause, a comma separates it from the main clause. When 'although' appears mid-sentence (subordinate clause second), no comma is needed." These comma rules are specific to the structure of the sentence, not the conjunction alone — understanding the distinction is a key Phase 2 punctuation milestone.`},{code:"Writing — Punctuation (Practice)",label:"Applying conjunction comma rules",detail:`NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This lesson develops the decision-making process behind comma placement in complex sentences — students learn to ask 'what comes before the conjunction?' and 'where does the conjunction sit?' rather than applying the comma mechanically every time they see "but" or "although."`}]),Tuesday:g("Modal verbs: might, should, could","Writing — Sentence Structure (Knowledge): modal verbs (might, should, could, would, must, may, will) express degrees of possibility, obligation, and ability; students use them to express nuance in persuasive and informational writing.",{title:"I Do — The Verbs of Possibility",instruction:"Modal verbs express how certain or necessary something is. They change the meaning of a sentence significantly.",example:'"Students must attend." (obligation) | "Students should attend." (recommendation) | "Students could attend." (possibility) | "Students might attend." (uncertain possibility)',demonstration:'"Must" = strong obligation, no choice. "Should" = strong recommendation. "Could" = ability or possibility. "Might/may" = weak possibility, uncertainty. In persuasive writing, choosing the right modal matches your certainty level and tone.',tip:"The more certain you are, the stronger the modal. Match your modal to your confidence level."},{title:"We Do — Choose the Modal",instruction:"Replace the underlined modal with one that changes the meaning as shown in brackets.",sentences:["Schools <u>must</u> provide healthy food options. (→ make it a recommendation, not a rule)","This solution <u>might</u> work. (→ make it stronger — you're fairly confident)","Students <u>could</u> choose their own topics. (→ make it an obligation)"],prompt:"How does the meaning change? Would you use different modals in a formal report vs. a persuasive letter?"},{title:"You Do — Your Turn",instruction:"Complete each sentence with the modal that best fits the context.",tasks:["Doctors ___ (must/might/could) wash their hands before treating patients.","With practice, anyone ___ (should/might/must) improve their writing.","The council ___ (could/must/should) consider building a new cycle path — it would benefit everyone.","✦ Bonus: Write a paragraph arguing for a school improvement. Use at least four different modal verbs and label the degree of certainty each one expresses."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Modal verbs: possibility & obligation",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Modal verbs (must, should, could, would, might, may, will, shall) are auxiliary verbs that express degrees of possibility (might, may, could), recommendation (should), obligation (must), or conditionality (would). They do not change form for person or number and are always followed by the base form of the main verb." Understanding modals enables students to express nuance and certainty in persuasive and formal writing.'},{code:"Writing — Composing (Practice)",label:"Modals for persuasive nuance",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to select language that is "fit for purpose and audience." In persuasive writing, modal choice directly signals the writer's degree of certainty and the strength of their claim — "must" is much stronger than "might." This lesson develops conscious modal selection as a persuasive writing strategy.`}]),Wednesday:g("Show-don't-tell technique",`Writing — Composing (Practice) & Vocabulary (Practice): show-don't-tell means conveying emotion and character through action, dialogue, and detail rather than stating it directly; students transform "telling" sentences into "showing" passages.`,{title:"I Do — Don't Tell Me, Show Me",instruction:'"Telling" states the emotion directly. "Showing" reveals it through action, sensation, or detail — and trusts the reader to feel it.',example:`Tell: "She was nervous." → Show: "Her hands wouldn't stay still. She kept checking the clock. When her name was called, her voice came out smaller than she intended."`,demonstration:`I didn't say "nervous" once. But every detail — shaking hands, clock-watching, the small voice — creates that feeling in the reader. Showing gives the reader an experience. Telling gives them information.`,tip:"When you write an emotion word (nervous, excited, sad), ask: what does this LOOK like? What does the body do? What does the person say or avoid saying?"},{title:"We Do — Transform Together",instruction:'Transform each "telling" sentence into a "showing" passage of 2–3 sentences.',sentences:["He was embarrassed.","The crowd was excited.","She was devastated by the news."],prompt:"What does each emotion look like physically? What actions or details reveal it without naming it?"},{title:"You Do — Your Turn",instruction:'Transform each "telling" sentence into a "showing" passage. Do not use the emotion word.',tasks:["She was furious.","He was terrified.","They were overjoyed.","She felt guilty.","✦ Bonus: Write a scene of 5–6 sentences where a character is in a difficult situation. Never name the emotion — only show it through actions, dialogue, and detail."]},[{code:"Writing — Composing (Practice)",label:"Show-don't-tell in narrative",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including the show-don't-tell technique. Rather than stating emotions directly, students reveal them through character action, body language, dialogue, and sensory detail — giving the reader an experience rather than information. This is a key narrative craft skill explicitly associated with Phase 2 composing.`},{code:"Writing — Vocabulary (Practice)",label:"Replacing emotion words with showing detail",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." Show-don't-tell is a vocabulary discipline — instead of defaulting to the emotion word, students select the specific physical details (shaking hands, a small voice) that carry the emotional truth more powerfully.`}]),Thursday:g("Editing: fixing poorly punctuated dialogue","Writing — Writing Process (Practice): students apply the five dialogue punctuation rules to identify and correct errors in modelled and their own writing.",{title:"I Do — The Dialogue Audit",instruction:"I'll use the five dialogue rules as a checklist to audit a passage of dialogue — finding every error and fixing it systematically.",example:"Checklist: ☐ Speech marks around spoken words ☐ Comma before speech tag (not full stop) ☐ Speech tag not capitalised ☐ New speaker = new line ☐ Punctuation inside speech marks",demonstration:'"come in" said the ranger, "and close the gate behind you." — errors: no speech marks, comma in wrong place, speech tag capitalised ("And"), "gate" should be lowercase. Fixed: "Come in," said the ranger. "And close the gate behind you."',tip:"Check one rule at a time — don't try to fix everything in one read-through."},{title:"We Do — Class Dialogue Audit",instruction:"Find and fix every dialogue punctuation error in this passage.",sentences:[`"I don't think we should go in" said Mia. Caleb replied "but we've come all this way." "What if there's someone in there, Mia whispered. "Then we knock" said Caleb. He reached out and rapped on the door.`],prompt:"Go through rule by rule. How many errors are there in total?"},{title:"You Do — Your Turn",instruction:"Rewrite this dialogue passage with all errors corrected.",tasks:["this is amazing whispered Hemi.","What is it asked his sister.",`"A tuatara, he said, I've never seen one this close before.`,'"Should we take a photo she asked.',`"Yes, but quietly. He's watching us."`,"✦ Bonus: Write a 6-line dialogue between two characters discovering something surprising in the bush. Apply all 5 rules perfectly — then swap with a partner to check."]},[{code:"Writing — Writing Process (Practice)",label:"Editing dialogue punctuation",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking punctuation." This lesson applies the five dialogue punctuation rules as a systematic editing checklist — teaching students to audit dialogue rule by rule rather than trying to catch all errors in a single reading, a strategy that significantly improves accuracy.'},{code:"Writing — Punctuation (Practice)",label:"Applying dialogue conventions accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including dialogue conventions. Dialogue punctuation is a cluster of related rules that must be applied simultaneously — speech marks, comma/full stop choice, capitalisation, new lines. This lesson builds automaticity through targeted practice on poorly punctuated passages.'}])},3:{Monday:g("Connotation: positive vs. negative word choice","Writing — Vocabulary (Knowledge): words carry connotations (emotional associations) beyond their literal meaning; students select words with connotations that match their intended effect on the reader.",{title:"I Do — The Hidden Message in a Word",instruction:"Two words can have almost the same meaning but completely different connotations — the emotional baggage they carry. Watch how choosing between them changes the reader's response.",example:'"The politician was <u>determined</u>." vs. "The politician was <u>stubborn</u>."',demonstration:'Same idea — but "determined" is positive (admirable, purposeful) and "stubborn" is negative (inflexible, difficult). Neither is more "accurate" — the choice depends on how you want the reader to feel about the politician. Connotation is how writers guide reader response without being obvious about it.',tip:"When you choose a word, ask: is the connotation positive, negative, or neutral? Does that match the effect I want?"},{title:"We Do — Spot the Connotation",instruction:"For each pair of words, identify the positive and negative connotation, then use each in a sentence that makes the connotation clear.",sentences:["childlike / childish","thrifty / miserly","assertive / aggressive"],prompt:"What emotional response does each word create? How would using the wrong one mislead the reader?"},{title:"You Do — Your Turn",instruction:"Choose the word with the connotation that matches the context. Explain your choice.",tasks:["The protest was ___ (passionate / fanatical) — the writer wants to show the protesters sympathetically.","The old cottage was ___ (quaint / dilapidated) — the writer wants to show it as charming.","He was ___ (thrifty / miserly) — the writer wants to show a negative character trait.","✦ Bonus: Write two versions of a description of the same person — one using words with positive connotations, one with negative. Read them aloud. How does the reader feel differently about the same character?"]},[{code:"Writing — Vocabulary (Knowledge)",label:"Connotation & word choice",detail:`NZC Phase 2 Writing — Vocabulary (Knowledge): "Words carry connotations — emotional associations beyond their literal meaning. Words with similar denotations (dictionary meanings) can have very different connotations: 'determined' (positive) and 'stubborn' (negative) both mean 'refuses to change position,' but they guide the reader's response differently. Understanding connotation is a core component of deliberate vocabulary selection at Years 5–6."`},{code:"Writing — Vocabulary (Practice)",label:"Selecting words for reader response",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson makes connotation visible as a writing tool — students practise choosing between synonyms not on the basis of denotation but on the basis of the emotional response they want to create in the reader.'}]),Tuesday:g("Subject-verb agreement with collective nouns in narrative","Writing — Sentence Structure (Knowledge): collective nouns are typically singular in New Zealand English; students apply SVA rules to collective nouns in narrative contexts, maintaining consistency throughout a passage.",{title:"I Do — The Group as One",instruction:"In NZ English (and most standard varieties), collective nouns are treated as singular — they take a singular verb. Watch me apply this in narrative context.",example:'"The kapa haka group <u>was</u> magnificent." ✓ | "The kapa haka group <u>were</u> magnificent." ✗ (in NZ/US English)',demonstration:'"The team is ready." "The pod of dolphins was heading south." "The herd of cattle moves slowly." In each case, the collective noun = singular = singular verb. The most common error is "The team were" — avoid this in formal and narrative writing.',tip:'In NZ English, collective noun = singular. "The team is" not "the team are." "The class was" not "the class were."'},{title:"We Do — Fix the Agreement",instruction:"Fix the subject-verb agreement in each sentence.",sentences:["The pod of dolphins were leaping alongside the waka.","A flock of kōtuku were standing at the edge of the estuary.","The group of students were rehearsing their speech."],prompt:"What is the subject? Is it a collective noun? In NZ English, what verb form does it require?"},{title:"You Do — Your Turn",instruction:"Choose the correct verb form for each collective noun subject.",tasks:["The committee ___ (has/have) made its decision.","A school of fish ___ (was/were) visible through the clear water.","The whānau ___ (is/are) gathering for the tangi.","The pack of dogs ___ (was/were) silent as the hunter approached.","✦ Bonus: Write a narrative paragraph of 5 sentences about a group of animals or people. Use at least three different collective nouns with correct SVA throughout."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"SVA with collective nouns",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "In New Zealand English, collective nouns (team, group, flock, pod, herd, class, whānau) are treated as singular and take singular verb forms. This contrasts with British English, where collective nouns may be treated as plural. Students apply this convention consistently in formal and narrative writing." Maintaining SVA accuracy throughout a narrative passage is a key Phase 2 expectation.'},{code:"Writing — Writing Process (Practice)",label:"Editing for SVA consistency in narrative",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." This lesson applies SVA knowledge in the context of narrative editing — students identify collective noun subjects throughout a passage and check that every corresponding verb is in the correct singular form, building the habit of targeted grammatical checking.'}]),Wednesday:g("Compound sentences: building tension in narrative",`Writing — Sentence Structure (Practice): compound sentences using "but," "yet," and "so" create tension, contrast, and consequence in narrative; students select conjunctions deliberately to shape the reader's emotional experience.`,{title:"I Do — Tension Through Contrast",instruction:'In narrative, compound sentences using "but" and "yet" are powerful tension-builders — they set up an expectation and then deny it.',example:`"She reached for the door, <u>but</u> it wouldn't open." | "He had practised a hundred times, <u>yet</u> his mind went blank."`,demonstration:'"But" creates contrast: the reader expects success, but gets failure. "Yet" does the same but with even more emphasis on the surprise. "So" shows consequence: "The path was blocked, <u>so</u> she turned back." Each conjunction shapes how the reader experiences the narrative moment.',tip:`"But/yet" = expectation denied (tension). "So" = consequence follows (momentum). Choose the conjunction that shapes the reader's feeling, not just the grammatical connection.`},{title:"We Do — Choose for Effect",instruction:'Complete each sentence with "but," "yet," or "so" — choosing for emotional effect, not just grammar.',sentences:["She had the map, ___ the path had completely disappeared.","The wind had died down, ___ he lit the fire quickly.","He had been waiting for this moment for years, ___ now that it had arrived, he felt nothing."],prompt:"Which conjunction creates the most tension? Which creates momentum? Does the choice change the reader's experience?"},{title:"You Do — Your Turn",instruction:"Write compound sentences using the conjunction shown to create the effect described.",tasks:['Use "but" to create contrast: she was ready → something goes wrong.','Use "yet" to create surprise: he had prepared → the opposite happens.','Use "so" to create momentum: something difficult happens → character takes action.','✦ Bonus: Write a paragraph of 5 sentences about a character overcoming a challenge. Use "but," "yet," and "so" at least once each — deliberately choosing each one for its effect on the reader.']},[{code:"Writing — Sentence Structure (Practice)",label:"Compound sentences for narrative tension",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity" and to use conjunctions deliberately. In narrative, the choice between "but," "yet," and "so" shapes the emotional experience — "but/yet" create contrast and denied expectation (tension); "so" creates consequence and forward momentum. This lesson develops junction selection as a craft decision, not a grammatical default.'},{code:"Writing — Composing (Practice)",label:"Shaping reader experience through conjunction choice",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader." This lesson applies compound sentence structure as a composing tool — teaching students that the conjunction they choose between two clauses directly shapes what the reader feels at that moment. "She reached for the door, but it wouldn't open" does something very different to "She reached for the door, and it opened."`}]),Thursday:g("Editing: upgrading adjectives for atmosphere","Writing — Vocabulary (Practice) & Writing Process (Practice): students identify weak adjectives in narrative writing and replace them with words that create specific atmosphere and mood.",{title:"I Do — Atmosphere Is in the Adjectives",instruction:"In narrative, adjectives do more than describe — they create mood and atmosphere. Watch me upgrade weak adjectives to ones that carry emotional weight.",example:'"The <u>dark</u> house stood at the end of the <u>quiet</u> street." → "The <u>decrepit</u> house stood at the end of the <u>deserted</u> street."',demonstration:`"Dark" just tells us there's no light. "Decrepit" tells us it's old, neglected, possibly dangerous — it creates unease. "Quiet" is neutral. "Deserted" implies abandonment, something wrong. The upgraded adjectives carry connotation as well as description.`,tip:"Ask of each adjective: does this create mood, or just describe? If just description — find an adjective that does both."},{title:"We Do — Atmosphere Upgrade",instruction:"Replace each underlined adjective with one that creates a specific atmosphere.",sentences:["The <u>big</u> waves crashed against the <u>old</u> lighthouse.","She walked into the <u>small</u> room with <u>dirty</u> windows.","The <u>nice</u> garden had <u>pretty</u> flowers in every bed."],prompt:"What atmosphere do you want to create? Choose adjectives whose connotations match that mood."},{title:"You Do — Your Turn",instruction:"Rewrite this passage, replacing every plain adjective with one that creates a specific atmosphere (you choose the mood — eerie, peaceful, threatening, joyful).",tasks:["The old building sat beside the big river. Its dark windows looked out over the quiet water. A small boat moved slowly past. The grey sky hung low overhead.","✦ Bonus: Write the same description twice — once to create an eerie atmosphere and once to create a peaceful one. The only difference should be your adjective choices."]},[{code:"Writing — Vocabulary (Practice)",label:"Adjectives for atmosphere",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." In narrative writing, adjectives are the primary tool for creating atmosphere — this lesson teaches students to choose adjectives not just for their denotative accuracy but for the connotative mood they create, turning description into experience.'},{code:"Writing — Writing Process (Practice)",label:"Adjective audit in narrative revision",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson develops the adjective audit as a targeted revision strategy: identify every adjective, ask 'does this create atmosphere or just describe?', and upgrade those that only describe — building the skill of reading one's own writing as a reader would experience it.`}])},4:{Monday:g("Apostrophes: tricky plurals (children's, people's)","Writing — Punctuation (Knowledge): irregular plural nouns that do not end in -s form their possessive by adding 's (apostrophe then s), not s' ; students identify and apply this rule accurately.",{title:"I Do — When the Plural Doesn't End in S",instruction:"Most plurals end in -s (cats → cats'). But irregular plurals don't follow this rule. With irregular plurals, we add 's — the same as singulars.",example:"children → children's (not childrens') | people → people's | men → men's | women → women's",demonstration:`"The children's books were on the shelf." "Children" is already plural (no -s at the end), so we add 's — NOT s'. Common mistake: "childrens'" — this is wrong because "childrens" isn't even a word. The rule: if the plural already ends in -s → just add '. If it doesn't end in -s → add 's.`,tip:`End in s? Just add '. Don't end in s? Add 's. Test: "The ___ needs an apostrophe. Does the plural end in -s?"`},{title:"We Do — Fix the Apostrophes",instruction:"Fix the apostrophe in each phrase.",sentences:["the childrens playground","the peoples decision","the womens changing room","the mens rugby team"],prompt:"Does the plural end in -s? If not, where does the apostrophe go?"},{title:"You Do — Your Turn",instruction:"Rewrite each phrase with a correctly placed possessive apostrophe.",tasks:["the teeth of the fish →","the voices of the people →","the coats belonging to the men →","the ideas of the children →","✦ Bonus: Write 5 sentences using possessive forms of these irregular plurals: children, people, men, women, teeth."]},[{code:"Writing — Punctuation (Knowledge)",label:"Apostrophes with irregular plurals",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "Irregular plural nouns that do not end in -s (children, people, men, women, teeth, mice) form their possessive by adding 's — the same pattern as singular nouns. The error of writing 'childrens'' or 'peoples'' creates a non-word before the apostrophe. Students learn the decision rule: if the plural ends in -s, add only '; if it does not end in -s, add 's."`},{code:"Writing — Punctuation (Practice)",label:"Applying possessive apostrophes accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including apostrophes for possession. This lesson addresses a specific and frequently misapplied rule — possessives with irregular plurals — giving students a reliable two-question test (Does the plural end in -s? Where does the apostrophe go?) that they can apply independently when editing their own writing.'}]),Tuesday:g("Pronoun reference: avoiding ambiguity in narrative","Writing — Sentence Structure (Knowledge): pronoun reference is ambiguous when a pronoun could refer to more than one noun; students identify ambiguous pronoun use in narrative and revise it for clarity.",{title:'I Do — Who Is "He"?',instruction:"A pronoun must refer unambiguously to one specific noun. When two or more nouns are present, the pronoun can become confusing.",example:'"Jake told Marcus that <u>he</u> had won the prize." — Who won? Jake or Marcus? Ambiguous!',demonstration:`Fixed options: "Jake told Marcus that <u>Jake</u> had won the prize." Or: "Jake told Marcus that <u>Marcus</u> had won the prize." Or: "Jake told Marcus, 'I won the prize.'" The fix is to either repeat the name, restructure the sentence, or use direct speech.`,tip:"After writing a sentence with a pronoun, cover up the pronoun and ask: could this refer to more than one person or thing? If yes — fix it."},{title:"We Do — Fix the Ambiguity",instruction:"Each sentence has an ambiguous pronoun. Rewrite it so the reference is clear.",sentences:["Hemi and his dad argued until he apologised.","The kaiako put the book on the desk after she had marked it.","The hawk and the kārearea circled together until it landed."],prompt:"Who or what does the pronoun refer to? How can we restructure to make it clear?"},{title:"You Do — Your Turn",instruction:"Identify the ambiguous pronoun and rewrite the sentence for clarity.",tasks:["Maya waved to Aroha as she crossed the field.","The captain spoke to the referee after he made the decision.","Finn's dog chased the cat until it disappeared under the fence.","She told her friend that her story was the best in the class.","✦ Bonus: Write a paragraph of 5 sentences involving two characters. Use pronouns — but make sure every pronoun reference is completely unambiguous throughout."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Ambiguous pronoun reference",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Pronoun reference is ambiguous when a pronoun could plausibly refer to more than one noun in the sentence or surrounding text. Ambiguity can be resolved by repeating the specific noun, restructuring the sentence, or using direct speech." Identifying and correcting ambiguous pronoun reference is a key grammatical accuracy skill at Years 5–6.'},{code:"Writing — Writing Process (Practice)",label:"Editing for pronoun clarity",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." This lesson applies pronoun knowledge as an editing skill — the "cover up" test gives students a practical, repeatable strategy for catching pronoun ambiguity in their own narrative writing before it confuses the reader.'}]),Wednesday:g("Narrative paragraph topic sentences","Writing — Text Structure (Knowledge & Practice): narrative paragraphs are organised around a key moment or shift; a narrative topic sentence signals the focus of the paragraph and the stage of the story.",{title:"I Do — Paragraph Focus in Narrative",instruction:"In narrative, paragraphs mark shifts — in time, place, character focus, or the story's rising tension. A strong topic sentence signals what shift this paragraph brings.",example:'"The moment they reached the cave entrance, everything changed." | "It was in the hours just before dawn that she made her decision."',demonstration:'Both topic sentences tell us: (1) the time/place of the paragraph, (2) something significant is happening — a shift, a decision, a change. They invite the reader forward. Compare: "They reached the cave." — no sense of significance. "The moment they reached the cave entrance, everything changed." — we feel the hinge point.',tip:"A narrative topic sentence should mark a shift and create a sense of significance. Ask: what changes in this paragraph? Signal that change in the opening sentence."},{title:"We Do — Write the Topic Sentence",instruction:"Write a topic sentence for each narrative paragraph description.",sentences:["Paragraph: the character arrives somewhere new and everything feels unfamiliar.","Paragraph: the character makes a difficult decision.","Paragraph: the climax — the moment of highest tension."],prompt:"What is the shift or hinge point in each paragraph? How does your topic sentence signal it?"},{title:"You Do — Your Turn",instruction:"Write a narrative topic sentence for each story stage.",tasks:["The story's opening — the character in their ordinary world.","The moment the problem appears.","The character's lowest point.","The resolution — something has changed.","✦ Bonus: Write a full narrative paragraph of 5–6 sentences for one of your topic sentences above."]},[{code:"Writing — Text Structure (Knowledge)",label:"Narrative paragraph organisation",detail:'NZC Phase 2 Writing — Text Structure (Knowledge): "In narrative writing, paragraphs mark shifts in time, place, character focus, or tension. A narrative topic sentence signals the focus of the paragraph and the stage of the story — what changes or matters in this paragraph — orienting the reader within the story structure." Students at Years 5–6 are expected to use paragraph organisation deliberately across all text types, including narrative.'},{code:"Writing — Text Structure (Practice)",label:"Structuring narrative paragraphs",detail:`NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail" in narrative writing. This lesson develops the skill of writing narrative topic sentences that do two jobs simultaneously: signal the paragraph's focus and create narrative momentum — moving the story forward with each new paragraph.`}]),Thursday:g("Editing: pronoun clarity in narrative","Writing — Writing Process (Practice): students apply pronoun reference checking to narrative passages, identifying and correcting ambiguous pronoun use to improve reader clarity.",{title:"I Do — The Pronoun Audit in Narrative",instruction:"Today I'll audit a narrative passage specifically for pronoun clarity — checking every pronoun has an unambiguous referent.",example:"Audit method: underline every pronoun → draw an arrow to its intended referent → check: could the arrow point anywhere else? If yes → fix.",demonstration:'"Tama ran towards the fence where Hemi was standing. He jumped over it and landed on the other side." — "He" could be Tama or Hemi. "It" could be the fence. Fix: "Tama ran towards the fence where Hemi was standing. Tama jumped over the fence and landed on the other side."',tip:"Read your narrative with fresh eyes. Every time you hit a pronoun, ask: is there any doubt who this refers to?"},{title:"We Do — Narrative Pronoun Audit",instruction:"Underline every pronoun in this passage. Draw an arrow to its referent. Fix any that are ambiguous.",sentences:["Aroha and her cousin Maia were gathering harakeke by the stream. She passed the leaves to her one by one. Then she said something she couldn't hear over the water. She asked her to repeat it. They looked at each other and laughed."],prompt:"How many ambiguous pronouns are there? What is the clearest fix for each?"},{title:"You Do — Your Turn",instruction:"Rewrite this narrative passage so every pronoun reference is completely clear.",tasks:["Kai met his uncle at the jetty. He helped him tie up the boat and carry the gear to the shed. He said they should head out again tomorrow — the snapper had been running well. He nodded and said he'd be there before sunrise.","✦ Bonus: Write a narrative paragraph of 5–6 sentences with two characters. After writing, do the pronoun audit on your own work — underline, arrow, check, fix."]},[{code:"Writing — Writing Process (Practice)",label:"Pronoun audit in narrative revision",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." The pronoun audit — underline every pronoun, draw an arrow to its referent, check for ambiguity — is a specific, targeted revision strategy for narrative writing where multiple characters create a higher risk of pronoun confusion. This lesson builds the habit of reading through a reader's eyes, not a writer's.`},{code:"Writing — Sentence Structure (Knowledge)",label:"Pronoun reference clarity",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Pronouns must refer unambiguously to their antecedent. In narrative writing involving multiple characters, pronoun reference errors are especially common and can significantly disrupt the reader's ability to follow the story." This editing lesson connects grammatical knowledge (pronoun-antecedent agreement) directly to the reader experience — ambiguous pronouns confuse readers; clear pronouns enable fluent story comprehension.`}])},5:{Monday:g("Ellipsis for suspense and trailing off","Writing — Punctuation (Knowledge): an ellipsis (...) marks an intentional pause, creates suspense, or shows trailing thought; students use it deliberately for narrative effect and distinguish it from other uses.",{title:"I Do — The Pause That Does Work",instruction:"An ellipsis (...) has three uses in narrative: (1) suspense — building anticipation before a reveal, (2) trailing off — a thought or voice that fades, (3) hesitation — a character unsure of what to say. Watch me use each one.",example:`Suspense: "She reached for the handle, turned it slowly... and the door swung open." | Trailing: "I thought I saw something in the water... but it was probably nothing." | Hesitation: "I just... I don't know what to say."`,demonstration:"In each case the ellipsis does specific work: it slows the reader down, creates a gap, and forces a moment of uncertainty. Used too often, it loses its power. Used precisely — it makes the reader lean in.",tip:"Each ellipsis must create a pause that matters. If you can remove it and lose nothing — remove it."},{title:"We Do — Choose the Right Use",instruction:"Add an ellipsis to each sentence where it would create the best effect. Label the use (suspense/trailing/hesitation).",sentences:["He opened the letter and began to read the words hit him like a wave.",'"I thought I knew the answer but now I am not so sure."',"She turned around slowly expecting nothing and then she saw it."],prompt:"Where does the pause create the most suspense or feeling? Is it suspense, trailing, or hesitation?"},{title:"You Do — Your Turn",instruction:"Add an ellipsis to create the effect shown in brackets.",tasks:["She reached into the box [suspense] and pulled out a small golden key.",`"I suppose it doesn't really matter anymore [trailing]"`,`"I just [hesitation] I don't know how to say this."`,"The footsteps grew louder [suspense] then stopped.","✦ Bonus: Write a paragraph of narrative using the ellipsis at least twice — each time for a different purpose. Label each use."]},[{code:"Writing — Punctuation (Knowledge)",label:"Ellipsis: uses and effects",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "An ellipsis (...) is used in narrative to: (1) create suspense by introducing a pause before a key moment; (2) show a trailing or fading thought; (3) indicate hesitation or an interrupted thought in dialogue. It is distinct from its academic use (indicating omitted text in quotation). The ellipsis is a high-impact punctuation mark that loses its power if overused." Students learn to deploy it purposefully.'},{code:"Writing — Punctuation (Practice)",label:"Using ellipsis for narrative effect",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." The ellipsis is one of the most expressive punctuation marks available to narrative writers — but only when used with restraint and purpose. This lesson develops both the rule knowledge (three legitimate uses) and the craft discipline (each ellipsis must earn its place) that characterise sophisticated punctuation use at Phase 2.'}]),Tuesday:g("Adjective placement: before and after nouns","Writing — Sentence Structure (Knowledge): adjectives typically precede the noun in English, but post-positive placement (adjective after the noun) creates emphasis and a more formal or literary tone; students use both positions deliberately.",{title:"I Do — Where You Put It Changes the Feeling",instruction:'In English, adjectives usually come before the noun ("the ancient tree"). But sometimes placing an adjective after the noun creates a different, more emphatic effect.',example:'"The <u>ancient</u> tree stood alone." vs. "The tree, <u>ancient</u> and gnarled, stood alone."',demonstration:`Post-positive placement ("ancient and gnarled" after "tree") gives the adjectives a more dramatic, literary quality — they feel added, emphasised, foregrounded. It's more common in formal or literary writing. "The warrior, fearless and unyielding, stepped forward" feels more epic than "The fearless, unyielding warrior stepped forward."`,tip:"Pre-noun placement (normal, neutral). Post-noun placement (emphasised, literary, dramatic). Choose based on the effect you want."},{title:"We Do — Try Both Positions",instruction:"Rewrite each sentence with the adjective in the other position. Discuss what changes.",sentences:["The exhausted, mud-covered runner crossed the finish line.","The mountain, vast and white, filled the horizon.","A curious, quick-eyed tūī landed on the branch."],prompt:"Which position sounds more dramatic? Which is more natural? Which fits better in a narrative?"},{title:"You Do — Your Turn",instruction:"Write each sentence twice — adjective before the noun and after. Choose the version you prefer and explain why.",tasks:['Use "ancient" and "crumbling" to describe a building.','Use "fierce" and "undefeated" to describe a warrior.','Use "silent" and "deep" to describe a lake.',"✦ Bonus: Write a paragraph of 4 sentences about a dramatic landscape. Use post-positive adjective placement at least twice for effect."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Adjective placement: pre- and post-nominal",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "In English, adjectives typically precede the noun they modify (pre-nominal position: 'the ancient tree'). However, adjectives can also follow the noun (post-nominal or post-positive position: 'the tree, ancient and gnarled') for emphasis and literary effect. Post-positive placement is characteristic of formal, poetic, and literary registers." Students learn to distinguish the two positions by their effect, not just their grammar.`},{code:"Writing — Composing (Practice)",label:"Adjective position as a craft choice",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader." Adjective placement is a composing tool — putting adjectives before the noun is neutral and natural; placing them after the noun creates drama and emphasis. This lesson develops awareness of placement as a deliberate craft choice available to students in their narrative and descriptive writing.'}]),Wednesday:g("Sentence length for dramatic effect","Writing — Sentence Structure (Practice) & Composing (Practice): students control sentence length deliberately across a narrative passage, using short sentences for tension and impact and long sentences for atmosphere and detail.",{title:"I Do — The Rhythm of a Narrative",instruction:"Great narrative writing has rhythm — it speeds up and slows down deliberately. Short sentences = fast, urgent, tense. Long sentences = slow, atmospheric, contemplative. Watch me control the rhythm.",example:`"For months she had been planning this moment, imagining every detail, rehearsing every line she would say. Now she stood at the door. Her hand wouldn't move. She knocked."`,demonstration:`The long sentence covers months of preparation — it sweeps time. Then: "Now she stood at the door." — a sudden stop. "Her hand wouldn't move." — tension. "She knocked." — one beat, one action, maximum impact. The rhythm creates the emotional experience.`,tip:"Before a key moment: slow down with a long sentence. In the moment: use short sentences. After: let the rhythm breathe."},{title:"We Do — Control the Rhythm",instruction:"Rewrite this flat passage by varying sentence length deliberately to create tension.",sentences:["The cave was dark. There was water dripping. She walked in. It was cold. There was a sound. She stopped. She looked around. She saw something glowing."],prompt:"Which moments need short sentences? Where could we use one longer sentence to build atmosphere before the tension?"},{title:"You Do — Your Turn",instruction:"Write a narrative passage of 6 sentences about this scene: a character approaching something they are afraid of. Deliberately vary sentence length for effect.",tasks:["Sentence 1: long — establish the setting and backstory.","Sentences 2–3: medium — movement towards the thing.","Sentences 4–5: short — rising tension.","Sentence 6: very short — the moment of arrival or decision.","✦ Bonus: Label each sentence with its intended effect: atmosphere / movement / tension / impact."]},[{code:"Writing — Sentence Structure (Practice)",label:"Sentence length for dramatic effect",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity," deliberately using sentence length as a pacing tool. Long sentences establish atmosphere and sweep time; short sentences create urgency, tension, and impact. This lesson develops students' ability to plan and execute sentence length variation across a whole passage — not just in isolated exercises.`},{code:"Writing — Composing (Practice)",label:"Controlling narrative pace and rhythm",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including controlling pace and rhythm. This lesson applies sentence length as a composing tool at the passage level — students plan which moments need which sentence lengths before writing, developing the pre-compositional awareness of rhythm that characterises effective narrative writers at Phase 2.'}]),Thursday:g("Peer editing: punctuation for effect","Writing — Writing Process (Practice): students give and receive targeted feedback on whether punctuation choices create the intended effect in narrative writing, going beyond accuracy to assess craft.",{title:"I Do — Punctuation as Craft",instruction:'Today we move beyond "is this punctuation correct?" to "is this punctuation doing a job?" Watch me evaluate a passage for both accuracy AND effect.',example:"Checklist: ☐ Ellipsis used for genuine suspense/trail/hesitation ☐ Short sentences for tension ☐ Dialogue punctuation correct ☐ Exclamation marks used sparingly ☐ Dashes for emphasis",demonstration:"I read the passage twice — once for accuracy (are the rules applied correctly?), once for effect (is each mark doing something for the reader?). A correctly placed comma that adds nothing is still a weak punctuation choice.",tip:'Feedback should be specific and rule-based: "Your ellipsis on line 3 creates real suspense" or "The exclamation mark on line 2 would be stronger if it was the only one in the paragraph."'},{title:"We Do — Craft Evaluation",instruction:"Evaluate this passage for both accuracy and effect. Mark what works and what could be improved.",sentences:[`"Look out!!!" she screamed. The wave was coming... it was huge... she didn't know what to do... she ran. It crashed. She was safe! It had missed her! She couldn't believe it!`],prompt:"Which punctuation marks work well? Which are overused or misused? How would you improve it?"},{title:"You Do — Your Turn",instruction:"Swap a piece of narrative writing with a partner. Evaluate each other's punctuation for both accuracy and craft effect.",tasks:["✦ Check 1: Are dialogue conventions correct throughout?","✦ Check 2: Does the ellipsis (if used) create genuine suspense or trailing?","✦ Check 3: Are exclamation marks used sparingly (max 1–2 in a passage)?","✦ Check 4: Are short sentences used for tension at key moments?","✦ Check 5: Write one specific piece of feedback — name the line, name the mark, explain the effect."]},[{code:"Writing — Writing Process (Practice)",label:"Peer editing for craft and accuracy",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "share writing with others and respond to feedback to improve their work." This lesson elevates peer editing beyond accuracy-checking to craft evaluation — students assess whether punctuation choices create the intended effect, not just whether rules are applied correctly. Giving specific, evidence-based craft feedback is an explicitly expected Phase 2 writing practice.'},{code:"Writing — Punctuation (Practice)",label:"Punctuation as a narrative craft tool",detail:`NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This lesson consolidates Term 3's punctuation learning — ellipsis, dialogue conventions, exclamation marks, dashes — in a peer editing context where students evaluate both dimensions: correctness (is the rule applied?) and craft (is it doing something for the reader?). This dual evaluation develops sophisticated punctuation awareness at Phase 2.`}])},6:{Monday:g("Figurative language: similes and metaphors",'Writing — Vocabulary (Knowledge) & Composing (Practice): similes compare using "like" or "as"; metaphors state a direct comparison; both are language devices that create vivid images and deepen meaning for the reader.',{title:"I Do — When One Thing Becomes Another",instruction:'Similes and metaphors both make comparisons — but in different ways. Similes use "like" or "as." Metaphors state the comparison directly. Watch me use both.',example:'Simile: "The haka was <u>like thunder</u> rolling across the ground." | Metaphor: "The haka <u>was thunder</u> — it shook the earth beneath our feet."',demonstration:'The simile says: these two things are similar. The metaphor says: this thing IS that thing. The metaphor is more direct and usually more powerful. Both create a vivid image the reader can experience — much stronger than "the haka was loud."',tip:"Avoid clichéd comparisons (white as snow, brave as a lion). Find a comparison the reader has never seen before — something specific to your world and context."},{title:"We Do — Simile or Metaphor?",instruction:"Identify whether each is a simile or metaphor, then discuss what image it creates.",sentences:["The tūī's song was liquid silver falling through the morning air.","She moved like a shadow through the crowd, silent and unseen.","His anger was a stone wall — impossible to get past."],prompt:"What is being compared to what? Why is this comparison effective? Could you make it even more specific?"},{title:"You Do — Your Turn",instruction:"Write the comparison as instructed.",tasks:["Write a simile comparing the sea to something unexpected.","Write a metaphor describing the feeling of stage fright.","Write a simile for the sound of heavy rain.","Write a metaphor for the feeling of hearing good news.","✦ Bonus: Write a descriptive paragraph of 4 sentences about a NZ natural setting. Include at least one simile and one metaphor. Avoid clichés."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Figurative language: similes & metaphors",detail:`NZC Phase 2 Writing — Vocabulary (Knowledge): "Language devices such as simile (comparing using 'like' or 'as') and metaphor (a direct comparison stating one thing is another) create vivid images and deepen meaning for the reader. Effective figurative language is specific and original — it finds a comparison the reader has not encountered before. Clichéd comparisons (white as snow) have lost their power through overuse." Students learn to evaluate and create original figurative language.`},{code:"Writing — Composing (Practice)",label:"Using figurative language for effect",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use language devices, including simile and metaphor, to create specific effects and engage the reader." This lesson develops two skills simultaneously: the ability to identify the structural difference between simile and metaphor, and the craft discipline of creating original comparisons that illuminate meaning rather than defaulting to clichés. Both are Phase 2 composing expectations.'}]),Tuesday:g("Adverbs of degree: very, quite, rather, extremely","Writing — Sentence Structure (Knowledge): adverbs of degree modify adjectives and other adverbs to indicate intensity; students understand that vague degree adverbs (very, quite) are often better replaced with a more precise adjective.",{title:"I Do — How Intense Is It?",instruction:`Adverbs of degree modify adjectives to show how much: very cold, quite cold, rather cold, extremely cold, slightly cold. But "very" is so overused it's often meaningless — and there's usually a better option.`,example:'"Very cold" → "freezing" | "Very happy" → "elated" | "Very tired" → "exhausted"',demonstration:'"Very" adds degree but adds no new meaning. "Freezing" says the same as "very cold" in one precise word. The rule: if "very + adjective" can be replaced by a single precise adjective — replace it. Not always — "very slightly cold" or "quite uncertain" sometimes need the degree adverb. But "very nice" and "very good" never do.',tip:'Before writing "very," ask: is there a single word that means "very [adjective]"? If yes — use it.'},{title:"We Do — Replace the Degree Adverb",instruction:'Replace each "very + adjective" combination with a single precise adjective.',sentences:["The climb was very difficult.","She was very angry at the decision.","The storm was very dangerous."],prompt:"What single word captures the same meaning more precisely? Is there more than one option?"},{title:"You Do — Your Turn",instruction:'Replace "very" with a precise adverb of degree or a single more precise adjective.',tasks:["The water was very cold.","He was very scared when he heard the sound.","The performance was very impressive.","She spoke very quietly so no one would hear.",'✦ Bonus: Scan a piece of your own writing for every "very." Replace each one with either a stronger adjective or a more precise degree adverb (extremely, utterly, barely, almost).']},[{code:"Writing — Sentence Structure (Knowledge)",label:"Adverbs of degree",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Adverbs of degree (very, quite, rather, extremely, slightly, utterly, barely) modify adjectives and other adverbs to indicate intensity. 'Very' is the most overused degree adverb in English — it often weakens rather than strengthens a sentence because it adds degree without precision. Students learn to evaluate each degree adverb: if a single more precise adjective can replace 'very + adjective,' use it."`},{code:"Writing — Vocabulary (Practice)",label:"Replacing weak degree adverbs",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience" and to "consider the effect of word choice on the reader." This lesson applies that principle to degree adverbs — teaching students to interrogate every "very" and "quite" in their writing, replacing them with either a single precise adjective or a more exact degree adverb that genuinely changes the meaning.'}]),Wednesday:g("Descriptive sentences using the five senses","Writing — Composing (Practice) & Vocabulary (Practice): effective description engages multiple senses; students write sentences that appeal to sight, sound, smell, taste, and touch to create vivid, immersive settings.",{title:"I Do — Writing That Readers Can Experience",instruction:"Most student writing is almost entirely visual — it describes what things look like. But the most vivid writing engages all five senses. Watch me add layers of sensory detail to a bare description.",example:'Visual only: "The market was busy." → Five senses: "The market smelled of frying onions and damp earth. Vendors called their prices over the clatter of crates. Somewhere a child was crying. The wooden boards were slick under her feet."',demonstration:`I didn't say "it was busy" — I let the reader experience the busyness through their senses. Smell: frying onions, damp earth. Sound: vendors calling, crates, crying. Touch: slick boards. No sight at all — and yet the scene is vivid.`,tip:"After writing a descriptive passage, ask: have I only described what things LOOK like? Challenge yourself to include at least sound and one other sense."},{title:"We Do — Layer the Senses",instruction:"Add at least two sensory details (non-visual) to each setting.",sentences:["Setting: a beach after a storm.","Setting: a school kitchen during lunch preparation.","Setting: a pine forest at midday."],prompt:"What would you hear? Smell? Feel underfoot? Touch? Could you taste anything? Which sense creates the most atmosphere?"},{title:"You Do — Your Turn",instruction:"Write 3 sentences about each setting — at least one per sentence must engage a non-visual sense.",tasks:["Setting: a NZ beach at dawn.","Setting: a geothermal area near Rotorua.","Setting: a marae the morning of a gathering.","✦ Bonus: Write a 5-sentence description of any NZ setting. Challenge: do not describe what anything looks like — only engage sound, smell, touch, and taste."]},[{code:"Writing — Composing (Practice)",label:"Multi-sensory description",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including descriptive strategies that create vivid, immersive settings. Multi-sensory description — engaging sound, smell, touch, and taste as well as sight — is an explicitly expected composing skill at Phase 2, enabling students to write settings the reader can experience rather than merely picture.'},{code:"Writing — Vocabulary (Practice)",label:"Precise sensory vocabulary",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Writing multi-sensory description requires building vocabulary in each sensory domain — sound words (clatter, hiss, murmur), touch words (slick, rough, clammy), smell words (acrid, earthy, sharp). This lesson extends students' sensory vocabulary as a direct writing resource.`}]),Thursday:g("Editing: cutting unnecessary adverbs (very, really)",'Writing — Writing Process (Practice) & Vocabulary (Practice): students conduct a degree adverb audit, removing or replacing unnecessary "very" and "really" with precise adjectives or stronger verbs.',{title:'I Do — The "Very" Audit',instruction:`"Very" and "really" are often the weakest words in a sentence. Today I'll audit a passage for them — remove the ones that add nothing, and replace the others with a single precise word.`,example:'"The storm was really very bad and the waves were very high and it was really scary."',demonstration:'"Really very bad" → "ferocious." "Very high" → "towering." "Really scary" → "terrifying." New version: "The storm was ferocious. Towering waves crashed against the hull. Each second felt terrifying." Three precise adjectives replaced six weak modifier words.',tip:'Circle every "very" and "really" in your writing. Delete each one. If the sentence loses meaning — replace with a precise adjective. If it loses nothing — leave it deleted.'},{title:"We Do — Audit Together",instruction:'Remove or replace every "very" and "really" in this passage.',sentences:["The bush track was really narrow and very overgrown. It was really hard to see the path. The trees were very old and really tall and their roots made the ground really uneven. It was really beautiful but very difficult to walk."],prompt:'Which "very/really" can be simply deleted? Which need to be replaced with a precise word?'},{title:"You Do — Your Turn",instruction:'Rewrite this passage by removing or replacing every "very" and "really."',tasks:["The performance was really amazing. The dancers were very graceful and their movements were really precise. The music was very loud at times and really quiet at others. Everyone in the audience was really moved by the end.",'✦ Bonus: Take a paragraph from your own writing. Circle every "very" and "really." Delete or replace each one. Count how many words you removed — and assess whether the writing is stronger.']},[{code:"Writing — Writing Process (Practice)",label:"Degree adverb audit",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The degree adverb audit — circle every "very" and "really," delete each one, then decide whether to replace or leave deleted — is a specific, mechanical revision strategy that consistently improves the precision and energy of students' writing at Phase 2.`},{code:"Writing — Vocabulary (Practice)",label:"Replacing weak modifiers with precise adjectives",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." This lesson applies the degree adverb audit as a vocabulary revision strategy — teaching students that "very + adjective" is almost always replaceable by a single more precise adjective, and developing the habit of finding that word rather than settling for the weak modification.'}])},7:{Monday:g("Semicolons to join related ideas","Writing — Punctuation (Knowledge): a semicolon joins two independent clauses that are closely related in meaning; students distinguish this use from the colon and apply it accurately in narrative and informational writing.",{title:"I Do — Two Ideas, One Breath",instruction:"A semicolon joins two complete sentences that are so closely related they belong together — but aren't connected by a conjunction.",example:'"The tide was coming in fast; we had ten minutes to reach the rocks." | "The last kōwhai flower fell; summer was finally over."',demonstration:`Both sides of the semicolon must be complete sentences. The ideas must be closely related — close enough that a full stop would feel like too big a break. The semicolon says: these two thoughts belong together. Test: can you replace the semicolon with "and" or "but"? If yes — semicolon or conjunction both work. If no — the ideas aren't closely related enough.`,tip:"Semicolon test: (1) complete sentence on both sides ✓ (2) closely related ideas ✓ (3) no conjunction ✓ → semicolon works."},{title:"We Do — Semicolon or Full Stop?",instruction:"Decide whether a semicolon or a full stop is more appropriate between these sentences.",sentences:["The mountain track was icy. We decided to turn back.","The tūī sang all morning. We planted kūmara last spring.","The match was tied at full time. Neither team wanted to lose."],prompt:"Are the ideas closely related? Would a full stop feel too abrupt? Would a conjunction fit instead?"},{title:"You Do — Your Turn",instruction:'Join each pair of sentences with a semicolon where appropriate. Write "full stop" if the ideas are not closely enough related.',tasks:["The ceremony had lasted three hours. Everyone was exhausted but grateful.","The pīwakawaka followed us along the track. It rained heavily that afternoon.","She had run the last two kilometres without stopping. Her legs were shaking.","The river was in flood. Kiwi can't fly.","✦ Bonus: Write a paragraph of 5 sentences about a journey. Use semicolons at least twice where ideas are closely related."]},[{code:"Writing — Punctuation (Knowledge)",label:"Semicolons between related clauses",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "A semicolon joins two independent clauses that are closely related in meaning, without using a conjunction. Both sides must be grammatically complete sentences. The semicolon signals a closer connection than a full stop but a clearer boundary than a comma. It is distinct from the colon, which introduces something that follows from or elaborates on the preceding clause." Students learn the three-part test for valid semicolon use.'},{code:"Writing — Punctuation (Practice)",label:"Applying semicolons accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including semicolons. This lesson extends the Term 1 introduction to semicolons into deeper practice — students learn to apply the three-part test (complete sentences, related ideas, no conjunction) and to distinguish the semicolon from the colon and full stop through repeated decision-making.'}]),Tuesday:g("Present and past perfect tenses","Writing — Sentence Structure (Knowledge): the present perfect (has/have + past participle) connects past action to the present; the past perfect (had + past participle) shows an action completed before another past event; students use both tenses to add precision to narrative and report writing.",{title:"I Do — Tenses That Show Sequence",instruction:"Two more tenses: present perfect and past perfect. They show how past actions relate to other moments in time.",example:'Present perfect: "She <u>has trained</u> for months." (past action with present relevance) | Past perfect: "She <u>had trained</u> for months before the race." (action completed before another past event)',demonstration:'Present perfect (has/have + past participle): "He has arrived" = he arrived, and is here now — past action relevant to present moment. Past perfect (had + past participle): "By the time we arrived, the match had already started" = the match started BEFORE we arrived — it shows sequence in the past.',tip:"Present perfect = past action still relevant now. Past perfect = action completed before another past action."},{title:"We Do — Present or Past Perfect?",instruction:"Choose the correct perfect tense for each sentence.",sentences:["By the time the ambulance arrived, the team ___ (has administered / had administered) first aid.","She ___ (has lived / had lived) in Gisborne for twenty years and loves it there.","He couldn't believe the news — his team ___ (has won / had won) the championship."],prompt:"Is the past action still relevant now (present perfect) or was it completed before another past event (past perfect)?"},{title:"You Do — Your Turn",instruction:"Complete each sentence with the correct perfect tense form of the verb in brackets.",tasks:["By the time we reached the summit, the mist ___ (settle) over the valley.","The scientist ___ (discover) three new species in the past year. (still relevant today)","She realised she ___ (forget) her notes when she was halfway to the stage.","✦ Bonus: Write a paragraph of 5 sentences about a recent event or achievement. Use present perfect for actions still relevant and past perfect for actions that preceded other past events. Label each one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Present and past perfect tenses",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "The present perfect tense (has/have + past participle) describes a past action that has ongoing relevance to the present. The past perfect tense (had + past participle) describes an action completed before another event in the past, showing sequence and chronology. Both tenses require the auxiliary verb 'have/has/had' and the past participle form of the main verb." Mastery of these tenses is a key grammatical expectation at Years 5–6.`},{code:"Writing — Sentence Structure (Practice)",label:"Using perfect tenses in narrative and report",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of tenses." Perfect tenses are particularly important in narrative (past perfect shows backstory: "She had always known") and in report and recount writing (present perfect links past events to the present: "Scientists have discovered"). This lesson develops students' ability to select the right perfect tense for the logical relationship they want to express.`}]),Wednesday:g("Complex sentences: because, after, before","Writing — Sentence Structure (Knowledge & Practice): 'because', 'after', and 'before' are subordinating conjunctions expressing cause and time sequence; students use them to create complex sentences that show logical and chronological relationships.",{title:"I Do — Showing Cause and Sequence",instruction:'"Because" shows cause. "After" and "before" show time sequence. All three create complex sentences where one clause explains or situates the other.',example:'"She left early <u>because</u> the tide was turning." | "<u>After</u> the haka, the crowd fell silent." | "<u>Before</u> she could answer, the bell rang."',demonstration:'"Because" answers WHY — it introduces the reason. "After" shows what happened next — the sequence. "Before" shows what happened first. When fronted (at the start), all three need a comma. When at the end — no comma. Clause order changes the emphasis.',tip:'"Because" = cause (why). "After" = following in time. "Before" = earlier in time. Fronted = comma. Final = no comma.'},{title:"We Do — Build the Complex Sentence",instruction:"Join these pairs using the conjunction shown. Try fronted and final versions.",sentences:["The river flooded. The rain had been falling for three days. [because]","She checked her gear. She set out on the track. [before]","The karakia was spoken. The group moved forward together. [after]"],prompt:"Which version is more effective — conjunction at the start or end? Does the comma placement change?"},{title:"You Do — Your Turn",instruction:"Write two sentences for each conjunction — one with the clause fronted, one with it at the end.",tasks:["because (cause)","after (time sequence)","before (prior event)","✦ Bonus: Write a narrative paragraph of 6 sentences about a significant moment. Use because, after, and before at least once each. Vary whether the subordinate clause comes first or last."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Subordinating conjunctions: because, after, before",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "'Because' introduces a causal subordinate clause (explaining why the main clause is true); 'after' introduces a time subordinate clause showing a subsequent event; 'before' introduces a time subordinate clause showing a prior event. When the subordinate clause is fronted, a comma separates it from the main clause. When it follows the main clause, no comma is needed." Clause order and comma placement are connected in complex sentences.`},{code:"Writing — Sentence Structure (Practice)",label:"Complex sentences for cause and sequence",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures — including complex sentences — for effect and clarity," using subordinating conjunctions to show causal and chronological relationships. This lesson extends the range of subordinating conjunctions students control, reinforcing that clause order is a choice (not fixed) and that comma placement follows from the structural position of the subordinate clause.'}]),Thursday:g("Editing: improving cohesion between sentences","Writing — Text Structure (Practice) & Writing Process (Practice): students identify and repair cohesion breaks between sentences, using pronouns, connectives, and repeated key ideas to create smooth paragraph flow.",{title:"I Do — Finding the Gaps",instruction:"A cohesion break is when two consecutive sentences feel disconnected — the reader has to jump from one idea to the next without a bridge. Watch me find and repair them.",example:'Disconnected: "The kākāpō is nocturnal. It eats fruit and leaves. New Zealand has made great conservation efforts." → Cohesive: "The kākāpō is nocturnal, foraging for fruit and leaves under the cover of darkness. Thanks to intensive conservation efforts, its population has slowly recovered."',demonstration:'I combined sentences 1 and 2 using a participial phrase. I connected sentence 3 to the previous idea using "thanks to" — creating a logical flow. I also removed the redundant "New Zealand" and replaced with "its population" — a pronoun chain.',tip:"Read your paragraph and ask: does each sentence connect to the one before? If there's a gap — add a bridge."},{title:"We Do — Find and Fix the Gaps",instruction:"Find the cohesion break in this paragraph and repair it.",sentences:["The great white shark is one of the ocean's apex predators. It can detect blood from kilometres away. Sharks have been on Earth for over 400 million years. Conservation of marine habitats is very important. The kaitiakitanga principles support environmental protection."],prompt:"Where does the paragraph lose its thread? What connecting device would repair each gap?"},{title:"You Do — Your Turn",instruction:"Rewrite this paragraph, repairing all cohesion breaks with appropriate linking devices.",tasks:["Matariki marks the Māori New Year. It is when the Pleiades star cluster rises. Traditional foods are prepared. Whānau gather together. New goals are set for the coming year. It is a time of reflection.","✦ Bonus: Write a cohesive paragraph of 5 sentences about a significant NZ event or place. After writing, draw connection arrows between sentences to verify cohesion."]},[{code:"Writing — Text Structure (Practice)",label:"Repairing cohesion breaks",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "use cohesive devices — including pronouns, synonyms, and connectives — to link ideas within and across sentences and paragraphs." This lesson develops the skill of reading a paragraph as a sequence of connected thoughts — identifying where the thread breaks and selecting the right device (pronoun reference, connective, participial phrase, repeated key idea) to repair it.'},{code:"Writing — Writing Process (Practice)",label:"Cohesion audit in revision",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The cohesion audit — drawing connection arrows between consecutive sentences — is a visual revision strategy that makes cohesion breaks immediately visible, enabling targeted repair rather than vague re-reading.'}])},8:{Monday:g("Spelling: suffixes (-tion, -ness, -ment)","Writing — Conventions (Knowledge): suffixes (-tion, -ness, -ment) change the word class of base words; students apply spelling rules for adding these suffixes and understand the grammatical change each one creates.",{title:"I Do — Suffixes That Change Word Class",instruction:"Suffixes don't just change spelling — they change the word class. Watch how adding a suffix turns a verb or adjective into a noun.",example:"-tion: complete → completion | -ness: happy → happiness | -ment: achieve → achievement",demonstration:'"Complete" (verb) + -tion → "completion" (noun). "Happy" (adjective) + -ness → "happiness" (noun) — note: y → i before -ness. "Achieve" (verb) + -ment → "achievement" (noun). Each suffix turns the base word into a noun that names the state, process, or result.',tip:"Spelling rules: words ending in -e usually drop the e before -tion (complete → completion). Words ending in y change y to i before -ness (happy → happiness)."},{title:"We Do — Add the Suffix",instruction:"Add the correct suffix (-tion, -ness, -ment) to each base word. Check spelling rules.",sentences:["dark + ___ → (darkness/darkment/darktion?)","state + ___ → (statetion/statement/stateness?)","sad + ___ → (sadness/sadment/sadtion?)","develop + ___ → (developness/development/develoption?)"],prompt:"What word class does each base word belong to? Which suffix creates a noun from it?"},{title:"You Do — Your Turn",instruction:"Add the correct suffix and write a sentence using the new word.",tasks:["kind → ___ (noun: the state of being kind)","protect → ___ (noun: the act of protecting)","lonely → ___ (noun: the state of being lonely — check the spelling rule)","govern → ___ (noun: the act of governing)","✦ Bonus: Find 5 words in a text you're reading that use -tion, -ness, or -ment. Write the base word, the suffix, and the word class of each."]},[{code:"Writing — Conventions (Knowledge)",label:"Suffixes: -tion, -ness, -ment",detail:'NZC Phase 2 Writing — Conventions (Knowledge): "Suffixes are word endings that change the meaning or grammatical class of the base word. The suffix -tion (and its variants -sion, -ation) typically converts verbs to nouns (complete → completion). The suffix -ness converts adjectives to nouns (happy → happiness; y changes to i). The suffix -ment converts verbs to nouns (achieve → achievement). Students apply these rules to spell suffixed words accurately." Morphological knowledge supports both spelling and vocabulary development.'},{code:"Writing — Vocabulary (Practice)",label:"Using nominalisations in writing",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "use knowledge of word origins, roots, and word families to extend vocabulary." Suffixed nouns (nominalised forms) are essential in formal and informational writing at Years 5–6 — "the development of technology" is more formal than "how technology developed." Understanding the suffix rules enables students to both spell these words accurately and use them purposefully in their writing.'}]),Tuesday:g("Prepositional phrases for setting in narrative","Writing — Sentence Structure (Practice) & Composing (Practice): prepositional phrases establish setting in narrative; students use them at sentence beginnings and within sentences to create vivid, specific scenes.",{title:"I Do — Setting the Scene with Prepositions",instruction:"Prepositional phrases are particularly powerful at the start of a narrative paragraph — they drop the reader directly into the physical setting.",example:'"<u>Deep in the manuka scrub</u>, something was moving." | "<u>At the edge of the old wharf</u>, she waited."',demonstration:`"Deep in the manuka scrub" — we're placed immediately. The preposition "in" + "the manuka scrub" gives us location. "Deep" modifies it — we feel the distance from civilisation. "At the edge of the old wharf" — "at" + "the edge" + "of the old wharf" is a layered prepositional phrase. Both drop the reader into the setting in the first few words.`,tip:"A fronted prepositional phrase at the start of a narrative paragraph is one of the most effective scene-setting tools available. It says: you are HERE."},{title:"We Do — Build the Setting Phrase",instruction:"Write a fronted prepositional phrase for each setting, then expand it into a full sentence.",sentences:["Setting: inside a cave near the sea.","Setting: at the top of a volcanic cone at dusk.","Setting: on the bank of a braided river in late summer."],prompt:"Which preposition sets the scene most precisely? Can you layer two prepositional phrases?"},{title:"You Do — Your Turn",instruction:"Write a narrative sentence for each NZ setting, starting with a fronted prepositional phrase.",tasks:["A remote West Coast beach.","The summit of a North Island maunga.","The interior of a wharenui at night.","Below the surface of a Canterbury river.","✦ Bonus: Write an opening paragraph of 4 sentences for a story set in a NZ location you know well. Begin with a fronted prepositional phrase and use at least two more within the paragraph."]},[{code:"Writing — Sentence Structure (Practice)",label:"Fronted prepositional phrases in narrative",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding prepositional phrases to express location" and to "vary sentence openings." Fronted prepositional phrases are particularly effective in narrative — they establish setting immediately, vary sentence openers, and require a comma after them. This lesson develops their use as a scene-setting strategy, connecting sentence structure knowledge to composing practice.'},{code:"Writing — Composing (Practice)",label:"Setting as immersive experience",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including creating vivid, specific settings. Fronted prepositional phrases are among the most efficient tools for placing the reader in a scene immediately — they do the work of several descriptive sentences in just a few words, establishing location before the action begins.'}]),Wednesday:g("Fronted adverbials: place and atmosphere","Writing — Sentence Structure (Practice): fronted adverbials of place create immediate setting and atmosphere; students use them to vary sentence openers and establish mood at the start of sentences and paragraphs.",{title:"I Do — Place Adverbials at the Front",instruction:"We know time adverbials at the front (Last Tuesday..., Before dawn...). This week: place adverbials. They set the scene with location and often carry atmospheric weight.",example:'"<u>High above the valley</u>, the hawk circled in silence." | "<u>Somewhere in the darkness</u>, a morepork called."',demonstration:'"High above the valley" — not just where, but how high — creates a sense of scale and isolation. "Somewhere in the darkness" — the vagueness of "somewhere" creates mystery and unease. The atmosphere is in the adverbial, before the subject even arrives.',tip:"Place adverbials at the front don't just say where — they say what the where FEELS like. Choose them for mood."},{title:"We Do — Write the Atmosphere",instruction:"Write a fronted place adverbial for each mood, then expand into a full sentence.",sentences:["Mood: eerie isolation","Mood: warmth and belonging","Mood: dangerous tension"],prompt:"How does the place adverbial carry the mood before the subject even appears? Does the comma change anything?"},{title:"You Do — Your Turn",instruction:"Write a sentence for each NZ setting that opens with a fronted place adverbial. Match the adverbial to the mood in brackets.",tasks:["Setting: the Milford Sound shoreline. (Mood: awe-inspiring vastness)","Setting: a Wellington street in winter. (Mood: cold loneliness)","Setting: a Bay of Islands beach in summer. (Mood: joyful warmth)","Setting: inside a mountain cave. (Mood: mystery and unease)","✦ Bonus: Write an opening paragraph of 5 sentences for a NZ story. At least 3 sentences must begin with a fronted adverbial (mix time, place, and manner). Vary the mood across the paragraph."]},[{code:"Writing — Sentence Structure (Practice)",label:"Fronted place adverbials for atmosphere",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "vary sentence openings to avoid repetition and create effect," using fronted adverbials of place, time, and manner. This lesson focuses specifically on place adverbials — teaching students that a well-chosen fronted place phrase does two jobs simultaneously: it establishes location and creates atmosphere, doing the work of a whole descriptive clause in just a few words.'},{code:"Writing — Composing (Practice)",label:"Place adverbials as mood-setting tools",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including establishing atmosphere through setting detail. This lesson develops fronted place adverbials as composing tools — students learn to choose place phrases not just for their locational accuracy but for the emotional atmosphere they carry before the main clause begins.'}]),Thursday:g("Editing: strengthening narrative openings","Writing — Writing Process (Practice) & Composing (Practice): students evaluate their own narrative openings against craft criteria and revise weak openings to engage the reader from the first sentence.",{title:"I Do — First Sentences That Pull",instruction:"We revisit narrative openings — this time evaluating our own writing against three criteria and revising weak openings.",example:"Criteria: (1) drops into a specific moment (2) creates a question in the reader's mind (3) does not explain or introduce",demonstration:`Weak: "This is a story about the time I found something surprising at the beach." Test: (1) No specific moment ✗ (2) No question ✗ (3) Explains itself ✗ — all three criteria fail. Strong: "The shape in the rock pool didn't move when I touched it — but it was definitely breathing." Test: (1) Specific moment ✓ (2) What is it? ✓ (3) No explanation ✓ — all three pass.`,tip:"If your opening tells the reader what the story is about — rewrite it. Drop them in. Let the story explain itself."},{title:"We Do — Class Evaluation",instruction:"Evaluate these openings against all three criteria. Score each one out of 3.",sentences:['"I am going to tell you about the most frightening thing that ever happened to me."','"The rope snapped. She fell. Neither of them made a sound."','"One day in the holidays something happened that changed everything."'],prompt:"What score does each get? What would you change in the weak ones?"},{title:"You Do — Your Turn",instruction:"Take a piece of your own narrative writing and evaluate your opening against the three criteria. Then revise it.",tasks:["✦ Criterion 1: Does it drop into a specific moment? Score /1","✦ Criterion 2: Does it create a question in the reader's mind? Score /1","✦ Criterion 3: Does it avoid explaining or introducing the story? Score /1","✦ Total: _/3. If below 3 — rewrite until you score 3/3.","✦ Bonus: Write three alternative openings for the same story. Choose the best and justify your choice against the criteria."]},[{code:"Writing — Writing Process (Practice)",label:"Evaluating and revising narrative openings",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson applies revision to the narrative opening — the highest-stakes single sentence in any story. Students use explicit criteria (specific moment, reader question, no explanation) to evaluate their own writing and revise with a clear target, not just a vague sense that it could be better.'},{code:"Writing — Composing (Practice)",label:"Narrative opening as reader engagement",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader." A strong narrative opening is the single most important composing decision in a story — it determines whether the reader continues. This lesson gives students the criteria to evaluate their own opening choices and the revision strategies to improve them: drop in, create a question, trust the story.'}])},9:{Monday:g("Personification as a writing device","Writing — Vocabulary (Knowledge) & Composing (Practice): personification gives human qualities to non-human things; students use it deliberately to create emotional connection, atmosphere, and vivid imagery in their writing.",{title:"I Do — Making the World Feel Something",instruction:"Personification gives human actions, emotions, or qualities to non-human things. It's one of the most powerful ways to create atmosphere and emotional resonance.",example:'"The wind <u>howled</u> with rage." | "The old pōhutukawa <u>stretched its arms</u> towards the sea." | "Fear <u>gripped</u> her."',demonstration:'"Howled with rage" — the wind feels aggressive, hostile. "Stretched its arms" — the tree feels alive, reaching. "Gripped her" — fear becomes a physical force. Each example makes the non-human feel present and intentional. The reader responds emotionally.',tip:"Personification works best when the human quality you give the thing MATCHES the atmosphere you want to create. Angry wind. Welcoming tree. Suffocating silence."},{title:"We Do — Give It Life",instruction:"Add personification to each subject to create the atmosphere in brackets.",sentences:["The fog ___ (eerie mystery).","The storm ___ (violent anger).","The forest ___ (welcoming safety)."],prompt:"What human quality creates the right atmosphere? What verb brings it to life?"},{title:"You Do — Your Turn",instruction:"Write a personification sentence for each subject that creates the mood in brackets.",tasks:["The river in flood. (Mood: terrifying power)","The silence after the tangi. (Mood: heavy grief)","The sun on the last day of holidays. (Mood: reluctant departure)","The wind off the Kaikōura mountains. (Mood: cold indifference)","✦ Bonus: Write a paragraph of 4 sentences describing a NZ weather event. Use personification at least three times — each time to create a specific, named atmosphere."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Personification as a language device",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Personification is a language device that gives human qualities — emotions, actions, or intentions — to non-human things (objects, animals, abstract concepts, natural phenomena). It creates emotional resonance and atmosphere by making the world feel alive and intentional. Effective personification matches the human quality to the desired mood." Students learn to choose the personification that serves their atmospheric intent.'},{code:"Writing — Composing (Practice)",label:"Using personification for atmosphere",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use language devices, including personification, to create specific effects and engage the reader." This lesson develops personification as a composing tool — students practise selecting human qualities that match a specific named atmosphere, rather than applying personification randomly. The discipline is: what do I want the reader to feel? → what human quality creates that feeling? → what verb brings it to life?'}]),Tuesday:g("Conjunctions review: narrative and informational use","Writing — Sentence Structure (Practice): students apply the full range of coordinating and subordinating conjunctions across both narrative and informational text types, selecting conjunctions that match the logical relationship and context.",{title:"I Do — The Right Conjunction for the Context",instruction:"Different text types call for different conjunction choices. Narrative uses conjunctions for drama and causation. Informational writing uses them for logic and sequence. Watch me use the same conjunction in both contexts.",example:'Narrative "because": "She ran because the wolf was gaining." | Informational "because": "Native biodiversity has declined because of introduced predators."',demonstration:'"Because" works in both — but the context changes everything. In narrative, it creates urgency. In informational, it states cause. "Although" in narrative: "Although she was afraid, she stepped forward." In argument: "Although some disagree, the evidence is clear."',tip:"Same conjunction, different context = different effect. Choose based on the relationship AND the text type."},{title:"We Do — Match to Context",instruction:"Write two sentences for each conjunction — one narrative, one informational.",sentences:["although","therefore (result in formal writing)","unless"],prompt:"How does the same conjunction feel different in narrative vs. informational writing?"},{title:"You Do — Your Turn",instruction:"Write sentences as directed.",tasks:['Narrative: use "yet" to show a character doing something despite fear.','Informational: use "however" to introduce a counterargument.','Narrative: use "until" to build suspense before a revelation.','Informational: use "because" to explain a cause-and-effect relationship.',"✦ Bonus: Write a paragraph of 5 sentences about a NZ environmental issue. Use at least 3 different conjunctions — choosing each one for its logical and stylistic effect."]},[{code:"Writing — Sentence Structure (Practice)",label:"Conjunctions across text types",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity" across different text types. This lesson consolidates conjunction knowledge by applying it in both narrative (where conjunctions create drama, causation, and suspense) and informational contexts (where they signal logical relationships: cause, contrast, condition, sequence). Students learn that conjunction choice reflects both the relationship between ideas and the text type's conventions.`},{code:"Writing — Composing (Practice)",label:"Conjunction choice as a composing decision",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to write with awareness of purpose and audience. This lesson develops the understanding that conjunction selection is a composing decision — the same word ("because") creates different effects in narrative versus argument, and choosing the right conjunction for the context is part of writing with craft and intentionality at Phase 2.'}]),Wednesday:g("Time connectives as cohesion links","Writing — Text Structure (Practice): time connectives (meanwhile, subsequently, prior to, at this point) create cohesion between narrative events and informational steps; students use them to signal time relationships and improve paragraph flow.",{title:"I Do — Linking Time in a Paragraph",instruction:"Time connectives signal the temporal relationship between events or steps. They're different from simple time adverbials — they explicitly link the new sentence to the time frame of the previous one.",example:'"The weather turned. <u>Meanwhile</u>, the rescue team was still an hour away." | "The sample was collected. <u>Subsequently</u>, it was analysed in the laboratory."',demonstration:'"Meanwhile" signals simultaneous events happening elsewhere. "Subsequently" signals what happened next, in a formal register. "Prior to" signals what happened before. "At this point" signals a moment in an ongoing sequence. Each one reaches back to the previous sentence and creates a time bridge.',tip:"Time connectives create bridges between sentences. They say: here's where we are in time relative to what just happened."},{title:"We Do — Choose the Connective",instruction:"Choose the best time connective for each gap and explain your choice.",sentences:["The hikoi marchers reached Wellington. ___, delegations were being prepared at Parliament.","The experiment failed on the first attempt. ___, the team adjusted their method.","She had lived in Gisborne her whole life. ___ moving to Christchurch, she had never left the North Island."],prompt:"What time relationship exists? Is it simultaneous, sequential, or prior?"},{title:"You Do — Your Turn",instruction:"Add an appropriate time connective to create a time bridge between these sentences.",tasks:["The kapa haka group rehearsed for weeks. ___, the day of the regional competition arrived.","The tide was going out fast. ___, the stranded dolphin was still alive.","The karakia was spoken. ___, no one in the group had met before.","✦ Bonus: Write a 5-sentence paragraph about a real or imagined event. Use a different time connective in at least three sentences. Label the time relationship each one creates."]},[{code:"Writing — Text Structure (Practice)",label:"Time connectives for cohesion",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "use cohesive devices — including pronouns, synonyms, and connectives — to link ideas within and across sentences and paragraphs." Time connectives (meanwhile, subsequently, prior to, at this point, eventually, simultaneously) are a specific class of cohesive device that signal temporal relationships between events — bridging sentences in narrative and informational writing and creating logical sequencing for the reader.'},{code:"Writing — Text Structure (Knowledge)",label:"Time relationships in text",detail:'NZC Phase 2 Writing — Text Structure (Knowledge): "Time connectives signal the temporal relationship between events or steps in a text — simultaneous (meanwhile, at the same time), sequential (subsequently, next, then), prior (prior to, before this), or eventual (eventually, in time). They are distinct from simple time adverbials in that they explicitly link the new sentence to the time frame established in the previous one." Understanding this distinction helps students use time language to create genuine cohesion rather than just adding time words.'}]),Thursday:g("Editing: cutting filler words for impact","Writing — Writing Process (Practice) & Vocabulary (Practice): filler words and phrases add length without meaning; students identify and cut them, creating tighter, more impactful writing.",{title:"I Do — Every Word Must Earn Its Place",instruction:'Filler words take up space but add no meaning: "in order to," "the fact that," "it is important to note that," "basically," "literally," "kind of," "sort of." Watch me find and cut them.',example:'"Basically, it is important to note that the fact that kiwi are nocturnal means that they are kind of hard to spot."',demonstration:`Cut: "Basically" — meaningless opener. "It is important to note that" — just say it. "The fact that" — remove. "Kind of" — either they are or they aren't. Fixed: "Kiwi are nocturnal — they are hard to spot." Same information. Half the words. Twice the impact.`,tip:"Read each sentence aloud. If you can remove a word or phrase and lose nothing — cut it. If removing it loses meaning — keep it."},{title:"We Do — Cut the Filler",instruction:"Remove every filler word or phrase from this passage.",sentences:["Basically, the reason why we are here is due to the fact that we need to kind of address the issue of how we are going to sort of solve this problem that we have been literally dealing with for a long time now."],prompt:"What is the core meaning? How few words do you need to express it clearly?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence by removing all filler words.",tasks:["In order to be able to successfully complete the task, it is necessary for students to basically follow the instructions.","The fact that the weather was bad literally made things kind of difficult for the rescue team.","It is important to note that the reason for the decision was due to the fact that it was the best option.","✦ Bonus: Take a paragraph from your own writing. Count the filler words. Cut every one. Count the words before and after. Assess whether the writing is stronger."]},[{code:"Writing — Writing Process (Practice)",label:"Cutting filler for impact",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." Cutting filler words is a high-yield revision strategy — it consistently reduces word count and increases impact without losing meaning. This lesson trains students to read each sentence with the question: can I remove this word and lose nothing? If yes — cut it.'},{code:"Writing — Vocabulary (Practice)",label:"Precision over volume",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." This lesson reinforces a foundational principle of effective writing: fewer, better-chosen words are stronger than more words. Filler phrases ("in order to," "the fact that," "it is important to note") are not just redundant — they actively weaken the sentences they inhabit by burying the real information in padding.'}])},10:{Monday:g("Review: Term 3 punctuation marks","Writing — Punctuation (Knowledge & Practice): students consolidate all punctuation covered in Term 3 — ellipsis, semicolons, dialogue conventions, and punctuation for atmosphere and effect.",{title:"I Do — Term 3 Punctuation Review",instruction:"Let's revisit every punctuation mark from Term 3 and its specific use in narrative and descriptive writing.",example:"Ellipsis (... for suspense/trailing) | Semicolons (related clauses) | Dialogue conventions (5 rules) | Commas with but/although | Dashes for emphasis",demonstration:`"She reached for the handle... and pushed (ellipsis — suspense). The door swung open; the room beyond was dark (semicolon — related clauses). 'Come in,' said the voice — low and even — 'if you dare' (dialogue + dashes for emphasis)." Every mark is doing a job.`,tip:"For each mark: what job is it doing? If it isn't doing a job — remove it."},{title:"We Do — Punctuation Audit",instruction:"Add the correct punctuation to this narrative passage and name every rule applied.",sentences:["She had been walking for three hours when she saw it. The lighthouse. It stood alone on the headland its light still turning even though everyone said it had been abandoned for years. She whispered to herself I knew it. I knew it was still here. She moved closer step by step her heart hammering"],prompt:"Which marks are needed? How many different types of punctuation can you use correctly here?"},{title:"You Do — Your Turn",instruction:"Rewrite this passage with full punctuation, using at least 5 different punctuation types from Term 3.",tasks:["the old meeting house stood at the edge of the bush its carved figures watching in silence. deep in the darkness something shifted. Rangi whispered to his cousin did you hear that. his cousin nodded but said nothing. then the sound came again closer this time and unmistakable it was footsteps","✦ Bonus: Write a short narrative passage (6 sentences) that deliberately uses all Term 3 punctuation marks. Label each one."]},[{code:"Writing — Punctuation (Knowledge)",label:"Term 3 punctuation review",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): Students consolidate all punctuation covered in Term 3: ellipsis (for suspense, trailing thought, and hesitation in dialogue), semicolons (joining related independent clauses), dialogue conventions (five rules), commas with "but" and fronted "although," and dashes for emphasis. Review ensures students can name the function and rule of each mark and apply it in narrative context.'},{code:"Writing — Punctuation (Practice)",label:"Punctuation for narrative effect",detail:`NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This consolidation lesson evaluates punctuation as a craft tool in narrative — students apply all Term 3 marks in a narrative context, demonstrating that they can select the right mark not just for grammatical correctness but for the effect it creates in the reader's experience of the story.`}]),Tuesday:g("Review: Term 3 grammar","Writing — Sentence Structure (Knowledge): students consolidate all grammar covered in Term 3 — count/non-count nouns, modal verbs, collective noun SVA, adjective placement, present and past perfect tenses, and suffixes.",{title:"I Do — Term 3 Grammar Gallery",instruction:"Let's revisit every grammar concept from Term 3 with a mini-example each.",example:"Count/non-count nouns | Modal verbs | Collective noun SVA | Adjective placement | Perfect tenses | Suffixes (-tion/-ness/-ment)",demonstration:'"A flock of kererū (collective: singular) has settled in the pōhutukawa. The team must (modal: obligation) protect these birds. Their conservation has progressed (present perfect: still relevant now) significantly. Ancient (pre-noun) and resilient (post-noun), the species has survived against the odds. Further development (suffix: -ment) of protection policies is needed."',tip:"Grammar is about meaning. Every grammar choice affects what the reader understands and feels."},{title:"We Do — Grammar Challenge",instruction:"For each sentence, identify the underlined grammar feature and explain the rule.",sentences:["The <u>excitement</u> in the room was building as the results were announced.","The group of students <u>was</u> asked to present their findings.","By the time the alarm sounded, she <u>had already</u> reached the exit."],prompt:"What type of noun/verb/tense is underlined? What rule governs it?"},{title:"You Do — Your Turn",instruction:"Complete the grammar review tasks.",tasks:["Write a sentence using a non-count noun correctly with an appropriate determiner.","Write a sentence using a modal verb that expresses recommendation (not obligation).","Write a sentence using the past perfect to show a backstory event.","Write a sentence with post-positive adjective placement for dramatic effect.","✦ Bonus: Write a paragraph of 6 sentences about a conservation issue. Include at least 5 different Term 3 grammar features. Label them."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Term 3 grammar review",detail:"NZC Phase 2 Writing — Sentence Structure (Knowledge): Students consolidate their understanding of all grammar covered in Term 3: count and non-count nouns with correct determiners, modal verbs and their degrees of obligation and possibility, subject-verb agreement with collective nouns, adjective placement (pre- and post-nominal), present and past perfect tenses, and word class changes through suffixes (-tion, -ness, -ment). Review connects grammar knowledge to purposeful writing choices."},{code:"Writing — Sentence Structure (Practice)",label:"Integrated grammar in context",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of word classes and structures." This review lesson asks students to demonstrate all Term 3 grammar knowledge in context — producing sentences that feature specific grammar points accurately and purposefully — moving from isolated identification to integrated, deliberate application at Phase 2.'}]),Wednesday:g("Review: Term 3 sentence structures","Writing — Sentence Structure (Practice) & Composing (Practice): students consolidate Term 3 sentence structure strategies — simple sentences for tension, compound sentences for narrative contrast, complex sentences using because/after/before/although/unless/while, and fronted adverbials for atmosphere.",{title:"I Do — The Term 3 Narrative Toolkit",instruction:"Term 3 focused on sentence structure for narrative effect. Let me show the full toolkit in action within a single narrative passage.",example:"Simple for tension | Compound with but/yet | Complex with because/after/although | Fronted adverbials for atmosphere | Show-don't-tell sentences",demonstration:'"Deep in the valley, the mist had settled (fronted adverbial). She had been walking for hours; her legs were beginning to fail (semicolon — related clauses). Although she knew the track well, nothing looked familiar (complex — although). She stopped. Listened. Nothing (simple — tension). But she kept moving — because she had no choice (compound + complex)."',tip:"Great narrative writing uses all these structures — none dominates. Variety creates rhythm; rhythm creates engagement."},{title:"We Do — Sentence Type Challenge",instruction:"Identify the sentence type and the intended effect in each example.",sentences:["Before the sun had fully risen, she reached the ridge.","The door was open. A light was on. Someone was home.","She had run for miles, yet she still couldn't shake the feeling she was being followed."],prompt:"What is the structure? What narrative effect does it create?"},{title:"You Do — Your Turn",instruction:"Write one sentence of each type for a narrative set in a NZ location.",tasks:["Fronted place adverbial (atmosphere).","Short simple sentence (tension).",'Complex sentence with "although" (contrast).','Compound sentence with "yet" (surprise).','Complex sentence with "because" (causation).',"✦ Bonus: Write a narrative paragraph of 6 sentences using all five sentence types above. Label each one."]},[{code:"Writing — Sentence Structure (Practice)",label:"Term 3 sentence structures in narrative",detail:"NZC Phase 2 Writing — Sentence Structure (Practice): Students consolidate all sentence structures from Term 3: simple sentences for tension, compound sentences for contrast and consequence, complex sentences using because/after/before/although/unless/while, fronted adverbials for atmosphere, and semicolons for related clauses. Students demonstrate the ability to select and produce each type on demand, with awareness of the narrative effect each creates."},{code:"Writing — Composing (Practice)",label:"Sentence variety in narrative composing",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including controlling rhythm and pace through sentence structure. This consolidation task — producing five different sentence types for a narrative setting — tests whether students can select the right structure for each narrative moment, rather than defaulting to their most comfortable pattern.'}]),Thursday:g("Full-passage edit: Term 3 checklist","Writing — Writing Process (Practice): students apply all Term 3 editing skills in a systematic multi-pass edit, using the full Term 3 checklist to revise narrative writing for accuracy, atmosphere, and craft.",{title:"I Do — The Full Term 3 Edit",instruction:"The Term 3 checklist adds narrative craft to our accuracy checks. Watch me apply all passes.",example:"Pass 1: Dialogue punctuation (5 rules) | Pass 2: Ellipsis (genuine use only) | Pass 3: Semicolons (correct?) | Pass 4: Adjective atmosphere audit | Pass 5: Show-don't-tell (emotion words to replace) | Pass 6: Filler word cut | Pass 7: Sentence variety (length, opener)",demonstration:"I read once for meaning. Then Pass 1: every dialogue exchange — 5-rule check. Pass 2: every ellipsis — is it creating suspense, trailing, or hesitation? If not — cut it. Pass 3: every semicolon — complete sentence on both sides? Related ideas? And so on through all seven passes.",tip:"Seven passes sounds like a lot. But each pass is targeted — you're not looking for everything at once."},{title:"We Do — Class Edit",instruction:"Work through all seven passes together on this narrative passage.",sentences:['the old woman lived very far away from the village at the edge of a very dark forest. she had lived there for many years and she was very wise. everyone was a bit scared of her but also they kind of respected her. one day a girl came to her door. she knocked. the old woman opened it and she said "what do you want" the girl said she needed help. the old woman looked at her for a long time.'],prompt:"Pass by pass — what are we fixing? Count the improvements."},{title:"You Do — Your Turn",instruction:"Edit this narrative passage using all seven passes of the Term 3 checklist.",tasks:[`it was a very dark night when rangi reached the coast. the sea was really rough and kind of scary. he basically had no choice but to swim. he dove in. the water was very cold. he swam and swam for what felt like hours. eventually he grabbed onto something it was a rope. "hold on" shouted a voice from above "i've got you"`,"✦ Bonus: Apply the full 7-pass Term 3 edit to a piece of your own narrative writing."]},[{code:"Writing — Writing Process (Practice)",label:"Multi-pass editing: Term 3 checklist",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The Term 3 checklist extends beyond accuracy to include craft — students audit for ellipsis purpose, show-don't-tell moments, atmosphere adjectives, filler words, and sentence variety alongside conventional accuracy checks. This integrated editing task builds the systematic revision habits expected at Phase 2.`},{code:"Writing — Writing Process (Practice)",label:"Term 3 skills: integrated application",detail:`NZC Phase 2 Writing — Writing Process (Practice): This consolidation lesson asks students to demonstrate mastery of all Term 3 writing skills in one editing task — accuracy (dialogue, semicolons), craft (ellipsis, show-don't-tell, atmosphere adjectives), and economy (filler word removal, sentence variety). It directly mirrors the Phase 2 expectation that students "apply writing knowledge and skills across a range of text types and purposes" with increasing independence and sophistication.`}])},4:{1:{Monday:g("Tier 2 vocabulary: words for argument & opinion","Writing — Vocabulary (Knowledge & Practice): evaluative vocabulary (crucial, significant, substantial) signals opinion, certainty, and importance; students select argument vocabulary that matches their degree of certainty and the formality of their writing.",{title:"I Do — Words That Signal Position",instruction:"Persuasive writing uses specific vocabulary to signal opinion, certainty, and importance. Watch me identify and use these words deliberately.",example:'"It is <u>crucial</u> that schools protect student wellbeing. The evidence is <u>substantial</u>. This is a <u>significant</u> issue."',demonstration:'"Crucial" = extremely important, urgent. "Substantial" = large, considerable, hard to dismiss. "Significant" = noteworthy, important enough to act on. These words do more than describe — they tell the reader how seriously to take the argument. Choose the word that matches your actual degree of conviction.',tip:'Match the evaluative word to your certainty level. "Crucial" is stronger than "important." Use the stronger word only when you mean it.'},{title:"We Do — Choose the Evaluative Word",instruction:"Choose the most appropriate evaluative word for each sentence. Explain your choice.",sentences:["The impact of plastic pollution on ocean wildlife is ___ (significant/minor/uncertain).","Access to clean water is ___ (desirable/crucial/interesting) for human survival.","The research provides ___ (substantial/vague/irrelevant) evidence for this claim."],prompt:"How certain are you? How serious is the issue? Match the word to the reality."},{title:"You Do — Your Turn",instruction:"Complete each sentence with an evaluative word that matches the context, then explain your choice.",tasks:["The effects of climate change on Pacific Island nations are ___.","Te reo Māori revitalisation is ___ for the cultural identity of Aotearoa.","The school's new wellbeing policy has had ___ results so far.","✦ Bonus: Write a persuasive paragraph of 5 sentences on a topic you care about. Use at least four different evaluative vocabulary words. Label each one."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Evaluative vocabulary for argument",detail:`NZC Phase 2 Writing — Vocabulary (Knowledge): "Vocabulary is chosen deliberately for effect, so students consider the connotations and precision of words." In persuasive and formal writing, evaluative vocabulary (crucial, significant, substantial, considerable, compelling, undeniable) signals the writer's position and the seriousness of their claim. Understanding the spectrum from weak to strong evaluative language is a key Tier 2 vocabulary skill at Years 5–6.`},{code:"Writing — Vocabulary (Practice)",label:"Selecting evaluative vocabulary for persuasion",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience," including formal and evaluative language appropriate to persuasive writing. This lesson develops conscious evaluative word selection — students learn to choose the word that accurately matches their certainty level rather than defaulting to vague alternatives like "important" or "good."'}]),Tuesday:g("Gerunds as sentence subjects","Writing — Sentence Structure (Knowledge): a gerund is the -ing form of a verb used as a noun; when a gerund acts as the subject of a sentence, it creates a formal, concise structure common in informational and persuasive writing.",{title:"I Do — The -ing Word as a Subject",instruction:"A gerund is a verb + -ing used as a noun. When a gerund is the subject of a sentence, it creates a formal, concise structure.",example:'"<u>Swimming</u> is excellent exercise." | "<u>Protecting</u> native species requires sustained commitment." | "<u>Reading</u> widely builds vocabulary."',demonstration:`"Swimming" is the subject of the first sentence — it's a verb used as a noun. Compare: "To swim is good exercise" (infinitive as subject — less natural in English). "If you swim, it's good exercise" (subordinate clause — more words). The gerund is the most elegant option.`,tip:"When you want to talk about an activity as a concept — use a gerund as the subject. It sounds formal and concise."},{title:"We Do — Spot and Build",instruction:"Identify the gerund subject in each sentence, then write your own sentence with a gerund subject.",sentences:["Reducing plastic waste is one of the most effective ways to protect our oceans.","Understanding grammar helps writers make deliberate choices.","Collaborating across cultures strengthens communities."],prompt:"What is the gerund? Is it acting as the subject? Write your own sentence using a gerund as the subject."},{title:"You Do — Your Turn",instruction:"Rewrite each sentence so the activity becomes a gerund subject.",tasks:["If you eat well, it helps you focus better. → ___ing ___.","When you exercise regularly, it reduces stress. → ___ing ___.","If you listen carefully, it shows respect. → ___ing ___.","✦ Bonus: Write an argument paragraph of 5 sentences. Begin at least three sentences with a gerund subject. Label each gerund."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Gerunds as sentence subjects",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "A gerund is the present participle (-ing form) of a verb used as a noun. When a gerund functions as the subject of a sentence, it creates a formal, concise structure common in persuasive, academic, and informational writing (e.g. 'Protecting native species requires commitment'). Gerund subjects are more concise and formal than equivalent subordinate clause or infinitive constructions."`},{code:"Writing — Composing (Practice)",label:"Gerund subjects in formal writing",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to write with awareness of purpose and audience. In formal persuasive and informational writing at Phase 2, gerund subjects signal sophistication and register — "Protecting biodiversity is essential" reads as more authoritative and concise than "If we protect biodiversity, it is essential." Students learn to deploy this structure purposefully.'}]),Wednesday:g("Simple sentences: direct and concise in argument","Writing — Sentence Structure (Practice): in persuasive and formal writing, short direct sentences can be used for emphasis and clarity; students place key claims in simple sentences for maximum impact.",{title:"I Do — The Argument One-Liner",instruction:"In persuasive writing, a short direct sentence can be the most powerful weapon in your arsenal. Watch me use simple sentences to deliver key claims with maximum impact.",example:'"This must change. The evidence is overwhelming. Action is required now."',demonstration:"Three simple sentences. Each one is a complete thought. No hedging, no complex subordination — just the claim, stated directly. In an argument paragraph, placing your core claim in a short simple sentence forces the reader to confront it. It says: this is the point. Accept it.",tip:"In persuasion, use complex sentences for evidence and reasoning. Save the short simple sentence for the moment you want the reader to feel the full weight of your claim."},{title:"We Do — Identify the Impact Sentence",instruction:"Find the short simple sentence in each passage that carries the most argumentative weight. Then write one for the given topic.",sentences:['"For decades, scientists have warned about the consequences of inaction on climate change. Study after study has confirmed the data. The planet is warming. Yet the pace of change remains slow."',"Topic for your own: the importance of te reo Māori in schools."],prompt:'Which short sentence carries the most weight? Why? Write your own "impact sentence" for the given topic.'},{title:"You Do — Your Turn",instruction:"Write a persuasive argument paragraph of 5 sentences for each topic. Include at least one short simple sentence as a deliberate impact moment.",tasks:["Topic: all students should have access to outdoor education.","Topic: social media has more harms than benefits for young people.","✦ Bonus: Take a piece of your own persuasive writing. Find the core claim of each paragraph and rewrite it as a short, direct simple sentence. Assess whether this makes the argument stronger."]},[{code:"Writing — Sentence Structure (Practice)",label:"Simple sentences for argumentative impact",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity" across text types including persuasion. In argument writing, a short simple sentence placed at a key moment creates maximum emphasis — it removes all hedging and forces the reader to confront the claim directly. This lesson develops conscious use of sentence length as a persuasive strategy, not just a narrative one.'},{code:"Writing — Composing (Practice)",label:"Sentence length as a persuasive tool",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader." This lesson extends Term 3's sentence length work into persuasive writing — students learn that the same principle applies across text types: long sentences build evidence and context; short sentences deliver the decisive point. Placing a core claim in a simple sentence is a composing decision that shapes the reader's experience of the argument.`}]),Thursday:g("Editing for report consistency: tense & parallel lists","Writing — Writing Process (Practice) & Sentence Structure (Knowledge): formal reports use consistent present tense and parallel grammatical structure in lists; students identify and correct inconsistencies in modelled report text.",{title:"I Do — Report Writing Conventions",instruction:"Reports use specific conventions: (1) consistent present tense for timeless facts, (2) parallel structure in lists — each item in the same grammatical form.",example:'Inconsistent list: "Kiwi are nocturnal, they eat invertebrates, and running fast." → Parallel: "Kiwi are nocturnal, eat invertebrates, and run fast."',demonstration:'Non-parallel: "nocturnal" (adjective) + "they eat" (clause) + "running fast" (gerund phrase). Parallel: "are nocturnal" (verb phrase) + "eat invertebrates" (verb phrase) + "run fast" (verb phrase). Same grammatical form throughout. The list reads smoothly and sounds authoritative.',tip:"Parallel lists: start each item with the same word type. All verbs, all nouns, all adjectives — not a mix."},{title:"We Do — Fix the Inconsistencies",instruction:"Fix the tense inconsistency and parallel structure error in each item.",sentences:["The tuatara was found only in New Zealand. It eats insects, lizards, and it also consumed seabird eggs.","Effective kaitiakitanga involves: monitoring biodiversity, the reduction of pollution, and to restore native habitats."],prompt:"What tense should the report use? What grammatical form must each list item share?"},{title:"You Do — Your Turn",instruction:"Rewrite each report sentence correcting tense and parallel structure.",tasks:["The kererū helped forests by dispersing seeds, it also pollinated flowers, and to eat large fruit.","Conservation programmes included: fencing predators out, monitoring population, and they released captive-bred birds.","The wetland provides habitat for many species, it filtered water, and food for migratory birds was supplied.","✦ Bonus: Write a 5-sentence report paragraph about a NZ species or environment. Use consistent present tense and at least one parallel list."]},[{code:"Writing — Writing Process (Practice)",label:"Editing for report conventions",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Report writing has specific conventions — consistent present tense for timeless facts, parallel grammatical structure in lists — that students must identify and apply when editing. This lesson builds the targeted checking habits needed to produce accurate, authoritative formal writing at Phase 2.'},{code:"Writing — Sentence Structure (Knowledge)",label:"Parallel structure in lists",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "Parallel structure means that items in a list share the same grammatical form — all verb phrases, all noun phrases, or all adjectives. Non-parallel lists (mixing verbs, nouns, and clauses) disrupt flow and signal inconsistent grammatical control. Parallel structure is a convention of formal and informational writing at Years 5–6." Students learn to identify and repair non-parallel constructions as part of their report editing repertoire.'}])},2:{Monday:g("Commas: advanced & embedded lists","Writing — Punctuation (Knowledge & Practice): embedded lists sit within a larger sentence structure; students punctuate them correctly and distinguish between simple lists requiring commas and complex lists requiring semicolons.",{title:"I Do — Lists Inside Sentences",instruction:"We know commas in simple lists. This week: embedded lists — lists that sit inside a more complex sentence structure, sometimes requiring semicolons to avoid confusion.",example:'Simple list: "She packed a torch, a map, and a compass." | Complex list (semicolons): "The teams were: Auckland, led by Sofia; Wellington, captained by Hemi; and Christchurch, coached by Dr Patel."',demonstration:"The complex list uses semicolons because the list items themselves contain commas (led by Sofia, captained by Hemi). Using regular commas would make it impossible to tell where one item ends and the next begins. Rule: if list items contain commas — use semicolons to separate them.",tip:"Do your list items already contain commas? If yes — use semicolons to separate the items (super-commas). If no — regular commas."},{title:"We Do — Comma or Semicolon List?",instruction:"Decide whether each list needs commas or semicolons. Add the correct punctuation.",sentences:["The countries represented were France the fashion capital Italy home of pasta and Japan known for innovation.","She needed flour eggs and butter.","The judges were Mr Chen a retired principal Ms Raka an author and Dr Patel a scientist."],prompt:"Do any list items contain commas already? That decides whether you need semicolons."},{title:"You Do — Your Turn",instruction:"Add correct list punctuation (commas or semicolons) to each sentence.",tasks:["The competitors came from Auckland a city of 1.7 million Dunedin home of the oldest university and Tauranga one of the fastest-growing cities.","For the recipe you will need flour sugar butter and two eggs.","The panel included Dr Aroha Ngata a linguist Professor James Kim a biologist and Ms Sara Osei an environmental lawyer.","✦ Bonus: Write two list sentences of your own — one that needs commas, one that needs semicolons. Explain your punctuation choices."]},[{code:"Writing — Punctuation (Knowledge)",label:"Embedded lists: commas vs. semicolons",detail:`NZC Phase 2 Writing — Punctuation (Knowledge): "In a simple list, commas separate items (a torch, a map, a compass). When list items themselves contain commas, semicolons are used to separate the items to prevent ambiguity — this is sometimes called the 'super-comma' use of the semicolon. Students learn to assess their list items for embedded commas before deciding which separator to use." This extends both list punctuation and semicolon knowledge from earlier terms.`},{code:"Writing — Punctuation (Practice)",label:"Applying advanced list punctuation",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including complex list structures. This lesson consolidates list punctuation knowledge from Terms 1 and 2 and extends it to the advanced case — embedded lists with commas — giving students a reliable decision rule (do list items contain commas?) that they can apply independently in formal and informational writing.'}]),Tuesday:g("Passive voice: introduction and purpose","Writing — Sentence Structure (Knowledge): the passive voice shifts the focus from the agent (doer) to the receiver of the action; students form the passive correctly and understand when it is appropriate in formal and informational writing.",{title:"I Do — When the Receiver Is More Important",instruction:"In active voice, the subject does the action. In passive voice, the subject receives the action. Watch me switch between them and see when each is appropriate.",example:'Active: "Scientists discovered a new species." | Passive: "A new species was discovered by scientists."',demonstration:"Active: focus on scientists (the doers). Passive: focus on the species (the discovery — what matters). Passive is formed with: be + past participle (was discovered). The agent can be included (by scientists) or omitted when unknown or unimportant. In reports and formal writing, passive is common because the focus is on what happened, not who did it.",tip:"Passive = be + past participle. Use it when the doer is unknown, unimportant, or when you want to focus on what happened rather than who did it."},{title:"We Do — Active or Passive?",instruction:"Identify whether each sentence is active or passive, then convert it to the other form.",sentences:["The taniwha was defeated by the rangatira.","Scientists have analysed the samples.","The bill was passed by Parliament last year."],prompt:"What is the subject? Is it doing or receiving the action? When does passive sound more appropriate?"},{title:"You Do — Your Turn",instruction:"Convert each active sentence to passive. Then decide which version is better for the given context.",tasks:['Active: "Researchers tested the new medicine." → Convert to passive. (Context: a medical report)','Active: "Someone vandalised the sign." → Convert to passive (agent unknown).','Active: "The government introduced new regulations." → Convert to passive. (Context: formal document)',"✦ Bonus: Write a paragraph of 5 sentences about a scientific discovery or historical event. Use passive voice at least twice where it is genuinely more appropriate than active."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Active vs. passive voice",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "The passive voice is formed using the auxiliary verb 'be' (is/are/was/were/has been) + the past participle of the main verb. In the passive voice, the grammatical subject receives the action rather than performing it. The agent (doer) may be expressed in a 'by' phrase or omitted. Passive voice is appropriate in formal and informational writing when the action or result is more important than the agent."`},{code:"Writing — Sentence Structure (Practice)",label:"Using passive voice in formal writing",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of structures." The passive voice is a formal writing convention expected in reports, scientific writing, and formal argument at Years 5–6. This lesson develops students' ability to form the passive accurately and to make an informed choice between active and passive based on focus, formality, and whether the agent is known or important.`}]),Wednesday:g("Evidence + explanation: the CEE structure","Writing — Text Structure (Knowledge & Practice): effective persuasive paragraphs state a Claim, provide Evidence, and offer Explanation (CEE); students structure their argument paragraphs using this framework.",{title:"I Do — The Three-Part Argument",instruction:"Strong persuasive paragraphs follow a pattern: Claim (what you argue) → Evidence (proof or example) → Explanation (why the evidence supports the claim). Watch me build a CEE paragraph.",example:'C: "Schools should have longer lunch breaks." E: "Research by the University of Auckland found that students who had 45-minute lunches showed improved concentration in afternoon sessions." Ex: "This demonstrates that adequate rest time directly impacts academic performance — students who return to class refreshed are better able to focus and retain information."',demonstration:'Claim: states the position clearly. Evidence: a specific fact, statistic, or example (not vague — "research shows" is weak; "research by X found Y" is strong). Explanation: unpacks WHY the evidence proves the claim — this is the part students most often miss.',tip:'After your evidence, always ask: "so what?" Your explanation is the answer to "so what?" — it connects the evidence to the claim.'},{title:"We Do — Build the CEE",instruction:"Label each sentence C, E, or Ex. Then write the missing part.",sentences:['"Access to green spaces improves mental health. [missing evidence] This shows that the natural environment has measurable psychological benefits."','"Physical activity should be part of every school day. [add your own evidence and explanation]"'],prompt:"Where is the gap — claim, evidence, or explanation? What would fill it most powerfully?"},{title:"You Do — Your Turn",instruction:"Write a full CEE paragraph for each topic.",tasks:["Topic: students should be taught financial literacy in school.","Topic: every school should have a garden.","✦ Bonus: Write a CEE paragraph about a topic you genuinely care about. Then highlight: C (blue), E (green), Ex (yellow). Make sure the explanation unpacks exactly WHY the evidence supports the claim."]},[{code:"Writing — Text Structure (Knowledge)",label:"CEE paragraph structure",detail:`NZC Phase 2 Writing — Text Structure (Knowledge): "Effective persuasive paragraphs are structured around a Claim (a clear statement of position), Evidence (a specific supporting fact, statistic, or example), and Explanation (an analysis of why the evidence supports the claim). The explanation — sometimes called the 'so what?' — is the most frequently omitted part of student argument paragraphs and the most important for demonstrating genuine reasoning." This three-part structure is a key Phase 2 text structure expectation for persuasive writing.`},{code:"Writing — Text Structure (Practice)",label:"Structuring persuasive paragraphs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail" in persuasive writing. The CEE framework makes this expectation concrete — it gives students a step-by-step structure for building an argument paragraph that moves from claim to evidence to reasoned explanation, developing the logical thinking that underpins effective persuasion at Phase 2.'}]),Thursday:g("Editing: converting passive to active (or vice versa)","Writing — Writing Process (Practice): students audit a passage for voice, converting passive to active where it creates more energy and active to passive where formality or focus demands it.",{title:"I Do — Voice Audit",instruction:"The right voice depends on context. In narrative and persuasion, active is usually stronger. In formal reports, passive is often appropriate. Watch me audit a passage and make purposeful voice choices.",example:'"The decision was made by the committee to cancel the event. All tickets were refunded. Customers were disappointed." → Active: "The committee decided to cancel the event. They refunded all tickets. Customers were disappointed."',demonstration:'Three passive sentences → two converted to active (committee decides, refunds tickets — they are the clear agents). The third ("customers were disappointed") stays — the customers are the focus, not whoever disappointed them. Voice choices are purposeful, not mechanical.',tip:"Convert to active when: the agent matters and is clear. Stay passive when: the agent is unknown, unimportant, or you want to focus on what happened."},{title:"We Do — Voice Audit Together",instruction:"For each sentence, decide: active or passive? Convert if needed. Explain your choice.",sentences:["A new study was published last week by researchers at Victoria University.","The results were announced at 3 p.m. (agent unknown — leave passive or convert?)","Mistakes were made by the council during the planning process."],prompt:"Who is the agent? Does the agent matter here? Which voice serves the meaning better?"},{title:"You Do — Your Turn",instruction:"Audit this passage for voice. Convert each sentence to the more appropriate voice, or leave it if it's already correct. Explain each choice.",tasks:["The new library was opened by the Mayor in November. Books were donated by community members. Reading programmes were developed by teachers. The space is now used by over 200 students each week.","✦ Bonus: Write a paragraph of 5 sentences about a community event — 2 in active voice, 2 in passive voice, and 1 where you deliberately choose between them and explain why."]},[{code:"Writing — Writing Process (Practice)",label:"Voice audit in revision",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The voice audit — reading each sentence and asking 'which voice better serves this context?' — is a targeted revision strategy that requires students to understand both active and passive voice and to make purposeful decisions rather than applying either form mechanically.`},{code:"Writing — Sentence Structure (Practice)",label:"Active and passive voice in context",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of structures," including active and passive voice. This lesson develops the contextual judgment required to choose between them — not as a rule ("always use active") but as a purpose-driven decision: who is the agent? Does the agent matter? What should the reader focus on? These questions guide voice selection at Phase 2.'}])},3:{Monday:g("Formal vs. informal vocabulary choices","Writing — Vocabulary (Knowledge & Practice): formal vocabulary is appropriate for reports, arguments, and academic writing; students identify the register of different vocabulary choices and select language appropriate to purpose and audience.",{title:"I Do — Reading the Room with Words",instruction:"Every vocabulary choice signals a level of formality. Formal writing uses precise, impersonal language. Informal writing uses conversational, personal language. Watch me identify the register of different choices.",example:'Informal: "Kids need to get outside more." | Formal: "Children require regular access to outdoor environments."',demonstration:'"Kids" → informal (colloquial). "Children" → formal (standard). "get outside" → informal verb phrase. "require access to outdoor environments" → formal (precise, impersonal). Neither is wrong — but one fits a persuasive report and one fits a text message. Register is about matching language to audience and purpose.',tip:"Formal register: avoid contractions, colloquialisms, and first person (I/we). Use precise nouns and verbs. Informal: contractions fine, personal tone, conversational vocab."},{title:"We Do — Register Check",instruction:"Identify the informal words in each sentence and replace them with formal alternatives.",sentences:["Kids these days spend way too much time on their phones and stuff.","The government needs to do something about the housing crisis — it's getting out of hand.","Lots of research shows that exercise is really good for mental health."],prompt:"Which words are informal? What formal alternatives carry the same meaning?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence in a formal register appropriate for a report or argument essay.",tasks:["There's heaps of evidence that shows junk food is bad for kids.","We should totally make public transport free — it would be amazing for the environment.","Lots of people reckon that the voting age should be dropped to 16.","✦ Bonus: Write the same argument claim in two registers: one informal (text to a friend) and one formal (letter to a government minister). Compare the vocabulary choices."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Formal vs. informal register",detail:'NZC Phase 2 Writing — Vocabulary (Knowledge): "Language register refers to the level of formality appropriate to a context. Formal register uses precise, impersonal, standard vocabulary (children, require, significant, demonstrate) and avoids contractions, colloquialisms, and first-person pronouns. Informal register uses conversational vocabulary (kids, get, loads, stuff) and personal tone. At Years 5–6, students are expected to recognise and apply formal register in persuasive, report, and academic writing."'},{code:"Writing — Vocabulary (Practice)",label:"Adjusting vocabulary for audience and purpose",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." This lesson develops the skill of reading the register of a word before selecting it — asking 'is this formal or informal?' and 'does that match my audience and purpose?' Formal register is a specific expectation of the persuasive, report, and formal argument writing required at Phase 2.`}]),Tuesday:g("Subject-verb agreement: final tricky cases","Writing — Sentence Structure (Knowledge): students master the final difficult SVA cases — neither/nor, either/or, and sentences where the subject follows the verb (inverted sentences).",{title:"I Do — The Final SVA Challenges",instruction:"We've covered most SVA. These are the final tricky cases: neither/nor, either/or, and inverted sentences where the subject comes after the verb.",example:'"Neither the students nor the teacher <u>was</u> prepared." | "Either the principal or the teachers <u>are</u> responsible." | "There <u>are</u> three options."',demonstration:'Neither/nor and either/or: the verb agrees with the CLOSER subject. "Neither the students NOR THE TEACHER was" — teacher (singular) is closer → singular verb. "Either the principal OR THE TEACHERS are" — teachers (plural) is closer → plural verb. Inverted: "There are three options" — subject is "options" (plural) → plural verb.',tip:"Neither/nor + either/or: the verb agrees with the subject closest to the verb. Inverted sentence: find the real subject (usually after the verb)."},{title:"We Do — Choose the Right Verb",instruction:"Choose the correct verb form and explain the rule.",sentences:["Neither the manager nor the staff ___ (was/were) informed of the decision.","Either the principal or the students ___ (is/are) responsible for the scheduling.","There ___ (is/are) several reasons why this matters."],prompt:"What is the subject closest to the verb in neither/nor and either/or? What is the real subject in the inverted sentence?"},{title:"You Do — Your Turn",instruction:"Complete each sentence with the correct verb. Write the rule you applied in brackets.",tasks:["Neither the data nor the conclusions ___ (support/supports) that theory. [___]","Either the kaiako or the students ___ (present/presents) the findings. [___]","There ___ (remain/remains) significant challenges ahead. [___]","Neither the government nor the opposition ___ (has/have) a clear plan. [___]","✦ Bonus: Write 4 sentences using neither/nor (×2) and either/or (×2) with correct SVA in each."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"SVA: neither/nor, either/or, inverted sentences",detail:'NZC Phase 2 Writing — Sentence Structure (Knowledge): "With neither/nor and either/or, the verb agrees with the subject closest to the verb. With inverted sentences (There is/are; Here comes/come), the verb agrees with the real subject, which typically follows the verb. These are among the most complex SVA cases in English and represent the full range of agreement knowledge expected at Years 5–6."'},{code:"Writing — Writing Process (Practice)",label:"Editing for complex SVA",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Mastering these final SVA cases completes the full grammar editing toolkit for subject-verb agreement — students can now audit any sentence for agreement errors, including the most complex constructions encountered in formal and academic writing at Phase 2.'}]),Wednesday:g("Compound sentences in argument: building the case","Writing — Sentence Structure (Practice): in persuasive writing, compound sentences link related evidence and claims; students use coordinating conjunctions deliberately to show the logical connection between points.",{title:"I Do — FANBOYS in Formal Argument",instruction:"Compound sentences in argument writing do more than join ideas — they show the logical relationship between evidence and claim. Watch me use different conjunctions to build the case.",example:'"The research is clear, <u>yet</u> policy has not changed. The problem is significant, <u>so</u> action is required. We can ignore this evidence, <u>or</u> we can act on it."',demonstration:`"Yet" = the contrast is the problem (evidence ignored). "So" = this is the logical consequence (action required). "Or" = presents a binary choice (act or don't). Each compound sentence does rhetorical work — not just grammatical connection, but persuasive logic.`,tip:'In argument, compound sentences are most powerful when the conjunction does rhetorical work: "yet" highlights contradiction, "so" drives consequence, "or" forces a choice.'},{title:"We Do — Choose for Rhetoric",instruction:"Complete each argument compound sentence with the conjunction that does the most rhetorical work.",sentences:["The evidence is overwhelming ___ the government refuses to act.","Students deserve access to quality education ___ funding must be increased.","We can continue the current approach ___ we can invest in genuine change."],prompt:"What rhetorical job does each conjunction do? Is it showing contradiction, consequence, or choice?"},{title:"You Do — Your Turn",instruction:"Write compound sentences for each argument situation using the most rhetorically powerful conjunction.",tasks:["Situation: the problem exists but is being ignored.","Situation: the evidence points to a clear solution.","Situation: the reader must choose between two paths.","✦ Bonus: Write a persuasive paragraph of 5 sentences. Use at least three different coordinating conjunctions, each chosen for its rhetorical effect. Label the rhetorical job of each."]},[{code:"Writing — Sentence Structure (Practice)",label:"Compound sentences in argument",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity" across text types including persuasion. This lesson develops compound sentences as a rhetorical tool in argument — students learn that conjunction choice in persuasive writing is a strategic decision (showing contradiction, driving consequence, forcing a binary choice) rather than a purely grammatical one.'},{code:"Writing — Composing (Practice)",label:"Rhetorical effect of conjunction choice",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to select language that is "fit for purpose and audience." In persuasive writing, coordinating conjunction choice is a composing decision — "yet" signals contradiction and creates urgency; "so" signals consequence and drives action; "or" creates a forced choice that can be rhetorically powerful. Students at Phase 2 learn to select conjunctions for their argumentative impact.'}]),Thursday:g("Editing: adjusting formality for audience","Writing — Writing Process (Practice) & Vocabulary (Practice): students revise a piece of writing to shift its register — converting informal writing to formal, or identifying when a formal piece could benefit from a more accessible tone.",{title:"I Do — Rewriting for a Different Audience",instruction:"Watch me take the same information and rewrite it for two different audiences: a student newsletter and a formal report to the school board.",example:`Newsletter: "Did you know heaps of kids at our school don't eat breakfast? It's a big problem and we should definitely do something about it." | Report: "Data indicates that a significant proportion of students arrive without having consumed breakfast. This requires strategic intervention."`,demonstration:'Newsletter: colloquial ("heaps," "kids," "do something"), personal and direct. Report: formal ("data indicates," "significant proportion," "strategic intervention"), impersonal and precise. Same information — completely different register. The audience determines the vocabulary.',tip:"Formal: remove contractions, replace colloquialisms, use third person, choose Tier 2 vocabulary. Informal: conversational tone, first/second person, accessible vocabulary."},{title:"We Do — Register Shift",instruction:"Rewrite this informal paragraph in a formal register suitable for a report.",sentences:["Lots of students at our school reckon they don't get enough say in stuff that affects them. They want to have more of a voice in decisions about school rules and timetables and things like that. We think the school should definitely listen to them more."],prompt:"Which words need replacing? Should you use first person? What Tier 2 vocabulary fits the formal version?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence in the register shown in brackets.",tasks:[`"The government is spending heaps of money on this and it's not really working." [→ formal report]`,'"Utilisation of alternative transportation modalities may mitigate vehicular congestion." [→ accessible newsletter]','"This programme has demonstrated substantial efficacy in reducing socioeconomic disparities in educational outcomes." [→ accessible blog post]',"✦ Bonus: Take a piece of your own persuasive writing. Rewrite one paragraph for a completely different audience — shift the register deliberately."]},[{code:"Writing — Writing Process (Practice)",label:"Revising for audience and register",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact" and to write with awareness of "purpose and audience." This lesson develops the skill of register-shifting — reading writing through the eyes of a specific audience and revising vocabulary, sentence structure, and tone to match that audience's expectations and needs.`},{code:"Writing — Vocabulary (Practice)",label:"Adjusting vocabulary for formality",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience." Adjusting register requires substituting informal vocabulary (heaps, kids, do something) with formal alternatives (substantial, students, implement) and vice versa. This lesson builds the metalinguistic awareness of register that enables students to make deliberate vocabulary choices for any audience at Phase 2.'}])},4:{Monday:g("All apostrophe types: consolidation","Writing — Punctuation (Knowledge): students consolidate all three apostrophe uses — possession (singular and irregular plural), contraction, and the non-use for plurals — applying a systematic audit to a range of sentences.",{title:"I Do — The Apostrophe Audit",instruction:"There are three things to know about apostrophes: (1) possession (singular: cat's; plural ending in s: cats'; irregular plural: children's), (2) contraction (replacing omitted letters: don't), (3) never for plurals (cats not cat's).",example:`"The children's books were on the teachers' shelves. They couldn't find the one they'd borrowed." | ✗ "The cat's sat on the mat's."`,demonstration:`"Children's" — irregular plural possession (children don't end in s → add 's). "Teachers'" — regular plural possession (teachers end in s → just add '). "Couldn't" — contraction (could not). "They'd" — contraction (they would/had). The final example: "cat's" and "mat's" are wrong — these are just plurals, no apostrophe needed.`,tip:"Before every apostrophe, run the two-question test: (1) Is this possession? (2) Is this a contraction? If neither — no apostrophe."},{title:"We Do — Full Apostrophe Audit",instruction:"Find and correct every apostrophe error in this passage — including missing apostrophes AND incorrect ones.",sentences:["The student's in Room 12 couldn't find the teacher's marking. The schools principal said the teacher's bag had been left in the staffroom. Its a mystery — nobody know's where it is."],prompt:"Which apostrophes are correct? Which are wrong? Which words need apostrophes that are missing?"},{title:"You Do — Your Turn",instruction:"Correct all apostrophe errors in these sentences.",tasks:["The womens rugby team's gear was in the coaches van.","Hemi's and Ariana's project's were both excellent — they couldnt have done better.","Its the teachers job to ensure the students arent struggling.","The childrens playground near the rivers edge needed repair's.","✦ Bonus: Write a paragraph of 5 sentences about a school event. Use all three apostrophe types at least once each. Label each one: P (possession), C (contraction), or NP (no apostrophe — plural)."]},[{code:"Writing — Punctuation (Knowledge)",label:"All apostrophe types: consolidation",detail:"NZC Phase 2 Writing — Punctuation (Knowledge): Students consolidate all apostrophe conventions: singular possessives (cat's), regular plural possessives (cats'), irregular plural possessives (children's, women's), contractions (don't, they'd, it's), and the rule that apostrophes are never used to form plurals. The two-question test (possession? contraction? if neither — no apostrophe) provides a reliable self-checking strategy for all three cases."},{code:"Writing — Punctuation (Practice)",label:"Apostrophe audit across all types",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including apostrophes. This consolidation lesson integrates all apostrophe knowledge from Terms 1, 2, and 3 in a full audit context — students must simultaneously identify correct use, incorrect use, and missing apostrophes, applying all three rules accurately in a single editing task.'}]),Tuesday:g("Pronouns in formal writing: avoiding first person","Writing — Sentence Structure (Practice): formal writing typically avoids first-person pronouns (I, we) in favour of third-person and passive constructions; students practise rewriting personal claims as formal, impersonal statements.",{title:"I Do — Making It Impersonal",instruction:"In formal reports and arguments, first-person pronouns (I, we, my, our) are generally avoided. Instead, writers use third person, passive voice, or impersonal constructions. Watch me convert personal claims to formal ones.",example:'Personal: "I believe that schools need more funding." | Formal: "The evidence suggests that schools require additional funding." | "It is clear that funding for schools must increase."',demonstration:`"I believe" → "the evidence suggests" or "it is clear that." Personal conviction becomes a statement supported by external evidence. "We think" → "research indicates." "Our view" → "the available data." The argument feels more authoritative because it is no longer just one person's opinion.`,tip:'Replace "I think/believe/feel" with "the evidence shows/suggests," "it is clear that," or "research indicates." Replace "we" with "students," "schools," or passive constructions.'},{title:"We Do — Formalise Together",instruction:"Rewrite each sentence to remove first-person pronouns and increase formality.",sentences:["I think that young people should have a lower voting age.","We believe our school needs more sports equipment.","In my opinion, the current homework policy isn't working."],prompt:'What formal phrase can replace "I think/we believe/in my opinion"? Does the meaning change?'},{title:"You Do — Your Turn",instruction:"Rewrite each informal sentence in formal, third-person style.",tasks:["I feel strongly that all students deserve access to arts education.","We think the government should do more to protect native species.","In my view, social media is harmful to young people's wellbeing.","Our research showed that regular exercise improves academic performance.","✦ Bonus: Take a persuasive paragraph you've written. Identify every first-person pronoun. Rewrite the paragraph without any — using formal, impersonal constructions throughout."]},[{code:"Writing — Sentence Structure (Practice)",label:"Avoiding first person in formal writing",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences" and to write with awareness of "purpose and audience." In formal persuasive writing at Years 5–6, avoiding first-person pronouns and replacing them with impersonal constructions (the evidence suggests, it is clear that, research indicates) is a register convention that makes arguments sound more objective and authoritative.'},{code:"Writing — Vocabulary (Practice)",label:"Formal, impersonal language",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience," including formal vocabulary appropriate to persuasive and report writing. This lesson develops the specific vocabulary of formal argumentation — the phrases that replace personal conviction with the language of evidence and reasoned conclusion: "the evidence suggests," "it is apparent that," "data indicates."'}]),Wednesday:g("Concluding an argument: synthesis sentences","Writing — Text Structure (Knowledge & Practice): an effective argument conclusion synthesises the key claims (rather than simply repeating them), states the writer's final position, and leaves the reader with a clear call to action or closing thought.",{title:"I Do — More Than a Summary",instruction:"A weak conclusion just repeats the introduction. A strong conclusion synthesises — it brings the argument together and says: given all this evidence, here is where we must land.",example:'Weak: "In conclusion, I have shown that schools need more funding, exercise is important, and arts education matters." | Strong: "The evidence is compelling: when schools are properly resourced, students thrive academically, physically, and creatively. The question is not whether to invest — it is how soon."',demonstration:"The weak conclusion lists. The strong conclusion synthesises — it creates a new statement that couldn't have been made without the evidence in the body. It also ends with a forward-looking closing thought that stays with the reader.",tip:"Your conclusion should say something your introduction couldn't — because you now have all the evidence. Then end with a thought that keeps the reader thinking."},{title:"We Do — Synthesise Together",instruction:"The argument is about: (1) schools need outdoor space, (2) outdoor learning improves concentration, (3) physical activity reduces anxiety. Write a synthesis sentence that brings all three together — without just listing them.",sentences:['Draft synthesis: "When schools prioritise outdoor environments, students [what happens as a result of all three claims combined?]"'],prompt:"What does combining all three claims allow us to conclude that we couldn't say from one alone?"},{title:"You Do — Your Turn",instruction:"Write a full conclusion paragraph (3–4 sentences) for each argument topic. Include: a synthesis sentence, a final position statement, and a closing thought.",tasks:["Argument: all schools should teach te reo Māori. Key claims: (1) te reo is a taonga, (2) bilingualism benefits cognition, (3) language preserves culture.","Argument: screens should be limited in schools. Key claims: (1) screen time affects attention spans, (2) face-to-face interaction builds social skills, (3) physical activity declines.","✦ Bonus: Write a conclusion for a piece of persuasive writing you've already written this term. Replace any list-style repetition with genuine synthesis."]},[{code:"Writing — Text Structure (Knowledge)",label:"Argument conclusions: synthesis",detail:`NZC Phase 2 Writing — Text Structure (Knowledge): "An effective argument conclusion synthesises the key claims — it creates a statement that brings the whole argument together rather than simply repeating each point. It states the writer's final position clearly and ends with a closing thought, question, or call to action that leaves the reader engaged." Students at Years 5–6 are expected to write conclusions that go beyond summary to genuine synthesis.`},{code:"Writing — Text Structure (Practice)",label:"Writing persuasive conclusions",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail" across all stages of an argument, including the conclusion. This lesson develops the specific skill of synthesis — combining multiple claims into a new, overarching statement — which is the defining feature of a strong conclusion and a key Phase 2 text structure expectation in persuasive writing.'}]),Thursday:g("Editing: strengthening topic and concluding sentences","Writing — Writing Process (Practice): students audit each paragraph for its topic and concluding sentence, revising weak ones that merely state facts rather than making claims or connections.",{title:"I Do — The Paragraph Frame",instruction:"Every paragraph has a frame: the topic sentence (what this paragraph argues) and the concluding sentence (what this paragraph proves or adds to the overall argument). Watch me evaluate and strengthen both.",example:`Weak frame: "There are many different types of native birds in New Zealand. [body] New Zealand has many birds." | Strong frame: "New Zealand's native birds are a defining part of our natural identity. [body] Their protection is therefore not merely an environmental concern — it is a cultural one."`,demonstration:"The weak topic sentence just states a fact — it doesn't argue anything. The weak concluding sentence just repeats the topic. The strong topic sentence takes a position. The strong conclusion extends the argument and sets up the next paragraph.",tip:"Topic sentence: should be a claim, not just a fact. Concluding sentence: should add something — a consequence, a connection, or a forward link."},{title:"We Do — Strengthen the Frame",instruction:"Rewrite the topic and concluding sentences to make them argumentative and connected.",sentences:['Topic: "Exercise has effects on health." Body: [evidence about exercise and concentration]. Conclusion: "This shows exercise is good."','Topic: "Many students use social media." Body: [evidence about social media and sleep]. Conclusion: "Social media is a topic that affects many students."'],prompt:"What position should each topic sentence take? What does the evidence in the body PROVE? That's your concluding sentence."},{title:"You Do — Your Turn",instruction:"Rewrite each weak topic or concluding sentence to make it strong.",tasks:['Weak topic: "There is a problem with screen time in schools." → Rewrite as a clear claim.','Weak conclusion: "This is why exercise matters." → Rewrite to add a consequence or connection.','Weak topic: "Some people think the voting age should change." → Rewrite to take a clear position.',"✦ Bonus: Audit a piece of your own persuasive writing. For each paragraph, evaluate the topic and concluding sentence against the two criteria. Rewrite any that don't make claims or add connections."]},[{code:"Writing — Writing Process (Practice)",label:"Paragraph frame audit",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The paragraph frame audit — evaluating topic and concluding sentences against criteria (claim, not fact; connection, not repetition) — is a targeted revision strategy that directly improves the argument structure of each paragraph at Phase 2.'},{code:"Writing — Text Structure (Practice)",label:"Strengthening paragraph structure",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "organise ideas into paragraphs with a clear main idea, supported by relevant detail." This lesson develops the specific sub-skills: a topic sentence that makes a claim (not just states a topic) and a concluding sentence that extends the argument (not just repeats the claim). Both are key paragraph structure expectations at Phase 2.'}])},5:{Monday:g("Hyphen, dash, ellipsis: full review","Writing — Punctuation (Knowledge): hyphens join compound words and modifiers; dashes set off emphatic asides; ellipses create pause and suspense; students distinguish between all three marks and apply them accurately.",{title:"I Do — Three Different Marks, Three Different Jobs",instruction:"Hyphen (-), dash (—), and ellipsis (...) look similar but do completely different jobs. Watch me use each one correctly.",example:'Hyphen: "a well-known scientist" | Dash: "The answer — finally — was clear." | Ellipsis: "She reached for the handle... and pushed."',demonstration:"Hyphen: joins words that work together as a modifier before a noun (well-known, fast-paced, three-year-old). Dash: marks an emphatic aside or dramatic pause (used in pairs, or alone before a final statement). Ellipsis: creates suspense, trailing, or hesitation. Three marks, three jobs — never interchangeable.",tip:"Hyphen = joining. Dash = emphasising or interrupting. Ellipsis = trailing or suspense. Test: which job does this sentence need?"},{title:"We Do — Which Mark?",instruction:"Add the correct mark (hyphen, dash, or ellipsis) to each sentence and name its function.",sentences:["She was a well respected leader in the community.","The package had finally arrived and inside was exactly what she hoped for.","He opened the envelope slowly and then stopped."],prompt:"What job is needed here — joining, emphasising, or creating suspense? Which mark does that job?"},{title:"You Do — Your Turn",instruction:"Add the correct mark and name its function.",tasks:["The three year old boy reached for the box.","She knew the answer all along but waited for the right moment.","The light flickered once twice and then went out completely.","It was a thought provoking question that nobody had considered before.","✦ Bonus: Write 4 sentences of your own — one using a hyphen, one a dash for emphasis, one a dash before a final reveal, and one an ellipsis for suspense. Label each mark and its function."]},[{code:"Writing — Punctuation (Knowledge)",label:"Hyphen, dash, and ellipsis",detail:'NZC Phase 2 Writing — Punctuation (Knowledge): "A hyphen (-) joins compound words or compound modifiers before a noun (well-known, three-year-old). An em dash (—) marks an emphatic aside, interruption, or a dramatic pause before a final statement. An ellipsis (...) creates suspense, a trailing thought, or hesitation in dialogue. All three marks look related but perform entirely different functions and are not interchangeable." Students consolidate all three marks as part of the full punctuation range at Phase 2.'},{code:"Writing — Punctuation (Practice)",label:"Applying all three marks accurately",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." This consolidation lesson reviews the full set of expressive punctuation marks covered across the year — hyphen, dash, and ellipsis — requiring students to identify which mark is needed for which job and apply it accurately. All three marks appear in sophisticated writing at Phase 2 and beyond.'}]),Tuesday:g("Sentence variety: combining all sentence types","Writing — Sentence Structure (Practice) & Composing (Practice): students demonstrate control over the full range of sentence types — simple, compound, complex, and sentences with fronted adverbials — combining them effectively within a single paragraph.",{title:"I Do — The Full Sentence Toolkit",instruction:"This year we've built a full sentence toolkit. Today we use everything together — mixing sentence types deliberately within a single paragraph for maximum effect.",example:'"Before the match, the captain gathered the team. She spoke quietly, but every player listened. Although they were underdogs, they believed — and belief, she told them, was half the battle. They walked out together."',demonstration:"Sentence 1: fronted adverbial. Sentence 2: compound (but). Sentence 3: complex (although) + dash for aside. Sentence 4: simple — short and powerful. Four different types. Each chosen for what that moment needs.",tip:"Read your writing aloud after drafting. If every sentence starts the same way or is the same length — you haven't used your toolkit. Vary deliberately."},{title:"We Do — Identify and Mix",instruction:"Identify the sentence type of each sentence in this passage, then rewrite the passage to improve its variety.",sentences:["The storm hit suddenly. It was very strong. The trees bent. The power went out. People stayed inside. It lasted all night."],prompt:"All simple sentences — what variety can we introduce? Where should a compound, complex, or fronted adverbial go?"},{title:"You Do — Your Turn",instruction:"Write a paragraph of 6 sentences about a challenging experience. Use one sentence of each type:",tasks:["1. Fronted adverbial (time or place).","2. Short simple sentence (3–5 words) for impact.",'3. Compound sentence with "but" or "yet."','4. Complex sentence with "although" or "because."',"5. Complex sentence with a fronted subordinate clause (comma after it).","6. Sentence with a dash for emphasis or dramatic pause.","✦ Bonus: Label every sentence type. Read aloud — does the rhythm vary? Does each type appear in the right place?"]},[{code:"Writing — Sentence Structure (Practice)",label:"Full sentence toolkit: combined use",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures — simple, compound, and complex — for effect and clarity," and to "vary sentence openings." This lesson is a culminating demonstration of that expectation — students produce all sentence types in a single cohesive paragraph, making deliberate structural choices based on the effect each type creates at that particular moment in their writing.'},{code:"Writing — Composing (Practice)",label:"Sentence variety as a composing strategy",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including controlling rhythm, pace, and emphasis through sentence variety. This culminating lesson asks students to demonstrate full command of their composing toolkit — not just knowing the sentence types but deploying them purposefully, with awareness of the effect each creates in the reader's experience.`}]),Wednesday:g("Full peer edit: voice and clarity","Writing — Writing Process (Practice): students give and receive structured feedback on voice (clarity of position, appropriate register, use of evaluative language) and overall clarity of argument in a partner's persuasive writing.",{title:"I Do — Reading for Voice and Clarity",instruction:"Today I'll show you how to read a piece of persuasive writing specifically for voice and clarity — not just punctuation and grammar.",example:"Voice checklist: ☐ Is the writer's position clear from the opening? ☐ Is the register consistent (formal throughout)? ☐ Are evaluative words used precisely? | Clarity checklist: ☐ Is each claim supported by evidence? ☐ Does the explanation connect evidence to claim? ☐ Does the conclusion synthesise (not just repeat)?",demonstration:`I read the piece once for overall impression. Then I use the checklist — marking where the voice is unclear ("I can't tell what position you're taking here") and where the argument loses clarity ("this evidence doesn't connect to the claim above it"). Specific, evidence-based feedback only.`,tip:'Feedback must be specific: "Your voice is clear" is not helpful. "Your position becomes unclear in paragraph 2 — the claim and the evidence seem to be about different things" is.'},{title:"We Do — Model the Feedback",instruction:"Read this piece of persuasive writing and give voice and clarity feedback together.",sentences:[`"I think schools should have better food. Food is important. Research shows healthy food helps you learn. Many students don't eat breakfast which is bad. Schools should do something about this. In conclusion, I have shown that food matters."`],prompt:"Voice: is the position clear? Is the register consistent? Clarity: is evidence linked to claim? Does the conclusion synthesise?"},{title:"You Do — Your Turn",instruction:"Swap a persuasive piece with a partner. Give voice and clarity feedback using the full checklist.",tasks:["✦ Voice check 1: Is the writer's position unmistakably clear in the opening paragraph?","✦ Voice check 2: Is the register consistent — no slipping into informal or personal language?","✦ Voice check 3: Are evaluative words (crucial, significant, substantial) used precisely?","✦ Clarity check 1: Does every claim have a CEE structure?","✦ Clarity check 2: Does the conclusion synthesise rather than repeat?","✦ Write 3 specific pieces of feedback. For each: name the location, name the issue, suggest the fix."]},[{code:"Writing — Writing Process (Practice)",label:"Peer editing for voice and clarity",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "share writing with others and respond to feedback to improve their work." This lesson moves peer editing beyond surface accuracy to the deeper qualities of voice (clarity of position, consistency of register, precision of evaluative language) and argument clarity (CEE structure, synthesis conclusion). Giving specific, located, actionable feedback is an explicitly expected Phase 2 writing process skill.'},{code:"Writing — Composing (Practice)",label:"Voice and clarity in persuasion",detail:`NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to write with awareness of "purpose and audience." This lesson develops the evaluative lens for persuasive writing at Phase 2 — students learn to read their own and others' writing for the qualities that make an argument genuinely convincing: a clear and consistent voice, precise evaluative language, and argument structures that connect evidence to claim and claim to conclusion.`}]),Thursday:g("Editing: replacing weak vocabulary in argument","Writing — Writing Process (Practice) & Vocabulary (Practice): students identify and replace weak, vague, or informal vocabulary in persuasive writing with precise, formal, evaluative alternatives.",{title:"I Do — The Argument Vocabulary Audit",instruction:"Persuasive writing has its own vocabulary weaknesses. Watch me audit a passage for weak argument vocabulary and replace it with precise, formal alternatives.",example:'"A lot of people think that this is a big problem and something needs to be done." → "A significant proportion of the population regards this as a critical issue requiring immediate intervention."',demonstration:'"A lot of people" → "a significant proportion of the population." "Think" → "regards." "Big problem" → "critical issue." "Something needs to be done" → "requiring immediate intervention." Each replacement shifts register and precision. The argument sounds more authoritative.',tip:"Argument vocabulary audit list: a lot (→ many/significant/substantial), think/feel (→ argue/contend/maintain), big (→ significant/considerable), good/bad (→ beneficial/detrimental), do something (→ intervene/implement/address)."},{title:"We Do — Upgrade Together",instruction:"Replace every piece of weak argument vocabulary in this passage.",sentences:["Lots of students feel really strongly that the current system isn't fair. They think the school should do something about the homework policy because it's causing a lot of stress. It's a big deal and people should pay attention to it."],prompt:"Work through word by word. What formal, precise alternative fits each weak word?"},{title:"You Do — Your Turn",instruction:"Rewrite each sentence replacing all weak argument vocabulary with precise, formal alternatives.",tasks:["Lots of evidence shows that exercise is really good for mental health.","Many people think the government should do something about this really important issue.","A big part of the problem is that schools don't have enough money to do things properly.","✦ Bonus: Take a piece of your own persuasive writing. Apply the argument vocabulary audit. Count how many replacements you make. Assess whether the writing is more authoritative after."]},[{code:"Writing — Writing Process (Practice)",label:"Argument vocabulary audit",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The argument vocabulary audit — identifying informal, vague, or weak argument language and replacing it with precise formal alternatives — is a targeted revision strategy that directly improves the authority and persuasiveness of argument writing at Phase 2.'},{code:"Writing — Vocabulary (Practice)",label:"Precise evaluative vocabulary in argument",detail:'NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience," including formal and evaluative language in persuasive writing. This lesson consolidates all Term 4 vocabulary work — formal register, evaluative language, precise verbs and nouns — in an argument editing context, developing the integrated vocabulary awareness needed for sophisticated persuasive writing at Phase 2.'}])},6:{Monday:g("Vocabulary: evaluative language ('significant', 'crucial')","Writing — Vocabulary (Knowledge & Practice): evaluative language signals the writer's judgement of importance, certainty, and urgency; students build a repertoire of evaluative vocabulary and apply it precisely in persuasive contexts.",{title:"I Do — The Language of Judgement",instruction:"Evaluative vocabulary doesn't just describe — it judges. It tells the reader how important, certain, or urgent something is. Watch me build an evaluative vocabulary toolkit.",example:"Importance: crucial, vital, fundamental, essential, pivotal | Certainty: undeniable, compelling, conclusive, irrefutable | Scale: substantial, considerable, widespread, significant",demonstration:`"This is an important issue." → "This is a fundamental challenge." "Important" is vague — "fundamental" means it's at the root of everything else. "The problem is large." → "The problem is widespread and considerable." Each evaluative word does more than say "big" — it signals the nature and scope of the issue.`,tip:'Match the evaluative word to the claim: "crucial" for urgency, "fundamental" for root causes, "compelling" for strong evidence, "widespread" for scale.'},{title:"We Do — Choose the Right Evaluative Word",instruction:"Choose the evaluative word that best matches each claim.",sentences:["The evidence ___ (crucial/compelling/widespread) supports the need for change.","Access to clean water is ___ (vital/significant/considerable) — without it, communities cannot survive.","The damage caused by introduced predators is ___ (undeniable/essential/fundamental)."],prompt:"What does each sentence need: urgency, scale, certainty, or importance? Match the word to the need."},{title:"You Do — Your Turn",instruction:"Complete each sentence with the evaluative word that best matches the context. Explain your choice.",tasks:["The link between poverty and educational underachievement is ___.","Protecting Māori language is ___ to preserving Aotearoa's cultural identity.","The research provides ___ evidence that early intervention makes a difference.","✦ Bonus: Write a persuasive paragraph of 5 sentences about a topic you care about. Use at least five different evaluative vocabulary words. Label the judgement each one signals: importance, certainty, or scale."]},[{code:"Writing — Vocabulary (Knowledge)",label:"Evaluative vocabulary toolkit",detail:`NZC Phase 2 Writing — Vocabulary (Knowledge): "Evaluative vocabulary signals the writer's judgement about the importance (crucial, vital, fundamental), certainty (undeniable, compelling, conclusive), or scale (substantial, considerable, widespread) of a claim or piece of evidence. Using precise evaluative language strengthens persuasive writing by making the writer's assessment of the evidence explicit and well-calibrated." Students build a toolkit of evaluative vocabulary for use across argument text types at Phase 2.`},{code:"Writing — Vocabulary (Practice)",label:"Applying evaluative vocabulary in argument",detail:`NZC Phase 2 Writing — Vocabulary (Practice): Students are expected to "select and use words and phrases… that are fit for purpose and audience," including formal and evaluative vocabulary in persuasive writing. This lesson consolidates and extends the evaluative vocabulary work of Term 4, developing students' ability to choose the specific evaluative word that accurately matches the nature of their claim — urgency, scale, certainty, or importance.`}]),Tuesday:g("Linking adverbs: 'furthermore', 'however', 'therefore'","Writing — Text Structure (Knowledge): linking adverbs (furthermore, however, therefore, consequently, nevertheless) signal logical relationships between paragraphs and sentences in formal writing; students use them to create argument cohesion.",{title:"I Do — The Connective That Does Logical Work",instruction:"Linking adverbs (also called discourse markers) signal the logical relationship between one idea and the next. Watch me use them to create argument flow.",example:'"Exercise improves concentration. <u>Furthermore</u>, it reduces anxiety. <u>However</u>, not all schools provide adequate time for physical activity. <u>Therefore</u>, policy change is required."',demonstration:'"Furthermore" = adds another supporting point (in the same direction). "However" = introduces a contrast or complication. "Therefore" = draws a logical conclusion. "Consequently" = shows a result. "Nevertheless" = continues despite the preceding complication. Each one tells the reader exactly how the new sentence relates to the previous one.',tip:"Linking adverbs are followed by a comma. They stand at the start of the sentence or clause they introduce."},{title:"We Do — Choose the Linking Adverb",instruction:"Choose the best linking adverb for each gap and explain the logical relationship it signals.",sentences:["Native bird populations have declined sharply. ___, habitat loss continues to accelerate.","The evidence strongly supports this approach. ___, some critics argue the costs outweigh the benefits.","Te reo Māori is an official language of Aotearoa. ___, it must be resourced and supported in all public institutions."],prompt:"Is the next sentence adding, contrasting, or concluding? That determines the linking adverb."},{title:"You Do — Your Turn",instruction:"Add an appropriate linking adverb to create a logical connection between each pair of sentences.",tasks:["Physical activity improves academic performance. ___, schools should build exercise into every school day.","Many students find homework stressful. ___, research shows it has limited benefit for younger learners.","The government has increased funding for conservation. ___, more needs to be done to address the rate of species loss.","✦ Bonus: Write a persuasive paragraph of 5 sentences about an environmental issue. Use at least three different linking adverbs. Label the logical relationship each one signals."]},[{code:"Writing — Text Structure (Knowledge)",label:"Linking adverbs for argument cohesion",detail:`NZC Phase 2 Writing — Text Structure (Knowledge): "Linking adverbs (furthermore, however, therefore, consequently, nevertheless, moreover, in addition) signal the logical relationship between sentences and paragraphs in formal writing. 'Furthermore' and 'moreover' add support in the same direction; 'however' and 'nevertheless' introduce contrast or complication; 'therefore' and 'consequently' signal logical conclusions or results. They are placed at the start of the sentence or clause they introduce and are followed by a comma."`},{code:"Writing — Text Structure (Practice)",label:"Creating argument cohesion with linking adverbs",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "use cohesive devices — including pronouns, synonyms, and connectives — to link ideas within and across sentences and paragraphs." In formal argument writing, linking adverbs are the primary cohesion tool for signalling logical relationships between claims — they tell the reader whether the new sentence is adding evidence, introducing a complication, or drawing a conclusion. Their precise use is a key Phase 2 text structure expectation.'}]),Wednesday:g("Varied sentence openings: full year review","Writing — Sentence Structure (Practice) & Composing (Practice): students review and apply the full range of sentence opening strategies from across the year — subjects, fronted adverbials, adjective openers, gerund subjects, and subordinate clause openers.",{title:"I Do — Every Way to Start a Sentence",instruction:"Over the year we've learned many ways to open sentences. Today: the full review. Watch me use all five types in one passage.",example:`Subject: "The kererū is New Zealand's largest pigeon." | Fronted adverbial: "Across the canopy, it moves silently." | Adjective opener: "Ancient and unhurried, it feeds on the ripest berries." | Gerund subject: "Protecting such species requires urgent action." | Subordinate clause: "Although numbers have recovered, threats remain."`,demonstration:"Five sentences. Five different openers. The variety prevents monotony and creates a more dynamic, engaging paragraph. Each opener creates a different emphasis and relationship between the ideas.",tip:"If three consecutive sentences start the same way — you've found a variety problem. Open your toolkit and fix it."},{title:"We Do — Variety Audit",instruction:"List the first word of each sentence in this passage. Identify any repetition. Then rewrite to add variety.",sentences:["The government introduced new policies last year. The policies aimed to reduce emissions. The results have been mixed. The critics argue the changes don't go far enough. The supporters say they're a positive step forward."],prompt:'All sentences start with "The." Rewrite using at least four different opening strategies.'},{title:"You Do — Your Turn",instruction:"Write a paragraph of 5 sentences about a NZ issue. Use one of each sentence opener type:",tasks:["1. Subject-first (standard but precise).","2. Fronted time or place adverbial.","3. Post-positive adjective opener (Ancient and..., Bold and...).","4. Gerund subject (Protecting..., Understanding...).","5. Fronted subordinate clause (Although..., Because..., Unless...).","✦ Bonus: Label every sentence opener in a piece of your own writing. Identify any repetition and rewrite to add variety."]},[{code:"Writing — Sentence Structure (Practice)",label:"Full year sentence opener review",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "vary sentence openings to avoid repetition and create effect." This lesson consolidates all sentence opener strategies from across the year: subject-first, fronted time/place/manner adverbials, post-positive adjective openers, gerund subjects, and fronted subordinate clauses. Students demonstrate the ability to identify, produce, and vary all five types in a single paragraph.'},{code:"Writing — Composing (Practice)",label:"Sentence variety as a composing discipline",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including varying sentence openings. This culminating lesson establishes sentence opener variety as an editing discipline — students learn to audit first words, identify repetition, and use their full toolkit to add variety with intention, not just for the sake of it.'}]),Thursday:g("Improving argument cohesion","Writing — Text Structure (Practice) & Writing Process (Practice): students audit an argument for cohesion — checking that linking adverbs, pronoun reference, and repeated key ideas connect paragraphs into a logical whole.",{title:"I Do — The Cohesion Thread",instruction:"A cohesive argument feels like a conversation — each paragraph connects to the next. Watch me identify cohesion gaps and repair them using linking adverbs, pronouns, and repeated key ideas.",example:'Disconnected: "Native species are under threat. Introduced predators are the main cause. The government needs to act." → Cohesive: "Native species are under severe threat. The primary cause of this crisis is the proliferation of introduced predators. Consequently, urgent government intervention is required."',demonstration:'"This crisis" links back to "under severe threat." "Consequently" signals the logical result. The argument now flows as cause → result → response, not three separate facts.',tip:"Read your argument aloud. At every new sentence, ask: what word or phrase connects this to the previous sentence? If there's none — add one."},{title:"We Do — Cohesion Audit Together",instruction:"Find and fix every cohesion gap in this argument passage.",sentences:["Physical activity has significant benefits for student wellbeing. Schools have cut PE time. Students are experiencing higher rates of anxiety. The evidence supports increasing PE. The government should consider this."],prompt:"Where are the gaps? What linking devices would repair each break?"},{title:"You Do — Your Turn",instruction:"Rewrite this argument passage to create full cohesion between all sentences.",tasks:["Access to nature is important for children. Urban children have less access to green space. Mental health problems are increasing among young people. Research links green space to mental health. Cities need more parks.","✦ Bonus: Audit a piece of your own argument writing for cohesion. Draw connection arrows between consecutive sentences. Identify gaps and add linking devices to repair them."]},[{code:"Writing — Text Structure (Practice)",label:"Argument cohesion audit",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "use cohesive devices — including pronouns, synonyms, and connectives — to link ideas within and across sentences and paragraphs." In argument writing, cohesion is both a structural and a logical requirement — the argument must flow as a connected series of claims, evidence, and conclusions, not a list of related points. The cohesion audit makes gaps visible and gives students the tools to repair them.'},{code:"Writing — Writing Process (Practice)",label:"Revising for argument flow",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This lesson applies revision specifically to argument cohesion — teaching students to read their argument through the reader's eyes and ask: does each sentence connect logically to the one before it? Does the argument feel like a whole, or a collection of separate points?`}])},7:{Monday:g("Colons & semicolons: final practice","Writing — Punctuation (Knowledge & Practice): students consolidate the full range of colon and semicolon uses across text types, applying both marks with accuracy and confidence in extended formal writing.",{title:"I Do — The Full Colon & Semicolon Toolkit",instruction:"Let's consolidate the full range of uses for both marks — colons and semicolons — in formal writing contexts.",example:'Colon before list: "Three factors matter: evidence, reasoning, and clarity." | Colon before explanation: "The result was clear: the policy had failed." | Semicolon between related clauses: "The data is compelling; action can no longer be delayed." | Semicolon in complex lists: "Delegates came from Auckland, New Zealand; Sydney, Australia; and London, England."',demonstration:"Colon: (1) introduces a list after a complete sentence, (2) introduces an explanation or elaboration. Semicolon: (1) joins two closely related independent clauses, (2) separates complex list items that contain commas. All four uses require the part before the mark to be a complete sentence (except in complex lists).",tip:"Colon = something follows that elaborates or lists. Semicolon = two related complete sentences joined, or a complex list."},{title:"We Do — Colon or Semicolon?",instruction:"Add the correct mark (colon or semicolon) to each sentence.",sentences:["The argument rests on three pillars credibility, evidence, and logic.","The evidence is overwhelming inaction is no longer defensible.","Representatives attended from Wellington, the capital Auckland, the largest city and Christchurch, the South Island's main centre."],prompt:"Which use applies here — list, elaboration, related clauses, or complex list? That determines the mark."},{title:"You Do — Your Turn",instruction:"Add a colon or semicolon to each sentence. Name the use type.",tasks:["The policy change has one goal to reduce inequity in educational outcomes.","The report identified four key recommendations increased funding, better training, community engagement and regular review.","The scientific evidence is beyond question the planet is warming at an unprecedented rate.","Panels included Dr Aroha Ngata, a linguist Professor James Kim, a biologist and Ms Sara Osei, an environmental lawyer.","✦ Bonus: Write a formal argument paragraph that uses a colon for a list, a colon for an explanation, and a semicolon between related clauses — all correctly."]},[{code:"Writing — Punctuation (Knowledge)",label:"Colons & semicolons: full range of uses",detail:"NZC Phase 2 Writing — Punctuation (Knowledge): Students consolidate all uses of colons (before a list, before an explanation or elaboration) and semicolons (between closely related independent clauses, between complex list items containing commas). Both marks require grammatical awareness — the part before a colon must be a complete clause; the parts on either side of a semicolon must be complete sentences when joining clauses. This full review completes Phase 2 punctuation knowledge."},{code:"Writing — Punctuation (Practice)",label:"Applying colons and semicolons in formal writing",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect," including colons and semicolons in formal and argumentative writing. This consolidation lesson integrates all colon and semicolon knowledge from across the year in a formal writing context — the most demanding application of these marks at Phase 2.'}]),Tuesday:g("Tense consistency across text types","Writing — Sentence Structure (Knowledge) & Writing Process (Practice): different text types use different tenses (reports: present; recounts: past; argument: present; narrative: past or present); students identify and apply the correct tense convention for each text type.",{title:"I Do — Tense Belongs to Text Type",instruction:"Different text types use different tenses as a convention. Watch me identify the right tense for each context.",example:'Report: "The kiwi is nocturnal. It eats invertebrates." (present — timeless facts) | Recount: "We visited the reserve last Thursday." (past — specific past event) | Argument: "Evidence shows that funding is insufficient." (present — current situation) | Narrative: "She walked into the forest alone." (past — story)',demonstration:"Reports use present because the facts are timeless. Recounts use past because they describe completed events. Arguments use present because they're about current realities. Narratives use past (or present for dramatic effect). Mixing conventions within a text type signals lack of control.",tip:"Before writing, decide: what text type is this? What tense convention does it use? Commit to it throughout."},{title:"We Do — Identify and Fix",instruction:"Identify the text type and correct tense for each passage, then fix any inconsistencies.",sentences:["[Report] The tuatara was an ancient reptile. It lived only in New Zealand. Its skin is scaly and rough.","[Argument] Access to clean water will be a fundamental right. Evidence showed that inequity in water access leads to significant health disparities."],prompt:"What tense convention should each text type use? Which verbs break the convention?"},{title:"You Do — Your Turn",instruction:"Rewrite each passage in the correct tense convention for its text type.",tasks:["[Report] The kererū was New Zealand's largest pigeon. It ate large fruit that other birds couldn't consume. This made it crucial for forest regeneration.","[Argument] Research showed that regular exercise improved academic performance. Students who exercised daily scored higher on concentration tests. This is why schools need to prioritise PE.","✦ Bonus: Write one paragraph of each text type (report, recount, argument, narrative) on the same topic — kaitiakitanga. Make sure each uses the correct tense convention throughout."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Tense conventions by text type",detail:`NZC Phase 2 Writing — Sentence Structure (Knowledge): "Different text types use different tense conventions: reports and information texts use present tense (timeless facts: 'kiwi are nocturnal'); recounts use past tense (completed events: 'we visited'); arguments typically use present tense (current situations: 'evidence shows'); narratives use past tense (completed stories) or present for dramatic effect. Understanding and applying these conventions is a key expectation at Years 5–6." Mixing tense conventions signals loss of text type control.`},{code:"Writing — Writing Process (Practice)",label:"Tense audit across text types",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate." Applying tense convention audit across all four main text types — report, recount, argument, narrative — completes the full range of tense accuracy work at Phase 2. Students learn to identify the text type before auditing, ensuring the right convention is applied rather than just consistency within one convention.'}]),Wednesday:g("Complex sentences: full subordination toolkit","Writing — Sentence Structure (Practice): students apply the full range of subordinating conjunctions from across the year in a single writing task, demonstrating controlled, purposeful use of complex sentences in argument writing.",{title:"I Do — The Full Subordination Toolkit",instruction:"Over the year we've learned many subordinating conjunctions. Today: the full toolkit in action within an argument paragraph.",example:'"<u>Although</u> progress has been made, challenges remain significant. <u>Because</u> funding is limited, solutions must be targeted. <u>Unless</u> communities are involved, policies will fail. <u>While</u> the evidence is compelling, political will is lacking. <u>Since</u> the problem first emerged, awareness has grown."',demonstration:"Five different subordinating conjunctions in five sentences — although (contrast), because (cause), unless (condition), while (simultaneity/contrast), since (time). Each one creates a different logical relationship. Together, they give the argument nuance and sophistication.",tip:"Choose the conjunction based on the logical relationship you want to express — not on which one sounds good. Each conjunction makes a specific claim about how two ideas relate."},{title:"We Do — Conjunction for the Relationship",instruction:"Choose the subordinating conjunction that best expresses the logical relationship in each sentence.",sentences:["___ (Although/Because/Unless) the data is inconclusive, action should not be delayed.","___ (Since/While/Unless) we address the root causes, the problem will persist.","___ (Because/Although/Since) the programme was introduced three years ago, results have been consistently positive."],prompt:"What logical relationship does this sentence express: contrast, cause, condition, simultaneous, or time?"},{title:"You Do — Your Turn",instruction:"Write complex sentences using each conjunction to express the given logical relationship.",tasks:['Use "although" to show that evidence exists despite opposition.','Use "because" to explain why action is needed.','Use "unless" to state a condition for success.','Use "while" to acknowledge a complication alongside a claim.','Use "since" to show how long a problem has existed.',"✦ Bonus: Write a persuasive paragraph of 6 sentences about a topic you care about. Use five different subordinating conjunctions. Label each conjunction and the logical relationship it expresses."]},[{code:"Writing — Sentence Structure (Practice)",label:"Full subordination toolkit in argument",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures — including complex sentences — for effect and clarity." This culminating lesson asks students to demonstrate full command of the subordinating conjunction toolkit in argument writing — producing multiple different complex sentence types in a single paragraph, choosing each conjunction based on the precise logical relationship they want to express.'},{code:"Writing — Composing (Practice)",label:"Subordination for argument nuance",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to select language that is "fit for purpose and audience." In formal argument, subordinating conjunctions are composing tools — they signal exactly what logical claim is being made (contrast, cause, condition, simultaneity, time). Using the full range purposefully is a mark of argumentative sophistication at Phase 2.'}]),Thursday:g("Editing: improving argument cohesion","Writing — Writing Process (Practice) & Text Structure (Practice): students apply a full cohesion audit to argument writing, using linking adverbs, pronoun reference, and structural signalling to create a logically connected whole.",{title:"I Do — The Full Cohesion Audit",instruction:"Today I audit a complete argument piece for cohesion — not just within paragraphs, but between them.",example:"Between-paragraph cohesion checklist: ☐ Does each paragraph opening connect to the previous paragraph? ☐ Are linking adverbs used to signal logical flow? ☐ Are key terms repeated or referred to by pronoun?",demonstration:'"...This demonstrates the scale of the problem. [¶] Furthermore, the consequences extend beyond the immediate community. This broader impact..." — "Furthermore" links forward. "This broader impact" picks up "consequences" from the previous paragraph. The argument flows as a connected whole.',tip:"Read the first sentence of each paragraph only. Do they form a logical sequence? That tells you whether the argument's macro-cohesion is strong."},{title:"We Do — Macro-Cohesion Audit",instruction:"Read only the first sentence of each paragraph in this argument. Identify where the cohesion breaks.",sentences:[`Para 1: "Te reo Māori is one of New Zealand's two official languages." | Para 2: "Research shows that bilingualism improves cognitive function." | Para 3: "Schools have cut time for language learning." | Para 4: "The government must act to protect this taonga."`],prompt:"Does each paragraph opening connect to the previous one? Where are the gaps? What linking devices would repair them?"},{title:"You Do — Your Turn",instruction:"Rewrite these paragraph openings to create full macro-cohesion in the argument.",tasks:['Para 1: "Physical activity has proven benefits for student wellbeing."','Para 2: "Many schools have reduced PE time in recent years."','Para 3: "Student anxiety rates have increased significantly."','Para 4: "Policy change is urgently needed."',"✦ Bonus: Take a piece of your own argument writing. Read only the first sentence of each paragraph. Rewrite any that don't connect logically to the previous paragraph — using linking adverbs, pronoun reference, or repeated key terms."]},[{code:"Writing — Writing Process (Practice)",label:"Full cohesion audit: argument",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." This culminating cohesion lesson audits both micro-cohesion (within paragraphs) and macro-cohesion (between paragraphs) — teaching students to read the argument's logical spine (the first sentence of each paragraph) as the clearest indicator of whether the whole piece holds together.`},{code:"Writing — Text Structure (Practice)",label:"Macro-cohesion in argument writing",detail:'NZC Phase 2 Writing — Text Structure (Practice): Students are expected to "use cohesive devices — including pronouns, synonyms, and connectives — to link ideas within and across sentences and paragraphs." This lesson extends cohesion work to the macro level — the argument as a whole. Students learn that a well-structured argument connects not just sentences within paragraphs but paragraphs to each other, creating a logical progression from claim to evidence to conclusion.'}])},8:{Monday:g("Spelling: consolidation of year's tricky words","Writing — Conventions (Knowledge): students consolidate spelling of the year's most challenging words, applying morphological, visual, and mnemonic strategies to words they consistently misspell.",{title:"I Do — The Year's Trickiest Words",instruction:"Let's revisit the words that trip up most Year 5–6 writers. I'll show a different strategy for each cluster.",example:"Homophones: their/there/they're | Suffixes: necessary, accommodate, embarrass | Tricky middles: separate (a rat in separate), government (govern-ment) | Silent letters: Wednesday, knight, psychology",demonstration:`Strategy 1 — Find the word in the word: "sep-A-RAT-e" has a rat in it. "Wed-NES-day" has NES in the middle. Strategy 2 — Mnemonic: "One Collar, Two Socks" → accommodate has one c, two m's (aCCommodate? — actually one c, two m's). Strategy 3 — Look, Cover, Write, Check for muscle memory.`,tip:"Your personal spelling list is the most important. What words do YOU consistently misspell? Those are the ones to practise today."},{title:"We Do — Strategy Match",instruction:"For each tricky word, decide the best strategy and apply it.",sentences:["necessary (one c, two s — find a mnemonic)","their/there/they're (expand the contraction to check)","rhythm (RHYTHM Helps Your Two Hips Move — first letters)"],prompt:"Which strategy works best for each word? Can you teach your strategy to a partner?"},{title:"You Do — Your Turn",instruction:"Use Look, Cover, Write, Check for each word. Then write a sentence using each correctly.",tasks:["accommodate (two c, two m)",'definitely (not "definately" — de-finite-ly)',"occurrence (two c, two r)",'privilege (not "priviledge" — no d)',"✦ Bonus: Create your personal end-of-year spelling list. Write the 5 words you most often misspell. Apply one strategy to each. Test yourself tomorrow."]},[{code:"Writing — Conventions (Knowledge)",label:"Year spelling consolidation",detail:'NZC Phase 2 Writing — Conventions (Knowledge): "Students develop spelling knowledge through a range of strategies including visual memory (Look, Cover, Write, Check), morphological analysis (identifying meaningful word parts), mnemonics, and analogy (finding the word within the word). At Year 5–6, students are expected to spell high-frequency words accurately and to develop strategies for words they find difficult." This consolidation lesson addresses the most persistently challenging words across the year.'},{code:"Writing — Writing Process (Practice)",label:"Personal spelling strategies",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing to check that it makes sense and is accurate, including checking spelling." This lesson builds metacognitive awareness about personal spelling weaknesses — students identify their own most-misspelled words and apply the strategy most effective for each one, developing the self-monitoring habit that supports spelling accuracy across all writing contexts.'}]),Tuesday:g("Prepositional phrases: all uses consolidated","Writing — Sentence Structure (Practice): students consolidate all prepositional phrase uses from across the year — location, direction, time, manner, and setting — applying them in a single extended writing task.",{title:"I Do — The Preposition Toolkit",instruction:"Over the year we've used prepositional phrases for location, direction, time, and setting. Watch me use the full range in one passage.",example:'Location: "in the manuka scrub" | Direction: "across the ridge towards the sea" | Time: "before dawn, throughout the morning" | Setting opener: "At the edge of the old wharf, she waited" | Stacked: "deep in the valley, below the snowline, just before the track turned south"',demonstration:"Each prepositional phrase type does a different job. Together they create a rich, precisely located scene. The stacked version shows how multiple prepositional phrases can build a vivid sense of place when layered carefully.",tip:'Prepositional phrases are most powerful when they give the reader something specific — not "near the river" but "at the bend where the river narrows."'},{title:"We Do — Layer the Phrases",instruction:"Expand each bare sentence by adding prepositional phrases of location, direction, and time.",sentences:["She walked.","The kiwi moved.","He waited."],prompt:"Which type of prepositional phrase adds the most to each sentence — location, direction, or time? Can you layer more than one?"},{title:"You Do — Your Turn",instruction:"Write a narrative or descriptive paragraph of 5 sentences about a NZ outdoor setting. Use at least five different prepositional phrases — at least one each of location, direction, time, and setting opener. Label each one.",tasks:["Setting options: a West Coast beach | the Southern Alps | a Northland kauri forest | a Canterbury braided river","✦ Checklist: ☐ Location phrase ☐ Direction phrase ☐ Time phrase ☐ Fronted setting opener ☐ Stacked prepositional phrases","✦ Bonus: Rewrite the same paragraph without any prepositional phrases. Compare the two versions — what is lost?"]},[{code:"Writing — Sentence Structure (Practice)",label:"Prepositional phrases: full year consolidation",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "expand sentences by adding prepositional phrases to express location, time, and direction." This consolidation lesson integrates all prepositional phrase types from across the year — location, direction, time, manner, and fronted setting openers — in a single extended writing task. Students demonstrate the ability to select and layer prepositional phrases purposefully for scene-setting and narrative precision.'},{code:"Writing — Composing (Practice)",label:"Prepositional phrases for immersive description",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including creating vivid, specific settings. Prepositional phrases are the primary tool for precise location in descriptive and narrative writing — they place the reader in a specific physical space (not "near the river" but "at the bend where the river narrows over the flat grey stones"). This lesson develops that specificity as a composing discipline.'}]),Wednesday:g("Fronted adverbials: full repertoire review","Writing — Sentence Structure (Practice): students apply the full range of fronted adverbial types from across the year — time, place, contrast, manner, and condition — in a single extended writing or editing task.",{title:"I Do — The Full Fronted Adverbial Toolkit",instruction:"Over the year we practised five types of fronted adverbial. Watch me use all five in one narrative passage, with a comma after each.",example:'Time: "Before the sun had risen, she was already moving." | Place: "High above the valley, the hawk circled." | Contrast: "Despite the cold, he swam." | Manner: "With great care, she lifted the taonga." | Condition: "If the weather held, they would reach the hut by nightfall."',demonstration:"Each fronted adverbial sets up the main clause differently — time positions us, place locates us, contrast creates tension, manner shows how, condition introduces stakes. Together in a paragraph, they create variety and atmosphere simultaneously.",tip:"Comma after every fronted adverbial — without exception. And vary the type: don't use three time openers in a row."},{title:"We Do — Type Identification and Writing",instruction:"Identify the type of each fronted adverbial, then write one more of the same type.",sentences:["Throughout the long night, the fire kept burning.","With surprising calm, she faced the crowd.","Although the climb was steep, they kept going."],prompt:"What type is each fronted adverbial — time, manner, contrast? Write one more of each type."},{title:"You Do — Your Turn",instruction:"Write a narrative or argument paragraph of 5 sentences. Use one fronted adverbial of each type:",tasks:["1. Time: (Before/After/Throughout/By the time...)","2. Place: (High above.../Deep in.../At the edge of...)","3. Contrast: (Although.../Despite.../Even though...)","4. Manner: (With [noun]/.../Silently and...)","5. Condition: (If.../Unless.../Should...)","✦ Bonus: Label every fronted adverbial type in a piece of your own writing. Identify any type you haven't used and add one example."]},[{code:"Writing — Sentence Structure (Practice)",label:"Fronted adverbials: full year review",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "vary sentence openings to avoid repetition and create effect," using fronted adverbials of time, place, manner, contrast, and condition. This culminating lesson integrates all five fronted adverbial types from across the year in a single writing task — students demonstrate control over both the punctuation (comma after each) and the variety (different types used deliberately for different effects).'},{code:"Writing — Composing (Practice)",label:"Fronted adverbials as composing tools",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader," including varying sentence openings for effect. This lesson establishes fronted adverbials as composing tools — students learn to choose the type based on what each sentence needs (positioning, contrast, condition, manner, time) rather than using the same type repeatedly. Deliberate variety in fronted adverbial type is a marker of composing sophistication at Phase 2.'}]),Thursday:g("Full editing checklist: seven passes","Writing — Writing Process (Practice): students apply the full seven-pass editing checklist to an extended piece of writing, systematically checking for punctuation accuracy, grammar, vocabulary precision, sentence variety, and cohesion.",{title:"I Do — The Seven-Pass Edit",instruction:"This is our most comprehensive editing checklist — seven passes, one focus at a time. Watch me work through each pass on a sample passage.",example:"Pass 1: Capitals & full stops | Pass 2: All punctuation marks (commas/colons/semicolons/apostrophes/dialogue/dashes/ellipsis) | Pass 3: Tense consistency & SVA | Pass 4: Vocabulary (vague words / formal register) | Pass 5: Sentence variety (length, openers) | Pass 6: Cohesion (linking devices, pronoun reference) | Pass 7: Paragraph structure (topic sentences, conclusions)",demonstration:"I read the passage once. Then I work through each pass with a specific colour or symbol. Pass 1 only: every sentence boundary. Pass 2: every punctuation mark — is it there? Is it correct? And so on. Each pass is fast because it has one focus.",tip:"Seven passes sounds slow. It's actually faster than reading the whole piece vaguely four times — because each pass has a clear target."},{title:"We Do — Class Seven-Pass Edit",instruction:"Work through all seven passes on this passage as a class.",sentences:["every year in new zealand thousands of native birds are killed by introduced predators the damage is immense. stoats rats and possums have devastated our ecosystems since they arrived. conservation teams work tirelessly to address this but the government doesnt always provide enough funding. its crucial that we act now because the cost of inaction will be even greater. our native species deserve better and so do we."],prompt:"Pass by pass — what are we fixing? Keep a running total of improvements."},{title:"You Do — Your Turn",instruction:"Apply the full seven-pass checklist to this argument passage. Rewrite it with all errors corrected.",tasks:["many student's in aotearoa dont have access to regular outdoor education. research show's that outdoor learning improve's concentration, creativity and wellbeing. this is important for all children not just those in rural areas urban student's need this to. schools should therefore prioritise outdoor learning in there programmes. its not just a nice to have its essential.","✦ Bonus: Apply the seven-pass checklist to your own most recent piece of writing. Track every improvement across all seven passes."]},[{code:"Writing — Writing Process (Practice)",label:"Seven-pass comprehensive edit",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact." The seven-pass checklist is the most comprehensive editing tool students have built across the year — it integrates all writing knowledge from Terms 1–4 into a systematic, sequential audit. This lesson develops the editing discipline that students will carry into Year 7 and beyond.'},{code:"Writing — Writing Process (Practice)",label:"Full year skills: integrated application",detail:"NZC Phase 2 Writing — Writing Process (Practice): This consolidation lesson asks students to demonstrate mastery of the full year's writing skills in a single integrated editing task. Each of the seven passes corresponds to a knowledge domain: punctuation conventions, grammar accuracy, vocabulary precision, sentence variety, paragraph cohesion, and text structure. Completing all seven passes demonstrates the full Phase 2 writing knowledge and process repertoire."}])},9:{Monday:g("Language devices: full year review","Writing — Vocabulary (Knowledge) & Composing (Practice): students review and apply all language devices from across the year — simile, metaphor, personification, onomatopoeia, alliteration, assonance — in a single creative or descriptive task.",{title:"I Do — The Language Device Toolkit",instruction:"Over the year we've built a full language device toolkit. Watch me use all six in a single descriptive paragraph.",example:'Simile: "like a cracked bell" | Metaphor: "the wind was a blade" | Personification: "the mountain watched, indifferent" | Onomatopoeia: "the creek gurgled and hissed" | Alliteration: "silver, slippery stones" | Assonance: "the cold, old stone"',demonstration:'Describing a mountain stream: "The creek gurgled over silver, slippery stones (alliteration + onomatopoeia), its voice like a cracked bell in the cold air (simile). The wind was a blade (metaphor), cutting across the water while the mountain watched, indifferent to the cold, old stone beneath our feet (personification + assonance)."',tip:"Don't force all six into every piece. Choose the devices that serve the moment. One well-chosen metaphor beats five forced similes."},{title:"We Do — Device Hunt",instruction:"Identify every language device in this passage and name it.",sentences:["The sea groaned and crashed against the basalt cliffs. It was a sleeping giant, slow to wake but terrible in its anger. The white froth hissed and spat. The cliffs stood — ancient, unyielding, unmoved. Above them, a single tūī stitched its song through the salt-bitter air."],prompt:"How many devices can you find? What effect does each one create?"},{title:"You Do — Your Turn",instruction:"Write a descriptive paragraph of 5–6 sentences about a NZ natural setting. Include at least four different language devices. Label each one.",tasks:["Setting options: Milford Sound | Mount Taranaki | a Northland beach at dusk | a Canterbury nor'wester","✦ Requirement: at least one metaphor or personification, at least one simile, at least one sound device (onomatopoeia, alliteration, or assonance).","✦ Bonus: Write the same description without any language devices. Compare. Which is more vivid? Which works harder for the reader?"]},[{code:"Writing — Vocabulary (Knowledge)",label:"Language devices: full year review",detail:"NZC Phase 2 Writing — Vocabulary (Knowledge): Students consolidate their knowledge of all language devices covered across the year: simile (comparison using like/as), metaphor (direct comparison), personification (human qualities to non-human things), onomatopoeia (words that imitate sounds), alliteration (repeated consonant sounds), and assonance (repeated vowel sounds). Each device creates a specific effect — students learn to name, identify, and evaluate them as tools for purposeful use."},{code:"Writing — Composing (Practice)",label:"Language devices as composing tools",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use language devices to create specific effects and engage the reader." This culminating lesson establishes the principle that guides all language device use: choose the device that serves the moment and the atmosphere. The discipline is selectivity — knowing all six devices but using only those that genuinely enhance the writing, rather than applying them mechanically for their own sake.'}]),Tuesday:g("Grammar: year review challenge","Writing — Sentence Structure (Knowledge): students demonstrate mastery of all grammar concepts from across the year in a comprehensive grammar review challenge.",{title:"I Do — The Year in Grammar",instruction:"Let me show every grammar concept we've covered this year — one example per concept.",example:"Word classes | Noun types | Verb forms | Tense | SVA | Adjectives | Adverbs | Pronouns | Conjunctions | Passive | Gerunds",demonstration:`"A flock of kererū (collective noun) has been sighted (passive, present perfect) in the pōhutukawa. Each bird (SVA: singular) feeds voraciously on the ripest fruit (superlative). Protecting (gerund subject) this species requires urgent action, although (subordinating conj.) funding remains limited (modal absent — contrast with 'must'). Neither the government nor the community (neither/nor SVA) has yet committed sufficiently."`,tip:"Grammar is always in service of meaning. Every rule exists to help writers communicate more clearly and precisely."},{title:"We Do — Grammar Challenge Round",instruction:"I'll call out a sentence. You identify every grammar feature named. Hands up, explain the rule, give an example.",sentences:['"The committee, which had been deliberating for weeks, finally reached its decision." — find: relative clause, SVA, pronoun.','"Reducing carbon emissions requires immediate and substantial intervention." — find: gerund subject, adjectives, formal vocabulary.','"Although progress had been made, the situation remained critical." — find: past perfect, subordinating conjunction, fronted clause.'],prompt:"Can you name the rule for each feature? Can you write your own example?"},{title:"You Do — Your Turn",instruction:"Write sentences that demonstrate each grammar feature.",tasks:['Write a sentence using a relative clause with "which" (remember the commas).',"Write a sentence with a gerund subject and a modal verb.","Write a sentence using past perfect to show backstory.","Write a compound-complex sentence (at least one coordinating AND one subordinating conjunction).","✦ Bonus: Write a paragraph of 6 sentences that demonstrates at least 8 different grammar concepts from across the year. Label each one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Full year grammar review",detail:"NZC Phase 2 Writing — Sentence Structure (Knowledge): Students consolidate their understanding of all grammar concepts from across the year: word classes (nouns, verbs, adjectives, adverbs, pronouns, conjunctions, prepositions), verb forms and tense (simple, progressive, perfect), subject-verb agreement (all cases), passive voice, gerunds, relative clauses, and clause types (main, subordinate, fronted). This review confirms the full range of Phase 2 sentence structure knowledge."},{code:"Writing — Sentence Structure (Practice)",label:"Integrated grammar in writing",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of word classes and structures." This year review task asks students to produce sentences that demonstrate specific grammar features on demand — moving from recognition to production, and from isolated features to integrated use within cohesive paragraphs. This is the full Phase 2 expectation for grammatical knowledge and control.'}]),Wednesday:g("Sentences: showcase and celebrate","Writing — Sentence Structure (Practice) & Composing (Practice): students write a showcase paragraph that demonstrates mastery of the full year's sentence structure, language device, and composing repertoire.",{title:"I Do — What a Year of Writing Can Do",instruction:"Watch me write a showcase paragraph that uses the best of everything we've learned this year — deliberately, purposefully, and with craft.",example:'"Deep in the Waikato basin, where the mist had not yet lifted (fronted adverbial), the kererū moved through the canopy like a purple-green shadow (simile). Ancient and unhurried (post-positive adjective), it fed on whatever the season offered (complex sentence). Protecting such a creature (gerund subject) is not merely an environmental imperative — it is a cultural one (dash + formal vocabulary). The forest has always known this (metaphor — personification). We are only beginning to catch up."',demonstration:"I've used: fronted place adverbial, simile, post-positive adjectives, complex sentence, gerund subject, dash for emphasis, formal evaluative vocabulary, personification, and a short simple sentence for impact. Each choice is deliberate — nothing is there by accident.",tip:"A showcase paragraph is not one that uses every device randomly — it's one where every choice serves the meaning."},{title:"We Do — Collaborative Showcase",instruction:"As a class, write a showcase paragraph together about a NZ place or issue. Each student contributes one sentence — choosing a different structure or device.",sentences:["Rules: no two consecutive sentences may use the same structure. Every sentence must demonstrate at least one named writing technique."],prompt:"What technique haven't we used yet? What would create the right effect here?"},{title:"You Do — Your Turn",instruction:"Write your own showcase paragraph of 6 sentences about a NZ topic you care about. After writing, annotate each sentence with the techniques you used deliberately.",tasks:["✦ Requirement: at least one fronted adverbial, one language device, one complex sentence, one simple sentence for impact, and one piece of formal evaluative vocabulary.","✦ After writing: annotate each sentence. What did you choose? Why?","✦ Bonus: Read your showcase paragraph aloud. Does every sentence feel intentional? Is there anything that feels forced or accidental? Revise until every choice is deliberate."]},[{code:"Writing — Sentence Structure (Practice)",label:"Showcase paragraph: full year integration",detail:'NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write a variety of sentence structures for effect and clarity." This culminating lesson asks students to demonstrate full command of their sentence structure repertoire in a single showcase paragraph — selecting and combining simple, compound, complex, and fronted adverbial sentences with awareness of the effect each creates. The annotation requirement makes structural choice visible and intentional.'},{code:"Writing — Composing (Practice)",label:"Deliberate composing: every choice counts",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader." The showcase paragraph is the culminating composing task of Phase 2 — it asks students to demonstrate not just that they know the techniques, but that they can deploy them purposefully, selecting each one for what it contributes to the whole. The annotation requirement ensures that composing is deliberate, not accidental.'}]),Thursday:g("Portfolio self-edit","Writing — Writing Process (Practice): students select their best piece of writing from the year, apply the full year editing checklist, and reflect on their growth as writers.",{title:"I Do — Editing Your Best Work",instruction:"The portfolio self-edit is about two things: making your best piece even better, and reflecting on how far you've come. Watch me model both.",example:"Step 1: Choose your strongest piece. Step 2: Apply the seven-pass checklist. Step 3: Reflect: what did you know how to do in Term 1 that you couldn't do before? What can you do now that you couldn't then?",demonstration:`I read my chosen piece once for overall impression. Then I apply passes 1–7 systematically. As I edit, I note: "I wouldn't have known to use a fronted adverbial here at the start of the year." "I can now identify a comma splice and fix it." The editing IS the reflection.`,tip:"Choose the piece you're most proud of — not necessarily the longest. The best piece is the one that shows who you are as a writer."},{title:"We Do — Reflection Share",instruction:"Share one sentence from your chosen piece that you're proud of. Explain: what technique did you use? Why did you choose it?",sentences:['"My best sentence this year is: ___ because ___."'],prompt:"What makes this sentence work? Which skill from this year's learning made it possible?"},{title:"You Do — Your Turn",instruction:"Complete the portfolio self-edit.",tasks:["Step 1: Choose your best piece from the year.","Step 2: Apply the 7-pass checklist. Make all corrections.","Step 3: Annotate three sentences — name the technique and why you used it.","Step 4: Write a reflection (5–6 sentences): What could you do at the start of the year? What can you do now? What are you most proud of?","✦ Bonus: Write one sentence that captures what you want to focus on as a writer in Year 7. Share it with your class."]},[{code:"Writing — Writing Process (Practice)",label:"Portfolio self-edit and reflection",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact" and to "reflect on their writing to identify strengths and areas for development." The portfolio self-edit is the culminating application of that expectation — students select, edit, annotate, and reflect on their best writing of the year, demonstrating the full Phase 2 writing process repertoire.'},{code:"Writing — Writing Process (Practice)",label:"Reflecting on growth as a writer",detail:'NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "develop awareness of their own writing process and reflect on what helps them write well." The portfolio reflection is the final step in that developmental process at Phase 2 — students identify specific skills they have gained, name the techniques they now deploy deliberately, and articulate where they want to grow. This metacognitive awareness is the foundation of becoming a lifelong writer.'}])},10:{Monday:g("Review: punctuation — year overview","Writing — Punctuation (Knowledge & Practice): students demonstrate mastery of the full year's punctuation — from basic sentence demarcation to colons, semicolons, ellipsis, and dialogue conventions — in a comprehensive final review.",{title:"I Do — The Full Punctuation Year in Review",instruction:"Let's do a rapid walkthrough of every punctuation mark we've learned this year — one example each, showing the rule.",example:"Term 1: . , ! ? ' (apostrophe) | Term 2: : ; — () fronted adverbial comma | Term 3: ... dialogue conventions | Term 4: hyphen, em dash, complex lists",demonstration:`"Before the match began, the captain spoke: 'There's only one rule — give everything you have. The rest will follow... or it won't.' The team's response was immediate; every player stood a little straighter."`,tip:"For every mark: what job is it doing? If it isn't doing a job — remove it."},{title:"We Do — Full Punctuation Audit",instruction:"Add correct punctuation to this passage and name every rule you apply.",sentences:["before the last day of term the principal called an assembly. she had three announcements the award winners the trip dates and a special surprise. isnt it funny she said how quickly a year goes. the students looked at each other. some smiled some groaned but all of them knew she was right. the year had been short its challenges and all"],prompt:"Which marks are needed and why? How many different types can you use correctly?"},{title:"You Do — Your Turn",instruction:"Write a passage of 6–8 sentences that uses every punctuation type from the year at least once. Label each mark and its rule.",tasks:["✦ Required marks: . , ! ? apostrophe (possession) apostrophe (contraction) : ; — () ... speech marks hyphen","✦ Every mark must be doing a genuine job — not added just to tick the box.","✦ Bonus: Write a brief explanation (3–4 sentences) of which punctuation mark you find most useful as a writer, and why."]},[{code:"Writing — Punctuation (Knowledge)",label:"Full year punctuation review",detail:"NZC Phase 2 Writing — Punctuation (Knowledge): Students demonstrate mastery of the complete punctuation repertoire covered across the year: sentence-end punctuation (. ! ?), commas (lists, fronted adverbials, complex sentences), apostrophes (possession — singular, plural, irregular; contraction; not for plurals), colon (before lists and explanations), semicolon (between related clauses; in complex lists), dash (emphasis and aside), brackets (parenthetical information), ellipsis (suspense, trailing, hesitation), dialogue conventions, and hyphen. This is the full Phase 2 punctuation knowledge base."},{code:"Writing — Punctuation (Practice)",label:"Full year punctuation in writing",detail:'NZC Phase 2 Writing — Punctuation (Practice): Students are expected to "use a range of punctuation accurately and for effect." The final punctuation review asks students to demonstrate not just knowledge of rules but purposeful application — every mark must be doing a job. This is the culminating punctuation standard at Phase 2: accurate, varied, and deliberate use of the full punctuation repertoire across a range of text types.'}]),Tuesday:g("Grammar: year overview","Writing — Sentence Structure (Knowledge): students demonstrate the full year's grammar knowledge in a final comprehensive overview, connecting each concept to its effect on meaning and reader experience.",{title:"I Do — Grammar Is Meaning",instruction:"Every grammar rule exists to help writers communicate more clearly and precisely. Watch me connect each concept to the meaning it creates.",example:"Word classes → word choice. Tense → when. SVA → accuracy. Passive → focus. Gerunds → formality. Relative clauses → embedded detail. Modals → certainty.",demonstration:'"The committee, which had deliberated for weeks (relative clause — embedded detail), finally announced its decision (passive — focus on decision, not committee). Implementing (gerund subject — formal) such a policy would require substantial (evaluative adjective) funding. Neither the opposition nor the public (neither/nor SVA) has been fully consulted." Every grammar choice shapes meaning.',tip:"Grammar is not a set of rules to follow mechanically — it's a set of tools to use purposefully. Every choice communicates something."},{title:"We Do — Grammar-Meaning Connection",instruction:"For each sentence, identify the grammar feature and explain what it communicates to the reader.",sentences:['"Protecting our waterways must be an urgent national priority." — What does the gerund subject + modal communicate?','"The decision was made without community consultation." — What does the passive communicate? What is deliberately omitted?','"Although progress has been made, significant challenges remain." — What does the complex sentence with past perfect + present communicate?'],prompt:"It's not just what grammar feature is used — it's what it means for the reader."},{title:"You Do — Your Turn",instruction:"Write sentences that demonstrate mastery of the year's grammar, with annotations.",tasks:["Write a sentence that uses passive voice for a specific reason. Explain why.","Write a sentence with a gerund subject and evaluate its effect on formality.","Write a compound-complex sentence about a NZ issue. Label both the coordinating and subordinating conjunctions.","Write a sentence using the past perfect to show something happened before another past event.","✦ Bonus: Write a paragraph of 6 sentences on the importance of te reo Māori. Demonstrate at least 8 different grammar concepts. Label every one."]},[{code:"Writing — Sentence Structure (Knowledge)",label:"Full year grammar overview",detail:"NZC Phase 2 Writing — Sentence Structure (Knowledge): This final review consolidates the complete Phase 2 grammar repertoire: all word classes and their functions, verb forms and tense (simple, progressive, perfect), subject-verb agreement (all cases including neither/nor, collective nouns, inverted sentences), passive voice, gerunds as subjects, relative clauses, modal verbs, adjective placement, and all conjunction types (coordinating and subordinating). Students connect each concept to its communicative function, completing the Phase 2 knowledge framework."},{code:"Writing — Sentence Structure (Practice)",label:"Grammar as a meaning-making tool",detail:`NZC Phase 2 Writing — Sentence Structure (Practice): Students are expected to "write grammatically correct sentences using a range of word classes and structures" with awareness of the effect each structural choice has on meaning and reader experience. This final lesson establishes the key insight of Phase 2 grammar learning: every grammatical choice communicates something specific — about time, certainty, focus, formality, and logical relationship. Grammar is not a constraint — it is the writer's toolkit for precise communication.`}]),Wednesday:g("Sentence mastery: year showcase","Writing — Sentence Structure (Practice) & Composing (Practice): students write a final showcase paragraph demonstrating mastery of the full year's sentence structure, language device, and composing repertoire — then peer review each other's work.",{title:"I Do — The Year in One Paragraph",instruction:"The final showcase: one paragraph that demonstrates everything a Year 5–6 writer can do. Watch me compose one with full annotation.",example:'"In the silence before dawn (fronted place adverbial), Aotearoa holds its breath. The hills are ancient sentinels (metaphor), watching — always watching (personification + dash). Although the world rushes past (fronted complex sentence), something here remains unchanged: the light on the water, the call of the tūī, the slow turning of the seasons (colon + tricolon). Protecting this (gerund subject) is not optional; it is essential (semicolon + evaluative vocabulary)."',demonstration:"Seven named techniques in five sentences. Every one deliberate. The paragraph is about something real. The techniques serve the meaning — they don't decorate it.",tip:"The best showcase paragraph is the one that sounds most like you — while demonstrating full command of your craft toolkit."},{title:"We Do — Peer Review the Showcase",instruction:"Read your partner's showcase paragraph. Identify every named technique. Write specific feedback.",sentences:[`Feedback framework: "I noticed you used ___ in sentence ___. The effect this creates is ___. One technique I'd love to see is ___ — it would work well in ___ place."`],prompt:"Be specific. Name the technique, name the sentence, explain the effect."},{title:"You Do — Your Turn",instruction:"Write your final Year 5–6 showcase paragraph. After writing, complete the annotation.",tasks:["Topic: something about Aotearoa that matters to you.","Length: 5–7 sentences.","✦ Required: at least 6 named techniques from across the year — annotated.","✦ After peer review: revise one sentence based on your partner's feedback.","✦ Final step: write one sentence that describes what kind of writer you want to be in Year 7."]},[{code:"Writing — Sentence Structure (Practice)",label:"Final showcase: sentence mastery",detail:"NZC Phase 2 Writing — Sentence Structure (Practice): This culminating showcase task asks students to demonstrate the full Phase 2 sentence structure repertoire in a single, cohesive, annotated paragraph — selecting sentence types, fronted adverbials, language devices, and punctuation marks for their effect on meaning and reader experience. The annotation and peer review ensure that structural choices are deliberate, named, and connected to purpose."},{code:"Writing — Composing (Practice)",label:"Final showcase: composing mastery",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "use composing strategies to create texts that engage the reader" and to "reflect on their writing to identify strengths and areas for development." The final showcase is the culminating composing task of Phase 2 — it asks students to demonstrate that they can write with full deliberate craft, receive and act on feedback, and articulate a vision for their own continuing development as writers.'}]),Thursday:g("End-of-year celebration edit","Writing — Writing Process (Practice): students complete a final celebration edit of their favourite piece of writing from the year, share it with the class, and celebrate their growth as writers.",{title:"I Do — The Celebration Edit",instruction:"The final lesson of the year. Today we celebrate by applying everything we know to a piece of writing we love — then sharing it.",example:"Step 1: Choose your favourite piece from the year — not necessarily your best, but the one you love most. Step 2: Apply your final edit — make it as good as it can be. Step 3: Read it aloud to at least one person. Step 4: Celebrate.",demonstration:"I'll read my chosen piece, explain why I chose it, and share one thing I changed in the final edit and why. Then I'll explain what I want to write in Year 7.",tip:"Good writing is never finished — it's abandoned at the right moment. Today is that moment. Edit until you're proud, then stop."},{title:"We Do — Gallery Share",instruction:"Each student reads their favourite sentence from their chosen piece. The class listens and names one technique they noticed.",sentences:['"My favourite sentence this year: ___"','"The technique I used deliberately: ___"','"What I want to write next year: ___"'],prompt:"Listen generously. Name something specific that you admire."},{title:"You Do — Your Turn",instruction:"Complete the final celebration edit and sharing.",tasks:["Step 1: Choose your favourite piece. Edit it to your very best.","Step 2: Annotate three sentences with the technique used and why.",`Step 3: Write a "writer's statement" — 3 sentences: (1) What I can do now that I couldn't at the start of Year 5/6. (2) The writing technique I'm most proud of mastering. (3) What I want to do next as a writer.`,"Step 4: Share your favourite sentence with the class.","✦ Bonus: Write one piece of advice about writing that you'd give to a Year 4 student starting Year 5 next year."]},[{code:"Writing — Writing Process (Practice)",label:"Celebration edit and final reflection",detail:`NZC Phase 2 Writing — Writing Process (Practice): Students are expected to "reread and revise their writing… making changes to vocabulary, punctuation, and structure to improve clarity and impact" and to "develop awareness of their own writing process and reflect on what helps them write well." The celebration edit is the final application of these expectations at Phase 2 — students apply the full year's editing knowledge to a piece they care about, and reflect meaningfully on their identity and growth as writers.`},{code:"Writing — Composing (Practice)",label:"Writers sharing their work",detail:'NZC Phase 2 Writing — Composing (Practice): Students are expected to "share writing with others and respond to feedback to improve their work." The celebration share is the culminating expression of that expectation — students read their own writing aloud with confidence, receive specific and generous feedback, and articulate their identity as writers. This is the full realisation of Phase 2 composing development: students who know what they can do, who are proud of their craft, and who are ready to keep writing.'}])}}}};
